/* ================================================================
   * Currents and Critters, multiplayer client
   * Gameplay: fish_game_all_in_one.py + multiplayer_server.py
   * ================================================================ */

  window.__FISH_API_BASE__ = "https://play.currentsandcritters.com";
  const CARD_IMAGE_VERSION = "20260730-v12c";

  // ── App version + update detection ──────────────────────────────────────
  // APP_VERSION → shown in the Beta badge ("BETA V<APP_VERSION>").
  // Versioning scheme: 1.<2nd>.<3rd> derived from the cumulative update count N.
  //   3rd digit = floor(N/10) % 10  → ticks up every 10 pushes
  //   2nd digit = floor(N/100)      → ticks up every 100 pushes
  //   1st digit = major version     → bumped only for a major release (by request)
  // e.g. update #350 → 1.3.5. Current update count N ≈ 353 → 1.3.5.
  // APP_BUILD → MUST stay equal to the "build" in /client/version.json. The client
  // polls version.json and prompts a one-tap refresh when the served build differs;
  // if these two drift apart, refreshed clients get stuck re-prompting forever.
  const APP_VERSION = "1.7.1";
  const APP_BUILD   = "2026-09-01.7";

  // ── Progress that is filed on the DEVICE, not on an account ─────────────
  // The challenge slots, the win streaks, the opponents you have met, the
  // strategies you have played, the unseen-critter dots and the undelivered
  // unlock notifications all live in localStorage: they are running totals
  // nothing asks a server about mid-game.
  //
  // They used to live under ONE key each, shared by whoever happened to be
  // sitting at this browser. Signing out of an account and tapping PLAY AS
  // GUEST therefore opened onto that account's half-finished dailies, its win
  // streaks and its pending unlock toasts, because none of it was ever filed
  // under a name.
  //
  // Now the key carries whose it is. Two rules make the change free:
  //   • An ACCOUNT with progress under the old shared key adopts it once, so
  //     nobody loses a streak or a day of challenges on the way to this fix.
  //   • A GUEST never adopts anything. That is the entire point.
  const CC_SCOPED_KEYS = [
    "cc_daily_state_v1", "cc_weekly_state_v1", "cc_streak_v1",
    "cc_seen_opponents_v1", "cc_active_strats", "cc_strat_play_counts",
    "cc_new_avatars", "cc_notif_queue",
  ];
  function ccScopedKey(base) {
    let who = "";
    try { who = String((window.__ccIdentityName && window.__ccIdentityName()) || ""); } catch (_) { who = ""; }
    // Before anybody has signed in there is nothing to keep apart, so the bare
    // key is used and the adoption below never runs.
    if (!who) return base;
    const key = base + "::" + who;
    // One-time adoption of pre-scoping progress, for accounts only.
    try {
      if (who.startsWith("acct:") && localStorage.getItem(key) === null) {
        const legacy = localStorage.getItem(base);
        if (legacy !== null) localStorage.setItem(key, legacy);
      }
    } catch (_) {}
    return key;
  }
  window.__ccScopedKey = ccScopedKey;

  // ── Profanity guard (chat + nicknames) ──────────────────────────────────
  // Keeps chat family-friendly and blocks offensive nicknames. Chat swears are
  // masked with asterisks; offensive nicknames are rejected outright. Two match
  // modes (kept in sync with _censor_profanity in multiplayer_server.py, which
  // re-filters chat server-side so a swear can never reach another player):
  //   • STRONG roots, matched ANYWHERE, tolerant of leetspeak, repeated
  //     letters and separator evasion (f u c k, f-u-c-k, f*u*c*k, sh1t, phuck…).
  //   • WORD roots, short words that also live inside innocent words (ass in
  //     "class", cock in "peacock"), matched ONLY as a whole word (avoids the
  //     "Scunthorpe problem").
  const CC_PROFANITY = (function () {
    const LEET = {
      a: "a4@", b: "b8", c: "c(", e: "e3", g: "g9", i: "i1!|",
      l: "l1|", o: "o0", s: "s5$", t: "t7+", u: "uv", z: "z2",
    };
    const cls = (ch) => "[" + (LEET[ch] || ch).replace(/[-\\\]^]/g, "\\$&") + "]";
    const strongPat = (w) => w.split("").map((c) => cls(c) + "+").join("[\\s._*\\-]{0,2}");
    const wordCore  = (w) => w.split("").map((c) => cls(c) + "+").join("") + "(?:es|[sz])?";
    const STRONG = ["fuck","phuck","shit","bitch","biotch","beotch","cunt",
      "asshole","dickhead","bastard","bollock","wanker","pussy","slut","whore",
      "faggot","nigger","nigga","retard","cocksucker","motherfucker","bullshit",
      "dumbass","jackass","dipshit","jerkoff","goddamn","douchebag","blowjob",
      "handjob","dildo","boner","penis","vagina"];
    const WORDS = ["ass","arse","damn","hell","crap","piss","cock","dick","tit",
      "prick","twat","wank","hoe","homo","queer","coon","chink","spic","kike",
      "gook","dyke","fag","skank","sex","porn","cum","anal","boob","bloody",
      "bugger","douche","wtf","stfu"];
    const strongSrc = STRONG.map(strongPat).join("|");
    const wordSrc   = "(^|[^a-z0-9])(" + WORDS.map(wordCore).join("|") + ")(?=[^a-z0-9]|$)";
    const strongRe  = () => new RegExp("(" + strongSrc + ")", "gi");
    const wordRe    = () => new RegExp(wordSrc, "gi");
    const strongTest = new RegExp(strongSrc, "i");
    const wordTest   = new RegExp(wordSrc, "i");
    const deSep = (s) => String(s == null ? "" : s).replace(/[\s._\-]+/g, "");
    function hasProfanity(text) {
      const raw = String(text == null ? "" : text);
      const packed = deSep(raw);
      return strongTest.test(raw) || strongTest.test(packed)
          || wordTest.test(raw)  || wordTest.test(packed);
    }
    function clean(text) {
      let out = String(text == null ? "" : text);
      out = out.replace(strongRe(), (m) => "*".repeat(m.length));
      out = out.replace(wordRe(), (full, pre, body) => pre + "*".repeat(body.length));
      return out;
    }
    return { hasProfanity, clean };
  })();

