  // ── New Current Modal ──────────────────────────────────────────
  let _ncIsCompetitive = false; // tracks whether the modal was opened for a competitive 1v1 game
  let _ncIsRanked = false;      // tracks whether the modal was opened for a Competitive (free-for-all) game
  let _ncMode = "normal";       // 'normal' | 'ranked' | 'competitive' | 'team'
  let _ncTeamCount = 2;         // 2..4 (team mode only)
  // Apply the chosen Mode to the setup modal.
  //  • Normal     : a fully customizable game (all settings editable).
  //  • Ranked     : "Competitive", an ordinary 3–8 player game that pays
  //    Ocean Points. People only, so the AI field is pinned to 0 and
  //    disabled; humans + privacy stay editable within 3–8. Three people is
  //    the mode's floor, not just the payout's (see COMP_FFA_MIN_PLAYERS): a
  //    two-person table here is Competitive 1v1 with extra steps, so the count
  //    can never be set below it, here or in the lobby's Table Setup.
  //  • Competitive: a locked "quick-match" ranked 1v1: 4 humans (2 hands
  //    each), 0 AI, public match. Those settings are fixed + disabled so the
  //    host only has to press the main button to continue.
  //  • Team       : a normal, fully-editable game played in 2–4 teams. Adds a
  //    Teams selector; humans/AI/privacy stay editable like Normal.
  // Accepts a mode string; legacy callers may still pass a boolean (isComp).
  function applyNcMode(mode) {
    if (mode === true) mode = "competitive";
    else if (mode === false || mode == null) mode = "normal";
    if (mode !== "competitive" && mode !== "team" && mode !== "ranked") mode = "normal";
    _ncMode = mode;
    _ncIsCompetitive = (mode === "competitive");
    _ncIsRanked = (mode === "ranked");
    const isTeam  = (mode === "team");
    const box     = document.getElementById("new-current-box");
    const totalEl = document.getElementById("nc-total");
    const aiEl    = document.getElementById("nc-ai");
    const visEl   = document.getElementById("nc-visibility");
    const modeEl  = document.getElementById("nc-mode");
    const teamsField = document.getElementById("nc-field-teams");
    const teamCountEl = document.getElementById("nc-team-count");
    const titleEl = document.getElementById("nc-modal-title");
    if (modeEl)  modeEl.value = mode;
    if (box)     box.classList.toggle("nc-comp", _ncIsCompetitive || _ncIsRanked);
    if (box)     box.classList.toggle("nc-team", isTeam);
    if (titleEl) titleEl.textContent = _ncIsCompetitive
      ? "⚔️ Competitive 1v1, 2 hands per player"
      : _ncIsRanked
      ? `🏅 Competitive, people only, ${COMP_FFA_MIN_PLAYERS}+ for OP`
      : (isTeam ? "🤝 New Team Current" : "🌊 New Current");
    if (teamsField) teamsField.style.display = isTeam ? "" : "none";
    if (isTeam && teamCountEl) _ncTeamCount = Math.max(2, Math.min(4, Number(teamCountEl.value) || 2));
    const lock = (fieldId, el, on) => {
      const f = document.getElementById(fieldId);
      if (f)  f.classList.toggle("nc-locked", on);
      if (el) el.disabled = on;
    };
    // Every mode but Competitive (free-for-all) allows a table from 1 human up,
    // so the floor is reset here and raised again inside that one branch: a
    // host who tries Competitive and then switches back to Normal must not be
    // left with Competitive's minimum on the field.
    if (totalEl) totalEl.min = "1";
    if (_ncIsCompetitive) {
      if (totalEl) totalEl.value = "4";
      if (aiEl)    aiEl.value    = "0";
      if (visEl)   visEl.value   = "public";
      document.getElementById("nc-password-row").style.display = "none";
      document.getElementById("nc-password").value = "";
    } else if (_ncIsRanked) {
      // People only. The AI field is pinned to 0 and locked below; the human
      // count opens at 4 and stays the host's to set, anywhere from
      // COMP_FFA_MIN_PLAYERS to 8. The field's own min moves with the mode so
      // the number spinner can't step under the floor either.
      if (aiEl) aiEl.value = "0";
      const _humans = Number(totalEl && totalEl.value) || 0;
      if (totalEl) totalEl.min = String(COMP_FFA_MIN_PLAYERS);
      if (totalEl && (_humans < COMP_FFA_MIN_PLAYERS || _humans > 8)) totalEl.value = "4";
    } else if (isTeam) {
      // A team game defaults to 4 humans so 2 teams start 2-v-2, but stays editable.
      if (totalEl && (Number(totalEl.value) || 0) < 2) totalEl.value = "4";
    } else {
      // Back to a fresh, fully-editable Normal game.
      if (totalEl) totalEl.value = "2";
      if (aiEl)    aiEl.value    = "0";
    }
    // Competitive 1v1 locks every base setting; Competitive (free-for-all)
    // locks only the bot count (that IS the mode's rule); Team leaves them all
    // editable.
    lock("nc-field-humans",  totalEl, _ncIsCompetitive);
    lock("nc-field-ai",      aiEl,    _ncIsCompetitive || _ncIsRanked);
    lock("nc-field-privacy", visEl,   _ncIsCompetitive);
  }

  function openNewCurrentModal(opts) {
    document.getElementById("nc-current-err").textContent = "";
    document.getElementById("nc-password-row").style.display = "none";
    document.getElementById("nc-password").value = "";
    document.getElementById("nc-visibility").value = "public";
    applyNcMode((opts && opts.competitive) ? "competitive"
              : (opts && opts.ranked)       ? "ranked"
              : (opts && opts.team)         ? "team" : "normal");
    const _ncBtn = document.getElementById("nc-create-btn");
    _ncBtn.disabled = false;
    _ncBtn.classList.remove("generating");
    const _ncLabel = _ncBtn.querySelector(".nc-btn-label");
    if (_ncLabel) _ncLabel.textContent = "Generate Current →";
    document.getElementById("new-current-modal").classList.add("open");
  }
  function closeNewCurrentModal() {
    document.getElementById("new-current-modal").classList.remove("open");
  }
  // Mode selector: switch between Normal / Competitive / Team on the fly.
  document.getElementById("nc-mode").addEventListener("change", (e) => {
    // Tournament Mode takes over its own create flow (its own overlay). Reset the
    // base modal's mode to Normal so cancelling returns cleanly.
    if (e.target.value === "tournament" && window.__ccTourney && window.__ccTourney.ENABLED) {
      e.target.value = "normal";
      applyNcMode("normal");
      document.getElementById("new-current-modal")?.classList.remove("open");
      if (typeof window.__ccTourneyOpenCreate === "function") window.__ccTourneyOpenCreate();
      return;
    }
    applyNcMode(e.target.value);
  });
  // Team count selector (2–4 teams).
  (function () {
    const tc = document.getElementById("nc-team-count");
    if (tc) tc.addEventListener("change", (e) => {
      _ncTeamCount = Math.max(2, Math.min(4, Number(e.target.value) || 2));
    });
  })();

  // ── Giant Squid challenge: a 1v1 vs-AI match. Winning unlocks the Sea
  // Anemone + the "It Is Finally Over" achievement (+1000 XP). ─────────
  let _giantSquidChallengeActive = false;
  let _giantSquidChallengeRoom = "";
  async function _startGiantSquidChallenge() {
    const name = (window.__fishNickname && window.__fishNickname()) || "Challenger";
    const rid = "SQUID" + Math.random().toString(36).slice(2,5).toUpperCase();
    const createKey = `ck_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
    try { localStorage.setItem(createKeyKey(), createKey); } catch {}
    const r = await apiPost("/api/rooms", {
      create_key: createKey, host_name: name, room_id: rid,
      total_players: 2, human_players: 1, ai_players: 1,
      replace_active: false, visibility: "private", password: rid,
      competitive: false,
    }, { timeoutMs: 10000 });
    if (!r.ok) { try { showToast("The Giant Squid slipped away, try again.", "err"); } catch (_) {} return; }
    const rId = normalizeRoomId(r.data?.room_id || rid);
    roomId = rId;
    _giantSquidChallengeActive = true;
    _giantSquidChallengeRoom = rId;
    if (r.data?.host_token) setHostToken(r.data.host_token);
    if (r.data?.seat_token) setSeatToken(r.data.seat_token);
    _myRoomVisibility = "private"; _myRoomCode = rId;
    const badge = document.getElementById("pv-my-name-badge"); if (badge) badge.textContent = name;
    enterRoom(rId);
    showWaitingRoom(rId, true);
  }
  window.__fishStartGiantSquidChallenge = _startGiantSquidChallenge;
  // Called from saveGameStats when a game ends: if it was the challenge room
  // and the player won, grant the reward. Clears the challenge either way.
  function _resolveGiantSquidChallenge(isWinner) {
    if (!_giantSquidChallengeActive) return;
    if (roomId && _giantSquidChallengeRoom && roomId !== _giantSquidChallengeRoom) return;
    _giantSquidChallengeActive = false;
    _giantSquidChallengeRoom = "";
    if (isWinner) {
      try { window.__fishUnlockAchievementById?.("it_is_finally_over"); } catch (_) {}
      try { showToast("🦑 You beat the Giant Squid! The Red Beaded Anemone is saved.", "info", 6000); } catch (_) {}
    }
  }

  document.getElementById("nc-close").addEventListener("click", closeNewCurrentModal);
  document.getElementById("new-current-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("new-current-modal")) closeNewCurrentModal();
  });

  document.getElementById("nc-visibility").addEventListener("change", (e) => {
    document.getElementById("nc-password-row").style.display = e.target.value === "private" ? "" : "none";
    if (e.target.value !== "private") document.getElementById("nc-password").value = "";
  });

  document.getElementById("nc-create-btn").addEventListener("click", async () => {
    const btn = document.getElementById("nc-create-btn");
    const errEl = document.getElementById("nc-current-err");
    const name = (window.__fishNickname && window.__fishNickname()) || "Host";
    const isTeam = (_ncMode === "team");
    const teamCount = isTeam ? Math.max(2, Math.min(4, _ncTeamCount || 2)) : 2;
    // Competitive 1v1 games are always 4 humans (2 per player), 0 AI.
    const human = _ncIsCompetitive ? 4 : Math.max(1, Number(document.getElementById("nc-total").value) || 2);
    // Competitive (free-for-all) is people only. The server refuses bots in a
    // ranked room anyway; zeroing here means the request it refuses is never sent.
    const ai    = (_ncIsCompetitive || _ncIsRanked) ? 0 : Math.max(0, Number(document.getElementById("nc-ai").value) || 0);
    const total = human + ai;
    if (_ncIsRanked && (human < COMP_FFA_MIN_PLAYERS || human > 8)) {
      errEl.textContent = `A competitive game needs ${COMP_FFA_MIN_PLAYERS} to 8 people.`;
      return;
    }
    // Team games need enough seats (players + bots) to fill every team.
    if (isTeam && total < teamCount) {
      document.getElementById("nc-current-err").textContent =
        `${teamCount} teams need at least ${teamCount} players or bots, add more seats.`;
      return;
    }
    // Tutorial flag is a one-shot set by "The Game" tour; consume it here so a
    // later manual create is never mis-flagged as a tutorial game.
    const _isTutGame = (window.__ccTutorialGame === true);
    window.__ccTutorialGame = false;
    // Tutorial variant ("blob" = B-Lob Strategy tutorial) tells the server which
    // opening-hand rig to apply. One-shot, consumed here like the tutorial flag.
    const _tutVariant = _isTutGame ? String(window.__ccTutorialVariant || "") : "";
    window.__ccTutorialVariant = "";
    let visibility = document.getElementById("nc-visibility").value;
    let password = "";
    let rid = Math.random().toString(36).slice(2,7).toUpperCase();
    if (visibility === "private") {
      const rawPw = document.getElementById("nc-password").value.trim();
      if (!rawPw) { errEl.textContent = "Enter a code for the private Current."; return; }
      const code = normalizeRoomCode(rawPw);
      if (!code) { errEl.textContent = "Code must be 4–12 letters or numbers (no spaces or symbols)."; return; }
      // The private code IS both the join code and the password.
      rid = code;
      password = code;
    }
    if (_isTutGame) {
      // A tutorial room is always PRIVATE, so it never appears in Open Currents
      // and no real player can join and scramble the guided turn.
      //
      // Its code is the same shape as any other: 5 characters. It used to be
      // "TUT" plus a base-36 timestamp sliced to the 12-char maximum, which the
      // waiting room then displayed at over twice the length of a real code, in
      // every tutorial, as the first room code most people ever saw. Being
      // private is what keeps strangers out, not the length of the name.
      //
      // And when the tutorial has just SHOWN the player a code (Online Play &
      // Controls stops on the code box to say "this is your room code"), that
      // is the code the room gets: rid already holds it, normalized and
      // validated by the private branch above. Overriding it unconditionally
      // put a different code on the very next screen.
      const tutKeepsTypedCode = (visibility === "private");
      visibility = "private";
      if (!tutKeepsTypedCode) rid = freshRoomCode(5);
      password = rid;
    }
    _myRoomVisibility = visibility;
    _myRoomCode = password;
    const createKey = `ck_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
    try { localStorage.setItem(createKeyKey(), createKey); } catch {}
    btn.disabled = true;
    btn.classList.add("generating");
    const _ncBtnLabel = btn.querySelector(".nc-btn-label");
    if (_ncBtnLabel) _ncBtnLabel.textContent = "Generating…";
    errEl.textContent = "";
    let r;
    try {
      r = await apiPost("/api/rooms", {
        create_key: createKey, host_name: name, room_id: rid,
        total_players: total, human_players: human, ai_players: ai,
        replace_active: false, visibility, password,
        competitive: _ncIsCompetitive, ranked: _ncIsRanked,
        tutorial: _isTutGame, tutorial_variant: _tutVariant,
        team: isTeam, team_count: teamCount,
      }, { timeoutMs:10000 });
    } catch (e) {
      btn.disabled = false;
      btn.classList.remove("generating");
      if (_ncBtnLabel) _ncBtnLabel.textContent = "Generate Current →";
      ccReport("room_create_failed", {
        source: "new_current",
        visibility,
        total,
        ai,
        competitive: _ncIsCompetitive ? "1" : "0",
        tutorial: _isTutGame ? "1" : "0",
        error: e && (e.name || e.message || e)
      }, "error");
      errEl.textContent = "Failed, check your connection and try again.";
      try { showToast("Create failed, check your connection.", "err"); } catch (_) {}
      return;
    }
    btn.disabled = false;
    btn.classList.remove("generating");
    if (_ncBtnLabel) _ncBtnLabel.textContent = "Generate Current →";
    if (!r.ok) {
      ccReport("room_create_failed", {
        source: "new_current",
        visibility,
        total,
        ai,
        competitive: _ncIsCompetitive ? "1" : "0",
        tutorial: _isTutGame ? "1" : "0",
        status: r.status,
        error: r.data?.error || ""
      }, "warn");
      errEl.textContent = "Failed: " + (r.data?.error || r.status); return;
    }
    const rId = normalizeRoomId(r.data?.room_id || rid);
    roomId = rId;
    if (r.data?.host_token) setHostToken(r.data.host_token);
    if (r.data?.seat_token) setSeatToken(r.data.seat_token);
    document.getElementById("pv-my-name-badge").textContent = name;
    closeNewCurrentModal();
    // Competitive: claim seat 1 for P1's second hand, then enter as comp mode.
    if (_ncIsCompetitive) {
      const hToken = r.data?.host_token || "";
      const seat0Tok = r.data?.seat_token || "";
      const j1 = await apiPost(`/api/rooms/${rId}/join`, { player_name: name + " 2", seat_index: 1, host_token: hToken }, { timeoutMs: 8000 });
      if (j1.ok) {
        const tokens = { 0: seat0Tok, 1: j1.data?.seat_token || "" };
        compMode = true; compMySeats = [0, 1]; compTokens = tokens;
        compHostToken = hToken; compHandNames = {};
        compP1Name = name; compP2Name = "Player 2";
        try { sessionStorage.setItem(`fish_comp_seats_${rId}_0`, JSON.stringify({ seats: [0,1], tokens, p1: name, p2: "Player 2" })); } catch {}
      } else {
        // Seat 1 is this player's SECOND hand. If claiming it failed the room is
        // a hand short, it can never reach 4 players to start, and a stranger
        // could sit in the hand that was meant to be theirs. Say so rather than
        // dropping them into a lobby that quietly never starts.
        try { showToast("Could not claim your second hand: close this Current and create a new one.", "err", 7000); } catch (_) {}
      }
    }
    enterRoom(rId);
    showWaitingRoom(rId, true);
  });

  // ── Seat Picker Modal (for joining public rooms from lobby browser) ──
  let _spPendingRid = null;
