  // ── Draw-over-10 warning modal handlers ────────────────────────
  function closeDrawWarn() {
    document.getElementById("draw-warn-modal").classList.remove("open");
  }
  document.getElementById("draw-warn-cancel").addEventListener("click", () => {
    closeDrawWarn();
    _pendingDrawAction = null;
    selectedPool.clear();
    if (latestPayload) renderPayload(latestPayload);
    setStatus("Draw cancelled, your turn continues.");
  });
  document.getElementById("draw-warn-confirm").addEventListener("click", () => {
    closeDrawWarn();
    const act = _pendingDrawAction;
    _pendingDrawAction = null;
    if (!act) return;
    _drawWarnBypass = true;
    submitAction(act);
  });
  // Clicking the dim backdrop = cancel
  document.getElementById("draw-warn-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("draw-warn-modal")) {
      document.getElementById("draw-warn-cancel").click();
    }
  });

  document.getElementById("sp-join-btn").addEventListener("click", async () => {
    if (_spSelectedSeat === null || !_spPendingRid) return;
    const rid = _spPendingRid;
    const name = (window.__fishNickname && window.__fishNickname()) || "Player";
    const btn = document.getElementById("sp-join-btn");
    btn.disabled = true; const _spTxtJ = document.getElementById("sp-join-text"); if (_spTxtJ) _spTxtJ.textContent = "Joining…";
    const j = await apiPost(`/api/rooms/${rid}/join`, { player_name: name, seat_index: _spSelectedSeat }, { timeoutMs:12000 });
    if (!j.ok) {
      document.getElementById("seat-picker-err").textContent = "Join failed: " + (j.data?.error || j.status);
      btn.disabled = false; const _spTxtR = document.getElementById("sp-join-text"); if (_spTxtR) _spTxtR.textContent = `Join as Seat ${_spSelectedSeat + 1} →`;
      return;
    }
    roomId = rid; // must be set before setSeatToken (which keys by roomId)
    if (j.data?.seat_token) setSeatToken(j.data.seat_token);
    document.getElementById("pv-my-name-badge").textContent = name;
    closeSeatPickerModal();
    showToast("Joined! Waiting for host to start…", "ok");
    enterRoom(rid);
  });

  // ── Action submission ──────────────────────────────────────────
  let actionInFlight = false;
  let pendingPayAction = null; // action staged waiting for payment card selection
  const selectedPayment = new Set();
  const selectedDiscard = new Set();
  const selectedPool    = new Set();
  let handEntryMap = new Map();

  function updatePaymentModeUI() {
    const bar         = document.getElementById("pv-payment-mode-bar");
    const playCtrl    = document.getElementById("pv-play-controls");
    const payInfo     = document.getElementById("pv-payment-info");
    const confirmBtn  = document.getElementById("pv-payment-confirm-btn");
    const txt         = document.getElementById("pv-payment-mode-text");
    if (!bar) return;
    if (!pendingPayAction) {
      bar.style.display = "none";
      if (playCtrl) playCtrl.style.display = "flex";
      return;
    }
    bar.style.display = "flex";
    if (playCtrl) playCtrl.style.display = "none";
    const cost    = Number(pendingPayAction.cost_to_pay || 0);
    const name    = pendingPayAction.face_name || "card";
    const star    = starPayInfo(pendingPayAction);
    // Only the ★ variant needs a matching symbol. On a plain play the symbol is
    // irrelevant (the engine will not fire the star), so never ask for one.
    const symHint = star.fires ? `, include a ${star.sym} card for the ★` : "";
    const sel     = selectedPayment.size;
    const need    = cost - sel;
    if (txt) {
      let msg = sel >= cost
        ? `✓ Ready, ${cost} card${cost!==1?"s":""} selected to pay for ${name}`
        : `Playing ${name}, click or hover a card and tap "Use as Payment" (${need} more needed${symHint})`;
      if (star.fires && sel >= cost) {
        const ok = Array.from(selectedPayment).some(uid => entryHasSymbolMatch(uid, star.sym));
        msg += ok
          ? ` ★ ${star.ability || "star ability"} will fire`
          : ` no ${star.sym} card selected, the ★ will NOT fire`;
      } else if (star.offered) {
        msg += `: ★ is off, playing without ${star.ability ? `"${star.ability}"` : "the star ability"}`;
      }
      txt.textContent = msg;
    }
    if (confirmBtn) {
      confirmBtn.disabled    = sel !== cost;
      confirmBtn.textContent = sel >= cost ? `✓ Confirm Payment` : `Select ${need} more`;
    }
  }

  function enterPaymentMode(action) {
    pendingPayAction = action;
    selectedPayment.clear();
    updatePaymentModeUI();
    const cost = Number(action?.cost_to_pay || 0);
    if (cost > 0) {
      try {
        showToast(`${action.face_name || "This card"} costs ${cost} card${cost === 1 ? "" : "s"} to play. Choose payment cards.`, "info");
      } catch (_) {}
    }
    document.getElementById("pv-hand")?.classList.add("payment-active");
    _handRenderKey = "";
    if (_handRenderData) {
      const { me, actions, mustDiscard, discardExcess } = _handRenderData;
      renderHand(me, actions, mustDiscard, discardExcess);
    }
  }

  // Toggle a card in/out of the payment selection, capping the total at the
  // card's required cost. Returns true if the selection changed. A player can
  // always UNSELECT, but can never select MORE than the cost, so overpaying
  // is impossible at the source (the UI), and the server re-validates anyway.
  function _togglePaymentCard(entryUid) {
    const id = Number(entryUid);
    const cost = Number(pendingPayAction?.cost_to_pay || 0);
    if (selectedPayment.has(id)) {
      selectedPayment.delete(id);   // unselect is always allowed
      return true;
    }
    if (selectedPayment.size >= cost) {
      // Already at the required count, block the extra selection.
      showToast(`You selected too many cards. This card only costs ${cost}.`, "warn");
      return false;
    }
    selectedPayment.add(id);
    return true;
  }

  function exitPaymentMode() {
    pendingPayAction = null;
    selectedPayment.clear();
    updatePaymentModeUI();
    document.getElementById("pv-hand")?.classList.remove("payment-active");
    _handRenderKey = "";
    if (_handRenderData) {
      const { me, actions, mustDiscard, discardExcess } = _handRenderData;
      renderHand(me, actions, mustDiscard, discardExcess);
    }
  }

  // Full "back button" for the current turn: cancel any in-progress (un-submitted)
  // action and wipe EVERY piece of local staging state so the next play starts
  // from a clean slate. Without this, leftover state from a canceled action
  // (e.g. a staged play + selected payment) bleeds into the next action, the
  // classic "it charged me but never placed the animal" bug. Clears: the staged
  // play (card / ocean / side / spot held in pendingPayAction), payment-card
  // selection + confirmation, pool/discard selections, all drag/drop state, the
  // pending-draw confirmation, and the in-flight / action-used flag. Then it
  // re-renders from the last known server state so no stale highlight survives.
  function resetTurnStaging() {
    pendingPayAction   = null;   // staged play (card_uid + ocean_uid + side/spot)
    selectedPayment.clear();     // chosen payment cards
    selectedPool.clear();        // pool picks
    selectedDiscard.clear();     // discard picks
    _pendingDrawAction = null;   // draw awaiting the over-10 confirm
    _pendingMoveAnim   = null;   // move-between-oceans animation staging
    _handDragSrc       = null;   // in-hand reorder drag
    _boardMoveDragSrc  = null;   // board animal move drag
    _drawWarnBypass    = false;  // one-shot draw-warning bypass
    actionInFlight     = false;  // never leave the turn looking "already used"
    // Visual cleanup: payment overlay, any drag-over highlights, the draw modal.
    document.getElementById("pv-hand")?.classList.remove("payment-active");
    document.querySelectorAll(".drag-over").forEach(el => el.classList.remove("drag-over"));
    document.getElementById("draw-warn-modal")?.classList.remove("open");
    updatePaymentModeUI();
    updatePaymentBadge();
    // Repaint hand + board from the last server snapshot so nothing stale lingers.
    _handRenderKey = "";
    if (latestPayload) renderPayload(latestPayload);
  }

  function setStatus(msg) { document.getElementById("pv-status-text").textContent = msg; }

  function _viewerCanActNow() {
    try { return !!(latestPayload && latestPayload.viewer && latestPayload.viewer.can_act); }
    catch (_) { return false; }
  }

  // True only when the SERVER says it's this client's turn to act. This is the
  // single source of truth used to gate every action submission, mirroring the
  // server's own "not your turn" rule so an off-turn play is refused up front
  // (with a friendly nudge) instead of being sent and bounced as "Failed".
  function _isMyTurnForAction() {
    if (_viewerCanActNow()) return true;
    // Competitive: the turn can already be on my OTHER hand while the payload on
    // screen is still the hand I was just playing. It is my turn, but that
    // hand's cards, board and legal actions are NOT what is displayed, so an
    // action sent now would be aimed at cards the player cannot see (End Turn
    // would end the unseen hand's turn for them). Refuse, and pull the active
    // hand's view in so they can play it for real a moment later.
    if (_compHandoffPending()) {
      _compRefetchKey = "";  // let the corrective fetch retry for this version
      setTimeout(() => { try { refreshStateAfterAction(); } catch (_) {} }, 0);
    }
    return false;
  }

  // True while the turn belongs to one of my competitive hands but the view on
  // screen is my other hand's (the handoff is still in flight).
  function _compHandoffPending() {
    try {
      if (!compMode || !Array.isArray(compMySeats) || !latestPayload) return false;
      const aas = Number(latestPayload.active_action_seat);
      if (!compMySeats.includes(aas)) return false;
      return Number(latestPayload.viewer && latestPayload.viewer.seat_index) !== aas;
    } catch (_) { return false; }
  }

  function _dirHuman(dir) {
    const d = String(dir || "").toLowerCase();
    return d === "up" ? "Up" : d === "down" ? "Down" : d === "left" ? "Left" : d === "right" ? "Right" : "that";
  }

  function _entryFirstFace(entry) {
    return (entry && Array.isArray(entry.faces) && entry.faces.length) ? entry.faces[0] : entry;
  }

  // Why a drop was refused.
  //
  // A two-sided card is ONE hand entry holding TWO animals, and the lane you
  // aim at is what decides which of them you are playing. Entry 105 is the
  // Great White Shark (Diamond, cost 4) on its Left half and the Goliath
  // Grouper (Square, cost 1) on its Right. So every reason below is worked out
  // for the face that owns the TARGET lane, never for the entry as a whole.
  //
  // Reading it off the entry is what produced "this card only goes in the
  // Right lane" for a player looking at a Great White Shark: the shark's own
  // lane IS Left, but with only three other cards in hand its cost of 4 was
  // unpayable, so the server offered no left-lane play, only the cheap
  // Grouper's right-lane one, and the lane check then reported the Grouper's
  // lane as if it were the card's. The lane a card can use is a property of
  // the card; what you can pay for this turn is not. They are separate answers
  // and this says which one actually blocked the play.
  function _blockedPlayMessage(entryUid, faceUid, targetDir, targetOceanUid) {
    if (!_viewerCanActNow()) return "It is not your turn.";
    if (_imAway) return "You're on Surf's Up, tap 🌊 I'm Back before making a move.";

    const entry = handEntryMap.get(Number(entryUid)) || null;
    const face = _entryFirstFace(entry) || {};
    const faces = (entry && Array.isArray(entry.faces) && entry.faces.length) ? entry.faces : [face];
    const species = String(face.species || entry?.species || "").trim();
    const me = latestPayload?.state?.players?.find(p => p.index === myIdx);
    const board = Array.isArray(me?.board) ? me.board : [];
    if (!board.length && species && species !== "Ocean") {
      return "You need to play an Ocean first.";
    }

    const tDir = String(targetDir || "").toLowerCase();
    if (tDir && species === "Ocean") return "This Ocean goes in the Ocean drop zone.";

    const acts = (legalActions || []).filter(a =>
      (a.kind === "play_to_ocean" || a.kind === "play_ocean") &&
      (Number(a.card_uid) === Number(entryUid) || Number(a.face_uid) === Number(faceUid))
    );

    // The lanes this card can EVER use, read off its own faces rather than off
    // whatever happens to be affordable right now. An unaffordable half still
    // owns its lane, and saying otherwise is the bug above.
    const LANES = ["up", "down", "left", "right"];
    const cardDirs = [...new Set(
      faces.map(f => String(f?.direction || "").toLowerCase()).filter(d => LANES.includes(d))
    )];
    if (tDir && cardDirs.length && !cardDirs.includes(tDir)) {
      return cardDirs.length === 1
        ? `This card only goes in the ${_dirHuman(cardDirs[0])} lane.`
        : `This card only goes in these lanes: ${cardDirs.map(_dirHuman).join(", ")}.`;
    }

    // Right lane, so name the animal that goes there and say what stopped it.
    const laneFace = tDir ? faces.find(f => String(f?.direction || "").toLowerCase() === tDir) : null;
    if (laneFace) {
      const who = String(laneFace.name || "").trim() || "That side of this card";
      const laneActs = acts.filter(a => Number(a.face_uid) === Number(laneFace.uid));
      if (!laneActs.length) {
        const cost  = Number(laneFace.cost ?? 0);
        const spare = Array.isArray(me?.hand) ? Math.max(0, me.hand.length - 1) : null;
        if (cost > 0 && spare !== null && spare < cost) {
          return `${who} costs ${cost} card${cost === 1 ? "" : "s"} to play, and you have ${spare === 0 ? "no" : "only " + spare} other card${spare === 1 ? "" : "s"} to pay with.`;
        }
        if (cost > 0) return `${who} costs ${cost} card${cost === 1 ? "" : "s"} to play.`;
        return `${who} can't be played right now.`;
      }
      // It plays fine somewhere, just not into this ocean's lane.
      if (targetOceanUid != null && !laneActs.some(a => Number(a.ocean_uid) === Number(targetOceanUid))) {
        return `That ${_dirHuman(tDir)} spot is taken. ${who} needs a free one on another ocean.`;
      }
    }

    if (!acts.length) {
      if (species === "Ocean") return "This Ocean goes in the Ocean drop zone.";
      return "That card cannot be played right now.";
    }
    const costs = [...new Set(acts.map(a => Number(a.cost_to_pay || 0)).filter(n => n > 0))];
    if (costs.length) {
      const cost = Math.min(...costs);
      return `This card costs ${cost} card${cost === 1 ? "" : "s"} to play.`;
    }
    return "That card can't be played here.";
  }

  function normalizeSymbol(s) { return String(s||"").trim().toLowerCase(); }
  function entryHasSymbolMatch(entryUid, sym) {
    if (!sym) return false;
    const entry = handEntryMap.get(Number(entryUid));
    if (!entry) return false;
    const target = normalizeSymbol(sym);
    // Dual-faced cards: a match on EITHER face counts as payable for the star ability.
    if (Array.isArray(entry.faces) && entry.faces.length > 0) {
      return entry.faces.some(f => normalizeSymbol(f && f.symbol || "") === target);
    }
    return normalizeSymbol(entry.symbol) === target;
  }

  // ── Star-ability helpers ───────────────────────────────────────────────
  // The FACE an action actually plays. Two-sided cards share one hand entry, and
  // in 40 of the game's pairs only ONE of the two faces carries a ★, so reading
  // the star off faces[0] names the wrong ability (or none) half the time.
  function _actionFace(action) {
    const entry = handEntryMap.get(Number(action?.card_uid));
    if (!entry) return null;
    const faces = Array.isArray(entry.faces) && entry.faces.length ? entry.faces : [entry];
    const want = Number(action?.face_uid);
    return faces.find(f => Number(f && f.uid) === want) || faces[0] || entry;
  }

  // Human-readable ★ text of the face this action plays ("Draw one", …).
  function _actionStarText(action) {
    // The server names the ★ this exact play will fire. That is not always the
    // played face's own star: a Clownfish copies the ocean it is attached to,
    // so on a Mangrove or an Arctic Ocean its ★ is "play again" while its own
    // card text carries none at all. Fall back to the face for older payloads.
    const fromServer = String(action?.star_ability || "").trim();
    if (fromServer) return fromServer;
    const face = _actionFace(action);
    return starText(face?.text || "") || "";
  }

  // The one question every ★ affordance in the UI must be answered by: will
  // submitting THIS action fire the star? The engine only fires a ★ for an
  // action sent with use_star=true: paying with a matching symbol on the plain
  // variant does nothing. So:
  //   • fires   → the gold "this pays for the ★" highlight is honest.
  //   • offered → a ★ twin exists but the player turned ★ off; no gold, just a note.
  function starPayInfo(action) {
    if (!action) return { fires: false, offered: false, sym: "", ability: "" };
    const fires = Boolean(action.use_star && action.requires_symbol_match && action.required_symbol);
    const sym   = normalizeSymbol(fires ? action.required_symbol : (action.star_symbol || ""));
    return {
      fires,
      offered: !fires && Boolean(action.star_symbol),
      sym,
      ability: _actionStarText(action),
    };
  }

  function uniqueIntList(arr) {
    const out = []; const seen = new Set();
    for (const r of (arr||[])) { const n=Number(r); if(Number.isInteger(n)&&!seen.has(n)){seen.add(n);out.push(n);} }
    return out;
  }

  function buildPaymentSet(action, sourceUids) {
    const cost = Number(action.cost_to_pay||0);
    if (cost <= 0) return [];
    const reqSym = Boolean(action.requires_symbol_match && action.required_symbol);
    const avail = uniqueIntList(sourceUids).filter(u => u !== Number(action.card_uid) && handEntryMap.has(u));
    const picks = []; const rem = [...avail];
    if (reqSym) {
      const m = rem.find(u => entryHasSymbolMatch(u, action.required_symbol));
      if (m == null) return null;
      picks.push(m); rem.splice(rem.indexOf(m),1);
    }
    for (const u of rem) { if (picks.length >= cost) break; picks.push(u); }
    return picks.length === cost ? picks : null;
  }

  function choosePayment(action) {
    const cost = Number(action.cost_to_pay||0);
    if (cost <= 0) return { picks:[], error:"" };
    const manual = uniqueIntList(Array.from(selectedPayment));
    if (manual.length === 0) {
      // A symbol is only REQUIRED on the ★ variant; a plain play takes any cards.
      const star = starPayInfo(action);
      const symHint = star.fires ? ` (one must be a ${star.sym} card for the ★)` : "";
      return { picks:[], error:`Select ${cost} payment card(s) from your hand first${symHint}.` };
    }
    if (manual.length !== cost) {
      return { picks:[], error:`Select exactly ${cost} payment card(s), you have ${manual.length} selected.` };
    }
    const mp = buildPaymentSet(action, manual);
    if (mp) return { picks: mp, error:"" };
    const sym = action.required_symbol;
    if (sym) return { picks:[], error:`Payment invalid, at least one selected card must have the ${sym} symbol.` };
    return { picks:[], error:`Selected cards cannot be used as payment for this action.` };
  }

  async function submitAction(action) {
    try { window.__ccNoteAction && window.__ccNoteAction(action); } catch (_) {} // Current Controller bug-log breadcrumb
    // Surf's Up!!, you cannot play any moves while you are Away. Tap "I'm Back"
    // (the 🌊 button) first. Mirrors the server-side guard so it's 100% accurate.
    if (_imAway) {
      try { showToast("You're on Surf's Up, tap 🌊 I'm Back to make a move.", "warn"); } catch {}
      return;
    }
    // ── Turn guard ────────────────────────────────────────────────────────
    // Every play / draw / move / end-turn funnels through here, and each is
    // legal ONLY on your own turn. Without this the client would happily let
    // you stage a play while another player is acting, send it, and have the
    // server bounce it with "not your turn", surfacing as a baffling
    // "Failed: not your turn" AFTER you'd already set everything up. Mirror the
    // server's own rule and refuse up front, so an off-turn tap can never waste
    // your setup or look like the game "broke". Uses the server truth
    // (viewer.can_act), NOT the optimistic canInteract, so rapid, legitimate
    // mid-turn follow-up actions (play, then immediately play again) still work.
    if (!_isMyTurnForAction()) {
      if (_compHandoffPending()) {
        // It IS my turn, just my other hand's: say so instead of "not your turn".
        const _hand = compGetHandName(Number(latestPayload?.active_action_seat));
        try { showToast(`Switching to ${_hand}…`, "warn"); } catch (_) {}
        setStatus(`Bringing up ${_hand}, its cards are on the way.`);
      } else {
        try { showToast("Hold on, wait for your turn.", "warn"); } catch (_) {}
        setStatus("Not your turn yet, waiting for the other players.");
      }
      return;
    }
    // If the action costs cards, ensure we have valid payment staged for THIS action.
    // enterPaymentMode() clears any stale selection from a prior action.
    if (Number(action.cost_to_pay || 0) > 0) {
      // Payment is considered "confirmed" (pendingPayAction=null) only when the user
      // explicitly clicked Confirm Payment, clearing pendingPayAction before calling here.
      // In every other path (drag, slot-click, picker) pendingPayAction is still set or null
      // from a prior action, if it doesn't match the current action, re-enter payment mode.
      const confirmedPath = pendingPayAction === null && selectedPayment.size > 0;
      const sameStagedAction = pendingPayAction !== null &&
        Number(pendingPayAction.card_uid) === Number(action.card_uid) &&
        Number(pendingPayAction.ocean_uid ?? -1) === Number(action.ocean_uid ?? -1);
      if (!confirmedPath && !sameStagedAction) {
        enterPaymentMode(action);
        return;
      }
    }

    // Hand-over-10 warning: ONLY for manual draw actions (pool / deck / mix).
    // Card-triggered draws don't come through here, they happen server-side
    // as part of resolving a play. So this naturally only catches user draws.
    // Draws are now 1 card at a time, so warn only when THIS draw would push
    // the hand past 10 (not when a hypothetical second draw might).
    if (action.kind === "draw" && !_drawWarnBypass) {
      const meNow = (latestPayload?.state?.players || []).find(p => p.index === myIdx);
      const handCount = Number(meNow?.hand_count ?? (Array.isArray(meNow?.hand) ? meNow.hand.length : 0));
      if (handCount + 1 > 10) {
        _pendingDrawAction = action;
        document.getElementById("draw-warn-modal").classList.add("open");
        return;
      }
    }
    _drawWarnBypass = false;

    // In competitive mode, use the token for whichever of our seats is currently
    // active, the server acts as the ACTIVE seat (see _competitive_same_owner),
    // so sending the other hand's token would submit this hand's move against the
    // wrong seat's legal-action list. mySeatIdx (the seat the last render drew) is
    // only the fallback, for the poll-cycle where the two briefly disagree.
    let token;
    if (compMode) {
      const _aas = Number(latestPayload?.active_action_seat);
      token = (compMySeats.includes(_aas) && compTokens[_aas])
        ? compTokens[_aas]
        : (mySeatIdx !== null && compTokens[mySeatIdx]) ? compTokens[mySeatIdx] : getSeatToken();
    } else {
      token = getSeatToken();
    }
    if (!token) { setStatus("No seat token, re-join."); showToast("No seat token, re-join.", "err"); return; }
    if (actionInFlight) { setStatus("Wait for previous action…"); return; }

    const pl = { seat_token: token, use_star: Boolean(action.use_star), request_id: makeRequestId() };
    const hi = v => typeof v === "number" && Number.isInteger(v);
    if (hi(action.index))          pl.action_index = action.index;
    if (action.kind)               pl.kind = action.kind;
    if (hi(action.card_uid))       pl.card_uid = action.card_uid;
    if (hi(action.face_uid))       pl.face_uid = action.face_uid;
    if (hi(action.ocean_uid))      pl.ocean_uid = action.ocean_uid;
    if (hi(action.source_ocean_uid)) pl.source_ocean_uid = action.source_ocean_uid;
    if (hi(action.draw_from_pool)) pl.draw_from_pool = action.draw_from_pool;
    const need = Number(action.draw_from_pool||0);
    if (Array.isArray(action.pool_pick_uids) && action.pool_pick_uids.length > 0) {
      pl.pool_pick_uids = action.pool_pick_uids;
    } else if (need > 0) {
      pl.pool_pick_uids = Array.from(selectedPool).slice(0, need);
    }
    if (action.kind === "discard_batch_to_pool" && Array.isArray(action.pool_pick_uids))
      pl.pool_pick_uids = action.pool_pick_uids;
    const cost = Number(action.cost_to_pay||0);
    if (cost > 0) {
      // ── Star play without a matching-symbol payment ──────────────
      // The ★ toggle is on, so this is the STAR variant, which needs at least
      // one payment card whose symbol matches. If the player's chosen payment
      // has NO matching symbol, don't hard-error (the old behavior, which felt
      // like the game "breaking"). Instead pop the friendly "skip the ★?" confirm:
      //   • Confirm → replay the SAME card WITHOUT the star, using their cards.
      //   • Go back → return to payment mode with their picks intact so they can
      //     swap in a matching-symbol card and keep the star.
      if (action.use_star && action.requires_symbol_match && action.required_symbol
          && selectedPayment.size === cost) {
        const sym = action.required_symbol;
        const hasMatch = Array.from(selectedPayment).some(uid => entryHasSymbolMatch(uid, sym));
        if (!hasMatch) {
          const nonStar = (legalActions || []).find(a => !a.use_star &&
            Number(a.card_uid) === Number(action.card_uid) &&
            String(a.kind) === String(action.kind) &&
            Number(a.ocean_uid ?? -1) === Number(action.ocean_uid ?? -1) &&
            String(a.face_direction || "") === String(action.face_direction || "")
          );
          // Read the ★ off the FACE being played, on a two-sided card the
          // other face normally carries no star at all.
          const ability = _actionStarText(action) || "the star ability";
          const msg = document.getElementById("star-skip-msg");
          if (msg) msg.textContent =
            `You didn't discard a ${sym} card, so you won't get "${ability}". Play it without the star ability?`;
          _starSkipLabels("Let me go back", "Play without the ★");
          _starSkipPendingCb = () => {
            // Submit the non-star play with the SAME chosen payment.
            submitAction(nonStar ? { ...nonStar } : { ...action, use_star: false });
          };
          _starSkipBackCb = () => {
            // Return to payment mode, keeping their current selection.
            pendingPayAction = action;
            document.getElementById("pv-hand")?.classList.add("payment-active");
            updatePaymentModeUI();
            if (latestPayload) { _handRenderKey = ""; renderPayload(latestPayload); }
          };
          document.getElementById("star-skip-modal")?.classList.add("open");
          return;
        }
      }
      const pay = choosePayment(action);
      if (pay.error) {
        // Invalid selection, re-enter payment mode so the user can pick valid cards.
        enterPaymentMode(action);
        setStatus(pay.error); showToast(pay.error, "err"); return;
      }
      pl.payment_uids = pay.picks;
    }

    // Increment the draw counter OPTIMISTICALLY before the network round-trip so
    // a slow or 503-ing server can never leave the tutorial stuck on the draw step.
    // Reverted below if the server rejects the action.
    const _isDrawAction = (action.kind === "draw");
    if (_isDrawAction) _ccDrawCount++;

    actionInFlight = true;
    setStatus("Submitting…");
    try {
      const r = await apiPost(`/api/rooms/${roomId}/action`, pl, { timeoutMs:15000 });
      if (!r.ok) {
        if (_isDrawAction) _ccDrawCount--;  // revert optimistic increment on rejection
        if (r.data?.error === "room not found") { handleRoomLost(); return; }
        const errMsg = "Failed: " + (r.data?.error || r.status);
        setStatus(errMsg); showToast(errMsg, "err"); return;
      }
      selectedPayment.clear(); selectedPool.clear(); selectedDiscard.clear();
      pendingPayAction = null;
      document.getElementById("pv-hand")?.classList.remove("payment-active");
      updatePaymentBadge();
      updatePaymentModeUI();
      const desc = action.description ? action.description : (action.kind || "Action sent");
      setStatus("→ " + desc);
      showToast(desc, "ok");
      // Only optimistically clear the banner and block canInteract when the
      // submitted action is end_turn, that's the only action that actually
      // advances active_action_seat. For mid-turn actions (draw, play card,
      // move animal, etc.) can_act correctly stays true and the banner should
      // remain "YOUR TURN" without any confusing flicker.
      if (action.kind === "end_turn") {
        const _optBanner = document.getElementById("pv-turn-banner");
        const _optEndBtn  = document.getElementById("pv-end-turn-inline");
        if (_optBanner) _optBanner.className = "their-turn";
        if (_optEndBtn)  _optEndBtn.classList.remove("pulse-glow");
        setPlayAgainCallout(false);   // the extra turn is over the moment it's handed on
        canInteract = false;
        _lastActionMs = Date.now();
      }
      // (draw counter already incremented optimistically above)
      // Track per-game stats for achievements
      // I Don't Need Help: any manual draw (Pool OR Deck) disqualifies the game.
      if (action.kind === "draw" && Number(action.draw_from_pool || 0) === 0) {
        _gameAchTracker.manualDeckDraw = true;
        // Peruvian Pelican avatar: cumulative deck draws (1 card per deck draw).
        _gameAchTracker.deckDraws = (_gameAchTracker.deckDraws || 0) + 1;
      }
      // Hard Choices (cumulative): discard cards to pay card costs, bump by the
      // number of payment cards spent this action.
      try {
        const payCount = Array.isArray(pl.payment_uids) ? pl.payment_uids.length : 0;
        if (payCount > 0) window.__fishBumpAchievement?.("hard_choices", payCount, 100);
      } catch {}
      if (action.kind === "draw" && Number(action.draw_from_pool || 0) > 0) {
        _gameAchTracker.usedPool = true;
        // ── Pool draw challenge hooks ─────────────────────────────
        try {
          const myName = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx)?.name;
          const pickUids = Array.isArray(action.pool_pick_uids) ? action.pool_pick_uids.map(Number) : [];

          // fresh_current, drawing from a freshly-reset pool (within 60s of reset)
          if (_chObsPoolJustResetAt && (Date.now() - _chObsPoolJustResetAt) < 60000 && pickUids.length > 0) {
            window._reportDailyChallengeProgress?.("fresh_current", 0, { complete: true });
            _chObsPoolJustResetAt = 0;
          }

          // Check provenance of drawn cards: which were added by other players?
          let drawnFromOther = false;
          let drawnFromOpponentLastTurn = false;
          let drawnFromMyCompPartner = false;
          const round = Number(latestPayload?.state?.round_count) || 0;
          for (const uid of pickUids) {
            const owner = _chObsPoolEntryOwner.get(uid);
            const addedTurn = _chObsPoolEntryAddedTurn.get(uid);
            if (!owner) continue;
            if (owner !== myName) {
              drawnFromOther = true;
              // deny_the_setup / stolen_setup, opponent put it in last turn
              if (addedTurn != null && (round - Number(addedTurn)) <= 1) {
                drawnFromOpponentLastTurn = true;
              }
            }
            // set_it_up, comp only, this device's seats put it in
            if (_chObsCompSelfDiscarded.has(uid)) {
              const ownerSeatIdx = (Array.isArray(_latestPlayers) ? _latestPlayers : [])
                .find(p => p.name === owner)?.index;
              // Make sure the pickup is by the OPPOSITE hand of the same device.
              if (Array.isArray(compMySeats) && compMySeats.includes(ownerSeatIdx) && ownerSeatIdx !== myIdx) {
                drawnFromMyCompPartner = true;
              }
            }
          }

          // pool_watcher, streak of pool draws from OTHER players' cards.
          // Any pool draw from MY OWN discarded card resets the streak.
          if (pickUids.length > 0) {
            if (drawnFromOther && pickUids.every(u => {
                  const o = _chObsPoolEntryOwner.get(u);
                  return o && o !== myName;
                })) {
              _chObsPoolWatcherStreak++;
              if (_chObsPoolWatcherStreak >= 5) {
                window._reportDailyChallengeProgress?.("pool_watcher", 0, { complete: true });
              }
            } else {
              _chObsPoolWatcherStreak = 0;
            }
          }

          // deny_the_setup (daily) / stolen_setup (weekly), drew an opponent's
          // very-recently-played pool card.
          if (drawnFromOpponentLastTurn) {
            window._reportDailyChallengeProgress?.("deny_the_setup", 0, { complete: true });
            window._reportWeeklyChallengeProgress?.("stolen_setup", 0, { complete: true });
          }

          // set_it_up (daily, comp only), pulled out a card that THIS device
          // had earlier set up via the opposite hand.
          if (drawnFromMyCompPartner) {
            window._reportDailyChallengeProgress?.("set_it_up", 0, { complete: true });
          }

          // pool_patience, a card that has been in the pool for >= one full
          // rotation gets taken by me.
          for (const uid of pickUids) {
            const addedTurn = _chObsPoolEntryAddedTurn.get(uid);
            if (addedTurn != null && (round - Number(addedTurn)) >= 1) {
              window._reportDailyChallengeProgress?.("pool_patience", 0, { complete: true });
              break;
            }
          }

          // Clear taken cards from provenance maps so they don't re-trigger.
          for (const uid of pickUids) {
            _chObsPoolEntryOwner.delete(uid);
            _chObsPoolEntryAddedTurn.delete(uid);
            _chObsCompSelfDiscarded.delete(uid);
          }
        } catch (e) { /* non-fatal */ }
      }
      if (action.kind === "move_between_oceans") {
        _gameAchTracker.animalMoves = (_gameAchTracker.animalMoves || 0) + 1;
        // Daily: current_lite, Move 3 animals today (target 3, accumulates).
        try { window._reportDailyChallengeProgress?.("current_lite", 1); } catch {}
        // Achievement board_fixer: moved an animal on the final turn (end-game
        // window), combined with a win at game end.
        if (_gameAchTracker.endGameSeen) {
          _gameAchTracker.movedDuringEndgame = true;
          // Daily: last_turn_move, Move an animal after End Game appears.
          try { window._reportDailyChallengeProgress?.("last_turn_move", 0, { complete: true }); } catch {}
        }
        // Snapshot my score before the move resolves; the per-payload
        // observer will compare to the post-move score to detect
        // 'better_spot' (move increased my score).
        try {
          const meNow = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx);
          if (meNow) _chObsPreMoveScore = Number(meNow.score || 0);
        } catch {}
      }

      // ── Surface / Floor streak hooks ──────────────────────────────
      if (action.kind === "play_to_ocean") {
        // Card-name based avatar hooks.
        try {
          const playedName = String(handEntryMap.get(Number(action.card_uid))?.name || "").trim().toLowerCase();
          // Razorbill Auk: play both in same turn in a 4-player game.
          if (playedName === "razorbill auk") {
            _gameAchTracker.razorbillThisTurn = (_gameAchTracker.razorbillThisTurn || 0) + 1;
            const _razPlayers = (Array.isArray(_latestPlayers) ? _latestPlayers.length : 0);
            if (_gameAchTracker.razorbillThisTurn >= 2 && _razPlayers >= 4 && typeof window.__fishGrantUnlockedIcon === "function") {
              if (await window.__fishGrantUnlockedIcon("/avatars/razorbill-auk.png")) _queueAnimalUnlock("razorbill-auk");
            }
          }
          // Bigeye Tuna: play all 5 in one game (checked for the win at game end).
          if (playedName === "bigeye tuna" || playedName === "big eye tuna") {
            _gameAchTracker.bigEyeTunaPlayed = (_gameAchTracker.bigEyeTunaPlayed || 0) + 1;
          }
          // Roosterfish: its ★ ability is "play a free Baitfish" (legacy counter).
          if (playedName === "roosterfish" && action.use_star) {
            _gameAchTracker.freeBaitfishUses = (_gameAchTracker.freeBaitfishUses || 0) + 1;
          }
          // Grooved Brain Coral avatar: use 2 Grooved Brain Coral ★ abilities and
          // play a Giant Squid and a Bobtail Squid via those free-cephalopod
          // windows. Grooved Brain Coral is the ONLY card that grants a free
          // cephalopod, so a squid played while a free-cephalopod window is open
          // necessarily came from its ★ ability.
          if (playedName === "grooved brain coral" && action.use_star) {
            _gameAchTracker.grooveBrainStars = (_gameAchTracker.grooveBrainStars || 0) + 1;
          }
          const _fpsAtPlay = Array.isArray(latestPayload?.legal_actions?.free_play_species)
            ? latestPayload.legal_actions.free_play_species : [];
          const _freeCephActive = _fpsAtPlay.some(s => String(s).trim().toLowerCase() === "cephalopod");
          if (_freeCephActive && playedName === "giant squid")   _gameAchTracker.giantSquidViaGBC = true;
          if (_freeCephActive && playedName === "bobtail squid") _gameAchTracker.bobtailSquidViaGBC = true;
        } catch {}

        // ── Invertebrate "draw one" avatars ───────────────────────────
        // Each of these animals draws a card when a trigger condition fires,
        // but only while it is already on your board. Count one draw per copy
        // on board at play time (the just-played card isn't on board yet).
        try {
          // Resolve the played face (name + species) from the hand entry. The
          // played face uid may be a face uid OR an entry key, so scan faces.
          let _pf = null, _pe = null;
          for (const e of handEntryMap.values()) {
            const hit = (Array.isArray(e.faces) ? e.faces : []).find(f => Number(f.uid) === Number(action.card_uid));
            if (hit) { _pf = hit; _pe = e; break; }
          }
          if (!_pe) { _pe = handEntryMap.get(Number(action.card_uid)) || null; _pf = _pe?.faces?.[0] || null; }
          const invName    = String(_pf?.name || _pe?.name || "").trim().toLowerCase();
          const invSpecies = String(_pf?.species || "").trim().toLowerCase();
          const invDir     = String(action.face_direction || "").toLowerCase();
          const myBoard = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx)?.board;
          const countOnBoard = (nm) => {
            let n = 0;
            for (const ocean of (Array.isArray(myBoard) ? myBoard : [])) {
              for (const d of ["up","down","left","right"]) {
                for (const c of (Array.isArray(ocean[d]) ? ocean[d] : [])) {
                  if (String(c.name || "").trim().toLowerCase() === nm) n++;
                }
              }
            }
            return n;
          };
          // Sea Urchin, draw one (per Urchin) when you play an animal on the surface.
          if (invDir === "up")
            _gameAchTracker.seaUrchinDraws = (_gameAchTracker.seaUrchinDraws || 0) + countOnBoard("sea urchin");
          // Sea Star, draw one (per Star) when you play a card on the ocean floor.
          if (invDir === "down")
            _gameAchTracker.seaStarDraws = (_gameAchTracker.seaStarDraws || 0) + countOnBoard("common sea star");
          // Johnson's Sea Cucumber, draw one (per Cucumber) when you play a Game Fish.
          if (invSpecies === "game fish")
            _gameAchTracker.seaCucumberDraws = (_gameAchTracker.seaCucumberDraws || 0) + countOnBoard("johnson's johnson's sea cucumber");
          // Red Beaded Anemone, its ★ ability draws one card when activated (legacy draw count).
          if (invName === "red beaded anemone" && action.use_star)
            _gameAchTracker.seaAnemoneDraws = (_gameAchTracker.seaAnemoneDraws || 0) + 1;
          // Red Beaded Anemone, count every one played this game (avatar: 25 lifetime plays).
          if (invName === "red beaded anemone")
            _gameAchTracker.seaAnemonePlayedThisGame = (_gameAchTracker.seaAnemonePlayedThisGame || 0) + 1;
          // Johnson's Sea Cucumber, count every one played this game (avatar: 25 lifetime plays).
          if (invName === "johnson's johnson's sea cucumber")
            _gameAchTracker.seaCucumberPlayedThisGame = (_gameAchTracker.seaCucumberPlayedThisGame || 0) + 1;
          // Frigatebird avatar: 7 Coral cards played onto a Coral Reef ocean in one game.
          if (invSpecies === "coral") {
            const targetOceanUid = Number(action.ocean_uid ?? -1);
            const playedOnCoralReef = (Array.isArray(myBoard) ? myBoard : []).some(o =>
              Number(o.ocean_uid) === targetOceanUid &&
              String(o.ocean?.name || "").trim().toLowerCase() === "coral reef"
            );
            if (playedOnCoralReef)
              _gameAchTracker.coralCardsPlayed = (_gameAchTracker.coralCardsPlayed || 0) + 1;
          }
          // All Bait Fish played this game (Roosterfish avatar: 250 lifetime total).
          if (invSpecies === "baitfish")
            _gameAchTracker.baitfishPlayedThisGame = (_gameAchTracker.baitfishPlayedThisGame || 0) + 1;
          // Loggerhead Sea Turtle, count cards played in the current turn and
          // flag when a Turtle was played (its ability chains extra card plays).
          _gameAchTracker.cardsPlayedThisTurn = (_gameAchTracker.cardsPlayedThisTurn || 0) + 1;
          if (invName === "loggerhead sea turtle") _gameAchTracker.turtlePlayedThisTurn = true;
          // Hermit Crab, its ability lets you play baitfish for free this turn.
          // Flag the Hermit Crab play and count Bait Fish played this turn.
          if (invName === "hermit crab") _gameAchTracker.hermitUsedThisTurn = true;
          if (invSpecies === "baitfish") _gameAchTracker.baitFishThisTurn = (_gameAchTracker.baitFishThisTurn || 0) + 1;
          // Grant the Hermit Crab avatar the moment the requirement is met, a
          // Hermit Crab turn with 6+ Bait Fish in a 4+ player game, rather than
          // waiting for game end (which could be missed if the game ends first).
          if (_gameAchTracker.hermitUsedThisTurn && Number(_gameAchTracker.baitFishThisTurn || 0) >= 6) {
            _gameAchTracker.hermitSixBaitDone = true;
            const _hcPlayers = (Array.isArray(_latestPlayers) ? _latestPlayers.length : 0);
            if (_hcPlayers >= 4 && typeof window.__fishGrantUnlockedIcon === "function") {
              if (await window.__fishGrantUnlockedIcon("/avatars/hermit-crab.png")) _queueAnimalUnlock("hermit-crab");
            }
          }
        } catch {}

        // ── Surface / Floor streaks (surface_life, ocean_floor) ────────
        const dir = String(action.face_direction || "").toLowerCase();
        if (dir === "up") {
          _chObsSurfaceStreak++;
          _chObsFloorStreak = 0;
          if (_chObsSurfaceStreak >= 3) {
            try { window._reportDailyChallengeProgress?.("surface_life", 0, { complete: true }); } catch {}
          }
        } else if (dir === "down") {
          _chObsFloorStreak++;
          _chObsSurfaceStreak = 0;
          if (_chObsFloorStreak >= 3) {
            try { window._reportDailyChallengeProgress?.("ocean_floor", 0, { complete: true }); } catch {}
          }
        } else {
          // left/right break both streaks
          _chObsSurfaceStreak = 0;
          _chObsFloorStreak = 0;
        }

        // Free animal play, submitted a play during an active free-play window.
        const fpsBefore = Array.isArray(latestPayload?.legal_actions?.free_play_species)
          ? latestPayload.legal_actions.free_play_species
          : [];
        if (fpsBefore.length > 0) {
          try { window._reportWeeklyChallengeProgress?.("free_animal_week", 1); } catch {}
        }
      } else if (action.kind && action.kind !== "play_ocean") {
        // Any other action (draw, move, discard, end turn) breaks the streaks.
        _chObsSurfaceStreak = 0;
        _chObsFloorStreak = 0;
      }

      // ── Star ability activation hooks ─────────────────────────────
      if (action.use_star) {
        _gameAchTracker.starsActivated = (_gameAchTracker.starsActivated || 0) + 1;
        _chObsStarTurnPlayer = latestPayload?.state?.current_player || null;
        // Snapshot turn-start score so combo_current can verify the +15 hit.
        try {
          const meNow = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx);
          const myName = meNow?.name;
          if (myName && _turnStartScores[myName] != null) {
            _chObsStarTurnStartScore = Number(_turnStartScores[myName]);
          }
        } catch {}
        try {
          // Daily: star_spark, Activate 2 ★ abilities (target 2, accumulates)
          window._reportDailyChallengeProgress?.("star_spark", 1);
          // Daily: star_surfer, Activate 5 ★ in ONE game. Per-game counter
          // resets in _resetGameAchTracker, so once the in-game count reaches
          // 5 we mark it complete (idempotent if already done).
          if (_gameAchTracker.starsActivated >= 5) {
            window._reportDailyChallengeProgress?.("star_surfer", 0, { complete: true });
          }
          // Daily: symbol_match, Discard matching symbol to activate ★
          // (any successful ★ activation requires a matching symbol).
          window._reportDailyChallengeProgress?.("symbol_match", 0, { complete: true });
          // Achievement perfect_symbol (cumulative): matching-symbol ★ activation 100×.
          window.__fishBumpAchievement?.("perfect_symbol", 1, 100);
          // Daily: star_finish, ★ activation after End Game appears
          if (_gameAchTracker.endGameSeen) {
            window._reportDailyChallengeProgress?.("star_finish", 0, { complete: true });
          }
          // Weekly: star_storm, 20 ★ activations this week
          window._reportWeeklyChallengeProgress?.("star_storm", 1);
        } catch {}
      }
      // Competitive: the server moves the view to my other hand as soon as this
      // turn ends (state_view), so there is nothing to switch here.
      await sleep(160);
      refreshStateAfterAction();
    } catch(e) { setStatus("Error: " + e.message); showToast("Error: " + e.message, "err"); }
    finally { actionInFlight = false; }
  }

  // ── Rendering helpers ──────────────────────────────────────────
  function cl(el) { while(el.firstChild) el.removeChild(el.firstChild); }

  function symbolEmoji(sym) {
    const s = normalizeSymbol(sym);
    if (s==="diamond")  return "◆";
    if (s==="circle")   return "●";
    if (s==="square")   return "■";
    if (s==="triangle") return "▲";
    if (s==="heart")    return "♥";
    return sym || "?";
  }

  // ── Canonical animal-family colours, ONE colour per species, used
  //    everywhere (strategy highlights, card glows, corner tags, tooltips and
  //    the strategy panel). A single source of truth is what keeps the colours
  //    100% consistent for players: e.g. a pink glow ALWAYS means "Mammal". ──
  //    The table itself lives in js/gamedata.js, loaded just before this file,
  //    so the standalone How to Play page (rules.html) colours its strategy
  //    cards from the very same ten hues.
  const FAMILY_COLORS = window.CC_FAMILY_COLORS;
  // The same ten hues pushed dark enough to stay legible as INK on the pale
  // Player Home surfaces (How to Play, the light rulebook skin). White birds and
  // yellow coral are unreadable as text on white, so anything drawn as a word
  // rather than as a glow reads from here instead.
  const FAMILY_INK = window.CC_FAMILY_INK;
  // Normalise the many spellings the data uses ("Gamefish", "Crustaceans",
  // "Lobster", plurals…) down to a FAMILY_COLORS key.
  function _normFamily(species) {
    let s = String(species || "").toLowerCase().trim();
    if (s === "gamefish" || s === "game-fish") s = "game fish";
    if (s === "lobster" || s === "lobsters" || s === "crustaceans") s = "crustacean";
    if (s === "cross current" || s === "cross-current" || s === "current") s = "crosscurrent";
    if (FAMILY_COLORS[s]) return s;
    if (s.endsWith("s") && FAMILY_COLORS[s.slice(0, -1)]) return s.slice(0, -1);
    return s;
  }
  function familyColor(species) { return FAMILY_COLORS[_normFamily(species)] || "#b388ff"; }
  // Light-surface counterpart of familyColor(). Use this anywhere the colour
  // becomes text or a hairline on a pale background.
  function familyInk(species) { return FAMILY_INK[_normFamily(species)] || "#6f4bb0"; }
  // Black or white text, whichever stays legible on a given family colour.
  function _idealText(hex) {
    const h = String(hex || "").replace("#", "");
    if (h.length < 6) return "#07101f";
    const r = parseInt(h.slice(0,2),16), g = parseInt(h.slice(2,4),16), b = parseInt(h.slice(4,6),16);
    return ((0.299*r + 0.587*g + 0.114*b) / 255) > 0.6 ? "#07101f" : "#ffffff";
  }
  // Tooltip / zoom species-label colour. Falls back for the non-animal "End
  // Game" reminder tag, then to muted for anything unknown.
  function speciesColor(species) {
    const s = _normFamily(species);
    if (FAMILY_COLORS[s]) return FAMILY_COLORS[s];
    if (s === "end game") return "#f87171";
    return "var(--muted)";
  }
  // Small colour key shown at the top of the Strategies panel so new players
  // instantly learn which colour means which animal family.
  //    Named and ordered like the printed List of Species poster, with Oceans
  //    appended because the game colours those too.
  const _FAMILY_LEGEND = [
    ["Bait Fish", "baitfish"], ["Birds", "bird"], ["Cephalopods", "cephalopod"],
    ["Coral", "coral"], ["Crustaceans", "crustacean"], ["Game Fish", "game fish"],
    ["Invertebrates", "invertebrate"], ["Mammals", "mammal"], ["Crosscurrent", "crosscurrent"],
    ["Oceans", "ocean"],
  ];
  function _familyLegendHtml() {
    return `<div class="hs-legend"><span class="hs-legend-cap">Card colours:</span>` +
      _FAMILY_LEGEND.map(([lbl, sp]) => `<span class="hs-legend-chip" style="--lc:${familyColor(sp)}">${lbl}</span>`).join("") +
      `</div>`;
  }

  function starText(text) { const m=/\*([^*]+)\*/g.exec(text||""); return m ? m[1].trim():""; }
  function mainText(text) {
    return String(text||"").replace(/\*[^*]+\*/g,"").replace(/\|\s*\|/g,"|")
      .replace(/^\s*\|\s*/,"").replace(/\s*\|\s*$/,"").trim();
  }

  // Star-skip guard: if the player is about to play a card with an available star
  // ability WITHOUT activating it, show a quick confirmation so they don't
  // accidentally skip it. "Let me go back" cancels; "Yes, that's okay" proceeds.
  let _starSkipPendingCb = null;
  let _starSkipBackCb = null;   // runs when the player declines (Go back / backdrop)
  // Both entry points share this one modal but mean different things by "go
  // back" (swap a payment card vs. switch the ★ on), so each sets its own
  // button wording instead of leaving a label that is right only half the time.
  function _starSkipLabels(backText, okText) {
    const b = document.getElementById("star-skip-back");
    const o = document.getElementById("star-skip-confirm");
    if (b) b.textContent = backText;
    if (o) o.textContent = okText;
  }
  // Move confirmation dialog state
  let _moveConfirmPendingCb  = null;
  let _endTurnPendingCb      = null;
  // Pending move animation: set when a move is confirmed so renderMyBoard can FLIP-animate the card
  let _pendingMoveAnim = null; // { srcRect, faceUid, tgtUid }
  (function _initStarSkipModal() {
    const modal    = document.getElementById("star-skip-modal");
    const backBtn  = document.getElementById("star-skip-back");
    const okBtn    = document.getElementById("star-skip-confirm");
    if (!modal || !backBtn || !okBtn) return;
    backBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const bcb = _starSkipBackCb;
      _starSkipPendingCb = null; _starSkipBackCb = null;
      if (bcb) bcb();
    });
    okBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const cb = _starSkipPendingCb;
      _starSkipPendingCb = null; _starSkipBackCb = null;
      if (cb) cb();
    });
    modal.addEventListener("click", (e) => {
      if (e.target === modal) {
        modal.classList.remove("open");
        const bcb = _starSkipBackCb;
        _starSkipPendingCb = null; _starSkipBackCb = null;
        if (bcb) bcb();
      }
    });
  })();

  // Move confirmation dialog: "You are about to MOVE this card from X to Y. Are you sure?"
  // Only shown for move_between_oceans actions (never for play-from-hand).
  (function _initMoveConfirmModal() {
    const modal     = document.getElementById("move-confirm-modal");
    const cancelBtn = document.getElementById("move-confirm-cancel");
    const okBtn     = document.getElementById("move-confirm-ok");
    if (!modal || !cancelBtn || !okBtn) return;
    cancelBtn.addEventListener("click", () => { modal.classList.remove("open"); _moveConfirmPendingCb = null; });
    okBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const cb = _moveConfirmPendingCb; _moveConfirmPendingCb = null;
      if (cb) cb();
    });
    modal.addEventListener("click", (e) => {
      if (e.target === modal) { modal.classList.remove("open"); _moveConfirmPendingCb = null; }
    });
  })();

  // Friendly End Turn confirmation modal (replaces scary browser confirm())
  function _openEndTurnModal(endAct, isFreeWindow, freePlaySpecies) {
    const msgEl = document.getElementById("end-turn-msg");
    if (msgEl) {
      msgEl.textContent = isFreeWindow
        ? `You have a free ${(freePlaySpecies||[]).join("/")} play available. Skip it and pass to the next player?`
        : "You're about to pass to the next player. You can still cancel if you want to keep playing.";
    }
    _endTurnPendingCb = () => submitAction(endAct);
    document.getElementById("end-turn-modal")?.classList.add("open");
  }
  (function _initEndTurnModal() {
    const modal     = document.getElementById("end-turn-modal");
    const cancelBtn = document.getElementById("end-turn-cancel");
    const okBtn     = document.getElementById("end-turn-confirm");
    if (!modal || !cancelBtn || !okBtn) return;
    cancelBtn.addEventListener("click", () => { modal.classList.remove("open"); _endTurnPendingCb = null; });
    okBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const cb = _endTurnPendingCb; _endTurnPendingCb = null;
      if (cb) cb();
    });
    modal.addEventListener("click", (e) => {
      if (e.target === modal) { modal.classList.remove("open"); _endTurnPendingCb = null; }
    });
  })();

  // ── Help / Strategy guide ──────────────────────────────────────
  // Strategy data generated from the real archetype profiles and full card
  // database (default_archetype_profiles + cards_*.txt). Card lists include
  // EVERY deck copy of each card (counts shown as ×N). Do not hand-edit.
  //   The list lives in js/gamedata.js so the published How to Play page
  //   (rules.html) prints exactly the strategies this game offers mid-match.
  const BUILTIN_STRATEGIES = window.CC_BUILTIN_STRATEGIES;
  // Each built-in strategy is tinted by its PRIMARY animal family, so the
  // strategy panel cards, the active-strategy pills and the corner tags all
  // line up with the family colours above. (Combos take their first-named
  // family; per-card glows on the board still use each card's OWN family.)
  const _STRAT_PRIMARY = window.CC_STRAT_PRIMARY;
  const STRAT_COLORS = _STRAT_PRIMARY.map(f => FAMILY_COLORS[f] || "#b388ff");

  // ── Custom (user-made) strategies ──────────────────────────────
  // Players describe their own strategy each game; the cards may be any cards.
  // Custom strategies are saved on this device and appended after the built-ins,
  // so every existing index-based reference (HELP_STRATEGIES[i]) keeps working.
  const CUSTOM_STRATS_KEY = "cc_custom_strats";
  const _CUSTOM_PALETTE = ["#69d3e6", "#d4e669", "#e6699e", "#9e69e6", "#69e6a0", "#e6c169", "#69a8e6", "#e67d69", "#a0e669", "#e669d3"];
  // Index every known card by name so typed cards can still light up in-game.
  const _CARD_NAME_INDEX = (() => {
    const m = new Map();
    for (const s of BUILTIN_STRATEGIES) for (const c of (s.cards || [])) {
      const k = c.name.trim().toLowerCase();
      if (!m.has(k)) m.set(k, { name: c.name, species: c.species, text: c.text, repUid: c.repUid, uids: (c.uids || []).slice() });
    }
    return m;
  })();
  // uid → animal family, built from every strategy's card list. Lets the
  // highlighter colour a card's glow by the card's OWN family even when the
  // DOM element carries no data-species attribute.
  const _UID_SPECIES = (() => {
    const m = new Map();
    for (const s of BUILTIN_STRATEGIES) for (const c of (s.cards || [])) {
      for (const u of (c.uids || [])) if (!m.has(Number(u))) m.set(Number(u), c.species);
    }
    return m;
  })();
  function _loadCustomStrats() {
    try {
      const raw = JSON.parse(localStorage.getItem(CUSTOM_STRATS_KEY) || "[]");
      return Array.isArray(raw) ? raw.filter(s => s && s.label) : [];
    } catch (_) { return []; }
  }
  const HELP_STRATEGIES = BUILTIN_STRATEGIES.concat(_loadCustomStrats());
  // Ensure every custom strategy has a palette colour for tags/highlights.
  function _ensureStratColor(i) {
    if (!STRAT_COLORS[i]) STRAT_COLORS[i] = _CUSTOM_PALETTE[(i - BUILTIN_STRATEGIES.length) % _CUSTOM_PALETTE.length];
  }
  for (let i = BUILTIN_STRATEGIES.length; i < HELP_STRATEGIES.length; i++) _ensureStratColor(i);
  function _saveCustomStrats() {
    try { localStorage.setItem(CUSTOM_STRATS_KEY, JSON.stringify(HELP_STRATEGIES.slice(BUILTIN_STRATEGIES.length))); } catch (_) {}
  }
  // Parse the typed card list, one card per line, optional "×3" / "x3" copies.
  function _parseCustomCards(text) {
    const out = [];
    for (let line of String(text || "").split("\n")) {
      line = line.trim();
      if (!line) continue;
      let count = 1;
      const m = line.match(/[\sx×*]+(\d+)\s*$/i);
      if (m) { count = Math.max(1, parseInt(m[1], 10) || 1); line = line.slice(0, m.index).trim(); }
      if (!line) continue;
      const hit = _CARD_NAME_INDEX.get(line.toLowerCase());
      if (hit) out.push({ name: hit.name, species: hit.species, text: hit.text, count, repUid: hit.repUid, uids: hit.uids.slice() });
      else out.push({ name: line, species: "", text: "", count, repUid: null, uids: [] });
    }
    return out;
  }
  // Build/replace a custom strategy. Returns its index in HELP_STRATEGIES.
  function _saveCustomStrategy(name, notes, cardsText, replaceIdx) {
    const cards = _parseCustomCards(cardsText);
    const uids = [];
    cards.forEach(c => c.uids.forEach(u => uids.push(u)));
    const steps = String(notes || "").split("\n").map(s => s.trim()).filter(Boolean);
    const tag = ((name || "").replace(/[^A-Za-z0-9]/g, "").slice(0, 3).toUpperCase()) || "MY";
    const strat = {
      custom: true,
      label: (String(name || "").trim().slice(0, 60)) || "My Strategy",
      tier: "Custom", tag,
      blurb: steps[0] || "Your own custom strategy.",
      steps, tips: [], cards, uids
    };
    let idx;
    if (replaceIdx != null && replaceIdx >= BUILTIN_STRATEGIES.length && replaceIdx < HELP_STRATEGIES.length) {
      HELP_STRATEGIES[replaceIdx] = strat; idx = replaceIdx;
    } else {
      HELP_STRATEGIES.push(strat); idx = HELP_STRATEGIES.length - 1;
    }
    _ensureStratColor(idx);
    _saveCustomStrats();
    return idx;
  }
  function _deleteCustomStrategy(i) {
    if (i < BUILTIN_STRATEGIES.length || i >= HELP_STRATEGIES.length) return;
    HELP_STRATEGIES.splice(i, 1);
    STRAT_COLORS.splice(i, 1);
    // Re-index the active set: anything after i shifts down by one.
    const shifted = new Set();
    _activeStrategies.forEach(x => { if (x !== i) shifted.add(x > i ? x - 1 : x); });
    _activeStrategies.clear();
    shifted.forEach(x => _activeStrategies.add(x));
    _saveCustomStrats();
    _saveActiveStrategies();
  }

  // Active strategies (indices into HELP_STRATEGIES), persisted across the game.
  const _activeStrategies = new Set();
  (function _loadActiveStrategies() {
    try {
      const raw = JSON.parse(localStorage.getItem(ccScopedKey("cc_active_strats")) || "[]");
      if (Array.isArray(raw)) {
        raw.forEach(label => {
          const i = HELP_STRATEGIES.findIndex(s => s.label === label);
          if (i >= 0) _activeStrategies.add(i);
        });
      }
    } catch (_) {}
  })();
  function _saveActiveStrategies() {
    try { localStorage.setItem(ccScopedKey("cc_active_strats"), JSON.stringify([..._activeStrategies].map(i => HELP_STRATEGIES[i]?.label).filter(Boolean))); } catch (_) {}
  }
  function _trackStrategyPlay(i) {
    try {
      const label = HELP_STRATEGIES[i]?.label;
      if (!label) return;
      const counts = JSON.parse(localStorage.getItem(ccScopedKey("cc_strat_play_counts")) || "{}");
      counts[label] = (counts[label] || 0) + 1;
      localStorage.setItem(ccScopedKey("cc_strat_play_counts"), JSON.stringify(counts));
    } catch (_) {}
  }
  function _getMostPlayedStrategyLocal() {
    try {
      const counts = JSON.parse(localStorage.getItem(ccScopedKey("cc_strat_play_counts")) || "{}");
      const top = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
      return (top && top[0]) ? top[0] : "";
    } catch (_) { return ""; }
  }

  // Strip em and en dashes to a plain hyphen for readability, then HTML-escape.
  const _hesc = (s) => String(s == null ? "" : s).replace(/[\u2014\u2013]/g, "-").replace(/[&<>"']/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;" }[c]));

  // Canonical "physical card" key. Dual-faced cards (uid 1-188) are stored as
  // consecutive pairs: odd = front (top / left) face, even = back (bottom /
  // right) face. Collapsing to the odd uid lets a strategy match a card by
  // EITHER face, so a card whose strategy animal lives on its back face still
  // lights up in your hand/pool. Oceans (201-269) are single-faced.
  function _stratPairKey(uid) {
    const u = Number(uid) || 0;
    if (u >= 1 && u <= 188) return (u % 2 === 1) ? u : u - 1;
    return u;
  }

  // Label keywords → animal family. Used to work out which families a strategy
  // is genuinely BUILT AROUND (its "core" families), versus cross-family support
  // cards it merely benefits from (e.g. Birds likes crustaceans for the Gull).
  const _FAMILY_KEYWORDS = [
    ["bird", "bird"], ["lobster", "crustacean"], ["crustacean", "crustacean"],
    ["coral", "coral"], ["cephalopod", "cephalopod"], ["mammal", "mammal"],
    ["baitfish", "baitfish"], ["yellowfin", "game fish"], ["tuna", "game fish"],
    ["salmon", "game fish"], ["game fish", "game fish"], ["moon", "crosscurrent"],
    ["cross", "crosscurrent"], ["invertebrate", "invertebrate"],
    ["ocean", "ocean"], ["blue", "ocean"],
  ];
  // The families a strategy is actually about: its author-set primary family
  // (_STRAT_PRIMARY) plus any families named in its label. Custom strategies (no
  // primary, free-text label) fall back to every family they contain.
  function _strategyCoreFamilies(s, idx) {
    const fams = new Set();
    if (idx < _STRAT_PRIMARY.length && _STRAT_PRIMARY[idx]) fams.add(_normFamily(_STRAT_PRIMARY[idx]));
    const lbl = String(s.label || "").toLowerCase();
    for (const [kw, fam] of _FAMILY_KEYWORDS) if (lbl.includes(kw)) fams.add(fam);
    if (!fams.size) for (const c of (s.cards || [])) fams.add(_normFamily(c.species));
    return fams;
  }

  // Apply strategy highlighting to every relevant card. Non-invasive: adds an
  // outline/glow and small corner tags, never alters card logic.
  //  • Hand + pool cards can be played as either face. We match the physical
  //    card (pair key) ONLY for the strategy's CORE families, this is what
  //    lets a strategy whose animal sits on the back face still light up
  //    (Crustaceans, Mammals, Cephalopods…). Cross-family SUPPORT cards match
  //    by exact face only, so e.g. a Baitfish card whose back happens to be a
  //    crustacean is never mislabelled as part of the Birds strategy.
  //  • Board cards (mine, opponents, the full-screen focus view, the hover
  //    peek) are committed to one face, so they match that exact face only.
  function _applyStrategyHighlights() {
    document.querySelectorAll(".strat-hl").forEach(el => { el.classList.remove("strat-hl"); el.style.removeProperty("--strat-c"); });
    document.querySelectorAll(".strat-tags").forEach(el => el.remove());
    if (!_activeStrategies.size) return;
    const pairMap  = new Map(); // pairKey -> [stratIdx,...]  (hand / pool, core families only)
    const exactMap = new Map(); // faceUid -> [stratIdx,...]  (boards + exact hand/pool match)
    const push = (map, key, idx) => {
      if (!map.has(key)) map.set(key, []);
      if (!map.get(key).includes(idx)) map.get(key).push(idx);
    };
    for (const idx of _activeStrategies) {
      const s = HELP_STRATEGIES[idx]; if (!s) continue;
      const cards = Array.isArray(s.cards) ? s.cards : null;
      if (cards && cards.length) {
        const core = _strategyCoreFamilies(s, idx);
        for (const c of cards) {
          // A card opts into back-face (pair-key) matching if its species is one
          // of the strategy's core families, OR it's explicitly flagged a key card
          // (c.core), e.g. Spiny Lobster in Shooting the Moon, a Crustacean that
          // is central to the plan even though the strategy's core family is the
          // Crosscurrent Goby. Without this it would only light up on one face.
          const isCore = c.core === true || core.has(_normFamily(c.species));
          for (const u of (c.uids || [])) {
            push(exactMap, Number(u), idx);                 // committed face (board + exact hand)
            if (isCore) push(pairMap, _stratPairKey(u), idx); // back-face match for core families only
          }
        }
      } else if (Array.isArray(s.uids)) {
        // Defensive fallback (a strategy with uids but no card list): old behaviour.
        for (const u of s.uids) { push(pairMap, _stratPairKey(u), idx); push(exactMap, Number(u), idx); }
      }
    }
    const decorate = (el, strs) => {
      if (!strs || !strs.length) return;
      el.classList.add("strat-hl");
      // Glow colour = the card's OWN animal family, so a pink glow always means
      // "Mammal", a blue glow always means "Bird", etc., 100% consistent no
      // matter which (or how many) strategies lit the card up.
      const fu  = Number(el.dataset.faceUid);
      const fam = el.dataset.species || _UID_SPECIES.get(fu) || _UID_SPECIES.get(_stratPairKey(fu));
      el.style.setProperty("--strat-c", familyColor(fam));
      const tags = document.createElement("div");
      tags.className = "strat-tags";
      const shown = strs.slice(0, 3).map(i => {
        const s = HELP_STRATEGIES[i];
        const c = STRAT_COLORS[i] || "#b388ff";
        return `<span class="strat-tag" style="background:${c};color:${_idealText(c)}" title="${_hesc(s.label)}">${_hesc(s.tag)}</span>`;
      }).join("");
      const more = strs.length > 3 ? `<span class="strat-tag strat-tag-more">+${strs.length - 3}</span>` : "";
      tags.innerHTML = shown + more;
      el.appendChild(tags);
    };
    // Hand + pool: a card matches if its shown face is the physical card of one
    // of a strategy's CORE families (pair key), OR its shown face is exactly a
    // card the strategy lists (covers cross-family support cards shown directly).
    document.querySelectorAll("#pv-hand .pv-hand-card, #pv-pool-wrap .pv-pool-card").forEach(el => {
      const fu = Number(el.dataset.faceUid);
      const a = pairMap.get(_stratPairKey(fu)) || [];
      const b = exactMap.get(fu) || [];
      const merged = b.length ? a.concat(b.filter(x => !a.includes(x))) : a;
      decorate(el, merged);
    });
    // Every board surface: match the committed face. Covers my board, the
    // always-visible opponent boards, the click-to-open focus view, and the
    // hover peek, including the ocean base cards (Coral Reef, Kelp Forest…).
    document.querySelectorAll(
      "#pv-my-board .pv-board-card, #pv-my-board .pv-ocean-face, " +
      "#pv-opponents .pv-board-card, #pv-opponents .pv-ocean-face, " +
      "#pv-board-focus-content .pv-board-card, #pv-board-focus-content .pv-ocean-face, " +
      "#pv-board-hover .pv-board-card, #pv-board-hover .pv-ocean-face"
    ).forEach(el => {
      decorate(el, exactMap.get(Number(el.dataset.faceUid)));
    });
  }
  window._applyStrategyHighlights = _applyStrategyHighlights;

  (function _initHelpModal() {
    const btn      = document.getElementById("pv-help-btn");
    const modal    = document.getElementById("pv-help-modal");
    const listEl   = document.getElementById("pv-help-list");
    const detailEl = document.getElementById("pv-help-detail");
    const titleEl  = document.getElementById("pv-help-title");
    const backBtn  = document.getElementById("pv-help-back");
    const closeBtn = document.getElementById("pv-help-close");
    const introEl  = document.getElementById("pv-help-intro");
    if (!btn || !modal) return;
    let _curDetail = -1; // strategy index currently open in detail view (-1 = list)
    let _hsShowAllCombos = false; // section 3: whether the full combo list is expanded

    // ── Strategy classification + combo-suggestion helpers ──────────
    function _isCore(i)   { const s = HELP_STRATEGIES[i]; return !!s && s.tier === "Core"  && !s.custom; }
    function _isCombo(i)  { const s = HELP_STRATEGIES[i]; return !!s && s.tier === "Combo" && !s.custom; }
    function _isCustom(i) { const s = HELP_STRATEGIES[i]; return !!s && !!s.custom; }

    // The symbol each strategy wears: the family mark printed in the
    // bottom-right corner of every card in that family (/species/*.png), so a
    // plan is stamped with the very thing the player is reading off the cards
    // in their hand. A COMBO wears BOTH marks it bridges, split by a +.
    // Oceans have no printed symbol, so an ocean-led plan shows the Coral Reef
    // ocean card instead. The table and the resolver both live in
    // js/gamedata.js, so a strategy wears the same symbol here and on the
    // published How to Play page (/rules).
    function _stratArtHtml(i, cls) {
      // Fail soft: a stale cached gamedata.js would otherwise throw here and
      // take the whole strategy panel down with it. An empty frame is bad, a
      // blank screen is worse.
      if (typeof window.CC_STRAT_SYMBOLS !== "function") return `<div class="${cls}"></div>`;
      const syms = window.CC_STRAT_SYMBOLS(i, HELP_STRATEGIES[i]) || [];
      if (!syms.length) return `<div class="${cls}"></div>`;
      const one = (e) => e.cardUid != null
        ? `<img class="cc-sym-img cc-sym-card" src="${imagePathForUid(e.cardUid)}" alt="${_hesc(e.label)}" title="${_hesc(e.label)}" loading="lazy">`
        : `<img class="cc-sym-img" src="/species/${e.sym}.png" alt="${_hesc(e.label)}" title="${_hesc(e.label)}" loading="lazy">`;
      const plus = `<span class="cc-sym-plus" aria-hidden="true">+</span>`;
      return `<div class="${cls} cc-strat-sym" data-syms="${syms.length}"`
        + ` title="${_hesc(syms.map(e => e.label).join(" + "))}">`
        + syms.map(one).join(plus) + `</div>`;
    }

    // Which CORE strategies each COMBO bridges, and therefore the two symbols
    // its tile wears. Keyed by combo label so it is robust to index shifts from
    // appended custom strategies. Lives in js/gamedata.js so /rules pairs them
    // up the same way.
    const _COMBO_PAIR_LABELS = window.CC_COMBO_PAIR_LABELS;
    function _comboPairIdxs(i) {
      const s = HELP_STRATEGIES[i];
      if (!s) return [];
      return (_COMBO_PAIR_LABELS[s.label] || [])
        .map(lbl => HELP_STRATEGIES.findIndex(x => x.label === lbl))
        .filter(x => x >= 0);
    }
    // Ordered list of combo indices relevant to the currently-selected cores.
    // Combos that bridge TWO selected cores rank above combos touching just
    // one; inside each group the ones that FIT THE TABLE YOU ARE LOOKING AT
    // come first, so "pairs with" is an answer about your cards rather than a
    // walk down the list. A hand-written combo breaks a tie against a generated
    // one, because the named archetypes are the ones players recognise.
    function _suggestedCombos() {
      const sel = new Set([..._activeStrategies].filter(_isCore));
      if (!sel.size) return [];
      const fits = _fitsNow();
      const scored = [];
      for (let i = 0; i < HELP_STRATEGIES.length; i++) {
        if (!_isCombo(i)) continue;
        const pair = _comboPairIdxs(i);
        if (!pair.length) continue;
        const overlap = pair.filter(p => sel.has(p)).length;
        if (overlap <= 0) continue;
        const bridgesBoth = (pair.length >= 2 && pair.every(p => sel.has(p))) ? 1 : 0;
        const fit = (fits.byIdx.get(i) || {}).fit || 0;
        const authored = HELP_STRATEGIES[i].generated ? 0 : 1;
        scored.push({ i, overlap, bridgesBoth, fit, authored });
      }
      scored.sort((a, b) => (b.bridgesBoth - a.bridgesBoth) || (b.overlap - a.overlap)
        || (b.fit - a.fit) || (b.authored - a.authored) || (a.i - b.i));
      return scored.map(x => x.i);
    }

    const HS_COMBO_PREVIEW = 3; // combos shown before "Show more combos"

    // ── What the table actually looks like, right now ───────────────
    // Everything the recommendation reads, gathered once per render:
    //   board  the cards I have already COMMITTED, ocean bases included. These
    //          are the ones that cannot be taken back, so they say more about
    //          what I am playing than anything else on the table.
    //   hand   what I can still play, matched by PHYSICAL card: either face of
    //          a two-sided card is available, so both faces count as a match.
    //   pool   the same, for the cards I could pick up.
    //   taken  physical copies already sitting on somebody ELSE's board. A card
    //          the deck list says there are four of is not four cards if three
    //          of them are already down in front of other people.
    function _tableSnapshot() {
      const players = Array.isArray(_latestPlayers) ? _latestPlayers : [];
      const me = players.find(p => Number(p.index) === Number(myIdx))
        || (_handRenderData && _handRenderData.me) || null;
      // Competitive is four seats owned by two people, so "mine" is a PAIR of
      // seats, not one. Reading only myIdx would drop half my own board and
      // then count the other half against me as a rival's cards.
      const mySeats = new Set();
      if (me && me.index != null) mySeats.add(Number(me.index));
      if (Number.isInteger(myIdx)) mySeats.add(Number(myIdx));
      if (compMode && Array.isArray(compMySeats)) for (const s of compMySeats) mySeats.add(Number(s));
      const boardFaces = [];        // exact faces on MY board(s)
      const taken = new Map();      // pairKey -> copies on OTHER boards
      const facesOf = (p) => {
        const out = [];
        for (const ocean of (Array.isArray(p && p.board) ? p.board : [])) {
          const base = Number((ocean.ocean && ocean.ocean.uid) != null ? ocean.ocean.uid : ocean.ocean_uid);
          if (base) out.push(base);
          for (const dir of ["up", "down", "left", "right"]) {
            for (const c of (Array.isArray(ocean[dir]) ? ocean[dir] : [])) {
              const u = Number(c.face_uid != null ? c.face_uid : c.uid);
              if (u) out.push(u);
            }
          }
        }
        return out;
      };
      for (const p of players) {
        const faces = facesOf(p);
        if (p === me || mySeats.has(Number(p.index))) { boardFaces.push(...faces); continue; }
        // Either face of a played card means that physical copy is spent, so
        // availability is counted by pair key, not by the face they chose.
        for (const u of faces) {
          const k = _stratPairKey(u);
          taken.set(k, (taken.get(k) || 0) + 1);
        }
      }
      // A hand/pool entry becomes the SET of physical cards it could be played
      // as, so one card in hand counts once however many faces it has.
      const entryKeys = (list) => {
        const out = [];
        for (const e of (Array.isArray(list) ? list : [])) {
          const keys = new Set();
          if (Array.isArray(e.faces)) for (const f of e.faces) { if (f && f.uid != null) keys.add(_stratPairKey(Number(f.uid))); }
          if (e.entry_uid != null) keys.add(_stratPairKey(Number(e.entry_uid)));
          if (e.uid != null) keys.add(_stratPairKey(Number(e.uid)));
          keys.delete(0);
          if (keys.size) out.push(keys);
        }
        return out;
      };
      if (!boardFaces.length && _handRenderData && _handRenderData.me && _handRenderData.me !== me) {
        // Mid-reconnect: the players array can arrive before my seat is in it.
        // Fall back to the board we last rendered rather than reading the table
        // as empty and answering from the hand alone.
        boardFaces.push(...facesOf(_handRenderData.me));
      }
      return {
        board: boardFaces,
        hand: entryKeys(me && me.hand),
        pool: entryKeys(_latestPool),
        taken: taken,
      };
    }

    // How well ONE strategy fits that snapshot, as a 0-1 number plus the
    // evidence behind it. Every term is a SHARE, never a raw count: the old
    // version scored "how many of this plan's cards did I match", which handed
    // the answer to whichever plan listed the most cards (Birds lists 12, Game
    // Fish lists 3) no matter what was actually on the table.
    //   board     how much of what I have built already serves this plan
    //   hand      how much of what I can play next serves it
    //   pool      how much of what I could pick up serves it
    //   coverage  how much of the PLAN I hold, which is what stops a big card
    //             list from winning by being big
    //   supply    how many of its copies are still out there to be had
    function _strategyFit(i, snap) {
      const s = HELP_STRATEGIES[i];
      const cards = (s && Array.isArray(s.cards)) ? s.cards : [];
      if (!cards.length) return null;
      const nameByFace = new Map(), nameByPair = new Map();
      for (const c of cards) {
        for (const u of (c.uids || [])) {
          const n = Number(u);
          if (!nameByFace.has(n)) nameByFace.set(n, c.name);
          const k = _stratPairKey(n);
          if (!nameByPair.has(k)) nameByPair.set(k, c.name);
        }
      }
      const held = new Set();  // distinct listed cards I hold anywhere

      const boardNames = [];
      let boardHits = 0;
      for (const u of snap.board) {
        const n = nameByFace.get(u);
        if (n == null) continue;
        boardHits++; held.add(n);
        if (boardNames.indexOf(n) === -1) boardNames.push(n);
      }
      const matchName = (keys) => {
        for (const k of keys) { const n = nameByPair.get(k); if (n != null) return n; }
        return null;
      };
      const handNames = [];
      let handHits = 0;
      for (const keys of snap.hand) {
        const n = matchName(keys);
        if (n == null) continue;
        handHits++; held.add(n);
        if (handNames.indexOf(n) === -1) handNames.push(n);
      }
      let poolHits = 0;
      for (const keys of snap.pool) if (matchName(keys) != null) poolHits++;

      // Copies of this plan's cards already committed to somebody else's board.
      let copies = 0, gone = 0;
      for (const c of cards) {
        const seen = new Set();
        for (const u of (c.uids || [])) seen.add(_stratPairKey(Number(u)));
        copies += seen.size;
        for (const k of seen) if (snap.taken.get(k)) gone++;
      }
      const supply = copies ? 1 - (gone / copies) : 1;
      const coverage = held.size / cards.length;
      const boardShare = snap.board.length ? boardHits / snap.board.length : 0;
      const handShare  = snap.hand.length  ? handHits  / snap.hand.length  : 0;
      const poolShare  = snap.pool.length  ? poolHits  / snap.pool.length  : 0;

      // Only the terms this table can actually answer get a vote, so an opening
      // hand is judged on the hand and an eighth-round board on the board.
      const terms = [[1.6, coverage], [0.6, supply]];
      if (snap.board.length) terms.push([3.2, boardShare]);
      if (snap.hand.length)  terms.push([2.0, handShare]);
      if (snap.pool.length)  terms.push([0.8, poolShare]);
      let w = 0, v = 0;
      for (const t of terms) { w += t[0]; v += t[0] * t[1]; }
      return {
        idx: i, fit: w ? v / w : 0,
        boardHits, boardTotal: snap.board.length, boardNames,
        handHits, handNames, poolHits,
        coverage, supply, gone, copies,
      };
    }

    // Rank every built-in plan against the table. Custom plans are left out:
    // they are the player's own note to self, not one of the game's archetypes,
    // and their card lists are whatever was typed in.
    function _rankStrategies() {
      const snap = _tableSnapshot();
      const byIdx = new Map();
      for (let i = 0; i < HELP_STRATEGIES.length; i++) {
        if (!_isCore(i) && !_isCombo(i)) continue;
        const r = _strategyFit(i, snap);
        if (r) byIdx.set(i, r);
      }
      // A combo is only the best plan when BOTH of its halves are live. Without
      // this a combo wins on the strength of one half plus a card list twice
      // the size, which is exactly the wrong advice: it tells you to split a
      // board that is already winning as a single plan.
      for (const [i, r] of byIdx) {
        if (!_isCombo(i)) continue;
        const pair = _comboPairIdxs(i).map(p => byIdx.get(p)).filter(Boolean);
        if (pair.length < 2) continue;
        const ev = pair.map(p => (p.boardHits + p.handHits));
        const hi = Math.max(ev[0], ev[1]), lo = Math.min(ev[0], ev[1]);
        const balance = hi > 0 ? lo / hi : 1;
        r.fit *= 0.55 + 0.45 * balance;
        r.balance = balance;
      }
      const order = [...byIdx.keys()].sort((a, b) => {
        const fa = byIdx.get(a).fit, fb = byIdx.get(b).fit;
        if (fb !== fa) return fb - fa;
        // Same fit: the simpler plan, then the hand-written one, then the list.
        const ca = _isCore(a) ? 1 : 0, cb = _isCore(b) ? 1 : 0;
        if (cb !== ca) return cb - ca;
        const ga = HELP_STRATEGIES[a].generated ? 1 : 0, gb = HELP_STRATEGIES[b].generated ? 1 : 0;
        if (ga !== gb) return ga - gb;
        return a - b;
      });
      return { snap, byIdx, order };
    }

    // One ranking per list render, shared by the banner and the combo section
    // so the two can never disagree about which plan is ahead.
    let _fits = null;
    function _fitsNow() { if (!_fits) _fits = _rankStrategies(); return _fits; }

    // Build the prominent "best strategy" banner at the top of the strategy
    // list. It names the evidence it used, because a recommendation you cannot
    // check is one you stop believing the first time it looks wrong.
    function _recoBannerHtml() {
      const fits = _fitsNow();
      const snap = fits.snap;
      const seen = snap.board.length;
      const head = `<div class="hs2-reco-kicker">💡 ${seen ? "Best strategy for the board you have built" : "Best strategy to play for your starting hand"}</div>`;
      const empty = (msg) =>
        `<section class="hs2-sec hs2-reco"><div class="hs2-reco-card empty">${head}<div class="hs2-reco-why">${msg}</div></div></section>`;
      if (!snap.board.length && !snap.hand.length) {
        return empty("Open this once you've been dealt your hand and we'll read your cards and recommend the strategy that fits them best.");
      }
      const top = fits.order[0];
      const rec = top != null ? fits.byIdx.get(top) : null;
      if (!rec || rec.fit <= 0) {
        return empty("Nothing on the table points at one plan yet, draw a couple of cards, then check back.");
      }
      const i = rec.idx, s = HELP_STRATEGIES[i], on = _activeStrategies.has(i);
      const nameList = (arr, n) => {
        const shown = arr.slice(0, n).map(_hesc).join(", ");
        return shown + (arr.length > n ? ` +${arr.length - n} more` : "");
      };
      // The reasons, strongest first, and only the ones that are actually true
      // of this table. Board evidence outranks hand evidence outranks the pool.
      const why = [];
      if (rec.boardHits) {
        why.push(`<strong>${rec.boardHits} of the ${rec.boardTotal} cards on your board</strong> already belong to it`
          + (rec.boardNames.length ? ` (${nameList(rec.boardNames, 3)})` : ""));
      }
      if (rec.handHits) {
        why.push(`you're holding <strong>${rec.handHits}</strong> more`
          + (rec.handNames.length ? ` (${nameList(rec.handNames, 3)})` : ""));
      }
      if (rec.poolHits) why.push(`<strong>${rec.poolHits}</strong> of its cards ${rec.poolHits === 1 ? "is" : "are"} in the pool right now`);
      const whyText = why.length
        ? why.join(", ").replace(/^./, c => c.toUpperCase()) + "."
        : `It covers <strong>${Math.round(rec.coverage * 100)}%</strong> of what you're holding.`;
      // The one warning worth interrupting for: the plan is a good match but
      // the cards it needs are already on other people's boards.
      const warn = (rec.supply < 0.75 && rec.gone > 0)
        ? `<div class="hs2-reco-warn">⚠ ${rec.gone} of its ${rec.copies} copies are already on other boards, the cheap ones may be gone.</div>`
        : "";
      // Runners-up, so the pick is a ranking you can argue with rather than a
      // verdict. Combos included: two plans off one board is often the answer.
      const alts = fits.order.slice(1, 4).map(j => {
        const a = fits.byIdx.get(j);
        return `<button class="hs2-reco-alt" data-detail="${j}" style="--strat-c:${STRAT_COLORS[j]}">`
          + `${_hesc(HELP_STRATEGIES[j].label)} <span class="hs2-reco-pct">${Math.round(a.fit * 100)}%</span></button>`;
      }).join("");
      return `
        <section class="hs2-sec hs2-reco">
          <div class="hs2-reco-card" data-strat="${i}" style="--strat-c:${STRAT_COLORS[i]}">
            ${_stratArtHtml(i, "hs2-reco-art")}
            <div class="hs2-reco-body">
              ${head}
              <div class="hs2-reco-name">${_hesc(s.label)} <span class="hs2-reco-fit">${Math.round(rec.fit * 100)}% fit</span></div>
              <div class="hs2-reco-why">${whyText}</div>
              ${warn}
              <div class="hs2-reco-foot">
                <span class="hs2-reco-view" data-detail="${i}">View cards &amp; plan ›</span>
                <button class="hsc-toggle${on ? " on" : ""}" data-toggle="${i}">${on ? "✓ Playing" : "Play this"}</button>
              </div>
              ${alts ? `<div class="hs2-reco-alts"><span class="hs2-reco-alts-cap">Close behind</span>${alts}</div>` : ""}
            </div>
          </div>
        </section>`;
    }
    function renderList() {
      _curDetail = -1;
      // The table moves between opens (and between renders, when a card is
      // played with the panel up), so the ranking is thrown away and re-read
      // here rather than cached across renders.
      _fits = null;
      modal.classList.remove("detail");
      titleEl.textContent = "Strategies";
      const _fav = _getMostPlayedStrategyLocal();
      const _favBadge = _fav ? `<div style="margin:6px 0 2px;font-size:12px;color:#9fc0e0">Your most-played strategy: <strong style="color:#3dd6a8">${_hesc(_fav)}</strong></div>` : "";
      if (introEl) introEl.innerHTML = "Choose a core strategy to build around, then we'll suggest combos that pair well with it. Run several at once if you like; matching cards light up in your hand and the pool in their family colour, and a gold ★ marks a special star ability." + _familyLegendHtml() + _favBadge;

      // ── Section 1: core strategy cards ──
      const coreIdx = [];
      for (let i = 0; i < HELP_STRATEGIES.length; i++) if (_isCore(i)) coreIdx.push(i);
      const coreCard = (i) => {
        const s = HELP_STRATEGIES[i]; const on = _activeStrategies.has(i);
        return `
          <div class="hs2-card${on ? " active" : ""}" data-strat="${i}" style="--strat-c:${STRAT_COLORS[i]}">
            ${on ? `<div class="hs2-check">✓</div>` : ""}
            ${_stratArtHtml(i, "hs2-card-art")}
            <span class="help-tier Core hs2-card-tag">Core</span>
            <div class="hs2-card-body">
              <div class="hs2-card-name">${_hesc(s.label)}</div>
              <div class="hs2-card-blurb">${_hesc(s.blurb)}</div>
              <div class="hs2-card-foot">
                <span class="hs2-card-view" data-detail="${i}">View cards & plan ›</span>
                <button class="hsc-toggle${on ? " on" : ""}" data-toggle="${i}">${on ? "✓ Playing" : "Play this"}</button>
              </div>
            </div>
          </div>`;
      };
      const coreRail = coreIdx.map(coreCard).join("");

      // ── Section 2: your selected strategies (cores, combos & customs you've turned on),
      //    plus any saved-but-inactive custom plans so they stay reachable ──
      const activeAll = [..._activeStrategies].filter(i => HELP_STRATEGIES[i]).sort((a, b) => a - b);
      const savedCustoms = [];
      for (let i = 0; i < HELP_STRATEGIES.length; i++) if (_isCustom(i) && !_activeStrategies.has(i)) savedCustoms.push(i);
      const miniCard = (i, removable) => {
        const s = HELP_STRATEGIES[i];
        const tierLbl = _isCustom(i) ? "Mine" : (_isCombo(i) ? "Combo" : "Core");
        const tierCls = _isCustom(i) ? "Custom" : (_isCombo(i) ? "Combo" : "Core");
        return `
          <div class="hs2-mini${removable ? "" : " avail"}" data-strat="${i}" style="--strat-c:${STRAT_COLORS[i]}">
            ${removable ? `<button class="hs2-mini-x" data-remove="${i}" title="Remove from selection">✕</button>` : ""}
            ${_stratArtHtml(i, "hs2-mini-art")}
            <div class="hs2-mini-body">
              <span class="help-tier ${tierCls}">${tierLbl}</span>
              <div class="hs2-mini-name">${_hesc(s.label)}</div>
            </div>
          </div>`;
      };
      const selectedHtml = (activeAll.length || savedCustoms.length)
        ? activeAll.map(i => miniCard(i, true)).join("") + savedCustoms.map(i => miniCard(i, false)).join("")
        : `<div class="hs2-empty">No strategy selected yet, pick a core strategy above to get started.</div>`;
      const addSlot = `<div class="hs2-slot" id="hs2-add"><div class="hs2-slot-ico">＋</div><div class="hs2-slot-title">Add another core strategy</div></div>`;
      const createSlot = `<div class="hs2-slot create" id="hs2-create"><div class="hs2-slot-ico">✏️</div><div class="hs2-slot-title">Create Your Own Strategy</div><div class="hs2-slot-sub">Build a custom plan with your cards</div></div>`;
      const clearBtn = activeAll.length ? `<button id="hs2-clear" class="hs2-clear">Clear all</button>` : "";

      // ── Section 3: suggested combos ──
      const combos = _suggestedCombos();
      const selCoreCount = [..._activeStrategies].filter(_isCore).length;
      const shown = _hsShowAllCombos ? combos : combos.slice(0, HS_COMBO_PREVIEW);
      const comboCard = (i) => {
        const s = HELP_STRATEGIES[i]; const on = _activeStrategies.has(i);
        const pairNames = _comboPairIdxs(i).map(p => HELP_STRATEGIES[p]?.label).filter(Boolean);
        const pairTag = pairNames.length ? `<span class="hs2-combo-pairtag">${_hesc(pairNames.join(" + "))}</span>` : "";
        return `
          <div class="hs2-combo${on ? " active" : ""}" data-strat="${i}" style="--strat-c:${STRAT_COLORS[i]}">
            ${on ? `<div class="hs2-check">✓</div>` : ""}
            ${_stratArtHtml(i, "hs2-combo-art")}
            <span class="help-tier Combo hs2-card-tag">Combo</span>
            <div class="hs2-combo-body">
              ${pairTag}
              <div class="hs2-combo-name">${_hesc(s.label)}</div>
              <div class="hs2-combo-why">${_hesc(s.blurb)}</div>
              <div class="hs2-combo-foot">
                <span class="hs2-combo-view" data-detail="${i}">View combo details ›</span>
                <button class="hsc-toggle${on ? " on" : ""}" data-toggle="${i}">${on ? "✓ Playing" : "Play this"}</button>
              </div>
            </div>
          </div>`;
      };
      let combosBody;
      if (!selCoreCount) combosBody = `<div class="hs2-empty">Select a core strategy to see suggested combos.</div>`;
      else if (!combos.length) combosBody = `<div class="hs2-empty">No combo pairs for this selection yet, try adding another core strategy.</div>`;
      else combosBody = shown.map(comboCard).join("");
      const moreCount = combos.length - HS_COMBO_PREVIEW;
      const showMoreBtn = (combos.length > HS_COMBO_PREVIEW)
        ? `<button id="hs2-show-more">${_hsShowAllCombos ? "Show fewer" : `Show more combos (${moreCount}) ›`}</button>`
        : "";

      listEl.innerHTML = `
        ${_recoBannerHtml()}
        <section class="hs2-sec">
          <div class="hs2-sec-head"><span class="hs2-num">1</span> Choose Your Core Strategy <span class="hs2-sec-sub">Foundational plans, pick one or more to build around.</span></div>
          <div class="hs2-core-rail">${coreRail}</div>
        </section>
        <div class="hs2-bottom">
          <section class="hs2-sec hs2-panel">
            <div class="hs2-sec-head"><span class="hs2-num">2</span> Your Selected Strategy(ies) ${clearBtn}</div>
            <div class="hs2-selected-row">${selectedHtml}${addSlot}${createSlot}</div>
          </section>
          <section class="hs2-sec hs2-panel">
            <div class="hs2-sec-head"><span class="hs2-num">3</span> Suggested Combos ${showMoreBtn}</div>
            <div class="hs2-combos-row">${combosBody}</div>
          </section>
        </div>`;
    }

    function renderDetail(i) {
      const s = HELP_STRATEGIES[i];
      if (!s) return;
      _curDetail = i;
      modal.classList.add("detail");
      titleEl.textContent = s.label;
      const on = _activeStrategies.has(i);
      const stepsHtml = (s.steps || []).map(t => `<li>${_hesc(t)}</li>`).join("");
      const tipsHtml  = (s.tips  || []).map(t => `<li>${_hesc(t)}</li>`).join("");
      const totalCopies = (s.cards || []).reduce((n, c) => n + c.count, 0);
      const cardsHtml = (s.cards || []).map(c => {
        const hasImg = c.repUid != null;
        const imgInner = hasImg
          ? `<img src="${imagePathForUid(c.repUid)}" style="object-position:${cardHalfPos(c.repUid)};" alt="${_hesc(c.name)}" loading="lazy">`
          : `<div class="hd-card-noimg">${_hesc(c.name.slice(0, 2).toUpperCase())}</div>`;
        return `
        <div class="hd-card-tile${hasImg ? "" : " no-img"}" ${hasImg ? `data-uid="${c.repUid}"` : ""} title="${_hesc(c.name)} ×${c.count}${hasImg ? " · click to zoom" : ""}">
          <div class="hd-card-img">${imgInner}${c.count > 1 ? `<span class="hd-card-count">×${c.count}</span>` : ""}</div>
          <div class="hd-card-name">${_hesc(c.name)}</div>
          <div class="hd-card-text">${_hesc(c.text)}</div>
        </div>`;
      }).join("");
      const stepsSection = stepsHtml ? `<div class="hd-section-title">🧭 What do I do next</div><ol class="hd-steps">${stepsHtml}</ol>` : "";
      const cardsSection = cardsHtml ? `<div class="hd-section-title">🃏 All cards in this strategy <span class="hd-count-note">(${totalCopies} cards total · ×N shows deck copies)</span></div><div class="hd-cards-grid">${cardsHtml}</div>` : "";
      const tipsSection  = tipsHtml ? `<div class="hd-section-title">💡 Quick tips</div><ul class="hd-tips">${tipsHtml}</ul>` : "";
      const customTools  = s.custom ? `<div class="hd-custom-tools"><button id="hd-edit" class="hd-edit-btn" data-strat="${i}">✏️ Edit</button><button id="hd-delete" class="hd-delete-btn" data-strat="${i}">🗑 Delete</button></div>` : "";
      detailEl.innerHTML = `
        <div class="hd-head"><span class="help-tier ${_hesc(s.tier)}">${_hesc(s.tier)}</span></div>
        <p class="hd-blurb">${_hesc(s.blurb)}</p>
        <button id="hd-activate" class="${on ? "on" : ""}" data-strat="${i}">${on ? "✓ You're Playing This Strategy · Stop" : "I'm Playing This Strategy"}</button>
        <div class="hd-activate-hint">${on ? "Matching cards are lit up in your hand and the pool. You can turn on more than one strategy at once." : "Turn this on and matching cards will light up in your hand and the pool. You can combine strategies."}</div>
        ${stepsSection}
        ${cardsSection}
        ${tipsSection}
        ${customTools}`;
      detailEl.scrollTop = 0;
    }

    // Create / edit a custom strategy. editIdx >= built-ins for edit, else new.
    function renderCreate(editIdx) {
      _curDetail = -2;
      modal.classList.add("detail");
      const editing = (editIdx != null && HELP_STRATEGIES[editIdx] && HELP_STRATEGIES[editIdx].custom);
      const s = editing ? HELP_STRATEGIES[editIdx] : null;
      titleEl.textContent = editing ? "Edit your strategy" : "Create your own strategy";
      const nameVal  = editing ? _hesc(s.label) : "";
      const notesVal = editing ? _hesc((s.steps || []).join("\n")) : "";
      const cardsVal = editing ? _hesc((s.cards || []).map(c => c.count > 1 ? `${c.name} ×${c.count}` : c.name).join("\n")) : "";
      detailEl.innerHTML = `
        <p class="hd-blurb">Describe the strategy you're playing this game. Add the cards you're using, one per line (put <code>×3</code> after a card for multiple copies). Cards the game recognises will light up in your hand and the pool.</p>
        <div class="cc-form" data-edit="${editing ? editIdx : ""}">
          <label class="cc-flabel">Strategy name</label>
          <input id="cc-name" class="cc-input" type="text" maxlength="60" placeholder="e.g. My Crab Rush" value="${nameVal}">
          <label class="cc-flabel">What's the plan? <span class="cc-fhint">(one step per line)</span></label>
          <textarea id="cc-notes" class="cc-textarea" rows="4" placeholder="Flood the board with crabs early, then cash in for big points…">${notesVal}</textarea>
          <label class="cc-flabel">Cards in this strategy <span class="cc-fhint">(one per line, e.g. Hermit Crab ×4)</span></label>
          <textarea id="cc-cards" class="cc-textarea" rows="7" placeholder="Hermit Crab ×4&#10;Kelp Forest ×3&#10;Coral Reef ×5">${cardsVal}</textarea>
          <div class="cc-form-actions">
            <button id="cc-save" class="cc-save-btn">${editing ? "Save changes" : "Save strategy"}</button>
            <button id="cc-cancel" class="cc-cancel-btn">Cancel</button>
          </div>
        </div>`;
      detailEl.scrollTop = 0;
      setTimeout(() => { const n = document.getElementById("cc-name"); if (n) n.focus(); }, 30);
    }

    function toggleStrategy(i) {
      if (_activeStrategies.has(i)) _activeStrategies.delete(i);
      else { _activeStrategies.add(i); _trackStrategyPlay(i); }
      _saveActiveStrategies();
      _applyStrategyHighlights();
      // refresh whichever view is open
      if (_curDetail === i) renderDetail(i);
      else if (modal.classList.contains("detail") && _curDetail >= 0) renderDetail(_curDetail);
      else renderList();
    }

    // ── Randomize: clear everything, then activate N random strategies ──
    let _randCount = 2;
    function randomizeStrategies(n) {
      // Surprise-me picks random CORE strategies (combos then surface as
      // suggestions for whatever cores were rolled).
      const pool = [];
      for (let i = 0; i < HELP_STRATEGIES.length; i++) if (_isCore(i)) pool.push(i);
      const count = Math.max(1, Math.min(Number(n) || 1, pool.length));
      // Fisher-Yates shuffle, then take N.
      for (let k = pool.length - 1; k > 0; k--) {
        const r = Math.floor(Math.random() * (k + 1));
        [pool[k], pool[r]] = [pool[r], pool[k]];
      }
      const pick = pool.slice(0, count);
      _activeStrategies.clear();
      pick.forEach(i => { _activeStrategies.add(i); _trackStrategyPlay(i); });
      _saveActiveStrategies();
      // off_meta_week / off_meta_master: flag that the player used Randomize
      // with 2+ strategies during this game. The win check at game end reads
      // this flag; it resets each game via the fresh per-game tracker.
      if (count >= 2) { try { if (_gameAchTracker) _gameAchTracker.usedRandomize2Plus = true; } catch {} }
      _applyStrategyHighlights();
      _curDetail = -1;
      _hsShowAllCombos = false;
      modal.classList.remove("detail");
      renderList();
      // Scroll back to the top so the freshly-lit cards are in view.
      if (listEl) listEl.scrollTop = 0;
    }
    const randBar = document.getElementById("pv-help-rand");
    randBar && randBar.addEventListener("click", (e) => {
      const nb = e.target.closest(".phr-n");
      if (nb) {
        _randCount = Number(nb.dataset.n) || 1;
        randBar.querySelectorAll(".phr-n").forEach(b => b.classList.toggle("active", b === nb));
        return;
      }
      if (e.target.closest("#phr-go")) randomizeStrategies(_randCount);
    });

    function openModal() {
      _hsShowAllCombos = false;
      (_curDetail >= 0) ? renderDetail(_curDetail) : renderList();
      modal.classList.add("open");
      // Hide the challenge panel so it doesn't overlap the help modal.
      try { window._igcpSetVisible?.(false); } catch {}
    }
    function closeModal() {
      modal.classList.remove("open");
      // Restore the challenge panel (it tracks its own enabled/visibility state).
      try { window._igcpSetVisible?.(true); } catch {}
    }

    btn.addEventListener("click", openModal);
    closeBtn.addEventListener("click", closeModal);
    backBtn.addEventListener("click", renderList);
    modal.addEventListener("click", (e) => { if (e.target === modal) closeModal(); });

    listEl.addEventListener("click", (e) => {
      // Section 2 / 3 controls
      if (e.target.closest("#hs2-create")) { renderCreate(); return; }
      if (e.target.closest("#hs2-add")) {
        const rail = listEl.querySelector(".hs2-core-rail");
        listEl.scrollTo({ top: 0, behavior: "smooth" });
        if (rail) rail.scrollTo({ left: 0, behavior: "smooth" });
        return;
      }
      if (e.target.closest("#hs2-show-more")) { _hsShowAllCombos = !_hsShowAllCombos; renderList(); return; }
      if (e.target.closest("#hs2-clear")) {
        _activeStrategies.clear(); _hsShowAllCombos = false;
        _saveActiveStrategies(); _applyStrategyHighlights(); renderList();
        return;
      }
      const rm = e.target.closest("[data-remove]");
      if (rm) {
        e.stopPropagation();
        _activeStrategies.delete(Number(rm.dataset.remove));
        _saveActiveStrategies(); _applyStrategyHighlights(); renderList();
        return;
      }
      const tgl = e.target.closest("[data-toggle]");
      if (tgl) { e.stopPropagation(); toggleStrategy(Number(tgl.dataset.toggle)); return; }
      const det = e.target.closest("[data-detail]");
      if (det) { e.stopPropagation(); renderDetail(Number(det.dataset.detail)); return; }
      // Click anywhere else on a card opens its detail view.
      const card = e.target.closest("[data-strat]");
      if (card) renderDetail(Number(card.dataset.strat));
    });
    introEl && introEl.addEventListener("click", (e) => {
      const pill = e.target.closest(".hs-active-pill");
      if (e.target.id === "hs-clear-active") { _activeStrategies.clear(); _saveActiveStrategies(); _applyStrategyHighlights(); renderList(); }
    });
    detailEl.addEventListener("click", (e) => {
      if (e.target.closest("#cc-cancel")) { renderList(); return; }
      const saveBtn = e.target.closest("#cc-save");
      if (saveBtn) {
        const name  = (document.getElementById("cc-name")  || {}).value || "";
        const notes = (document.getElementById("cc-notes") || {}).value || "";
        const cards = (document.getElementById("cc-cards") || {}).value || "";
        if (!name.trim()) { const n = document.getElementById("cc-name"); if (n) { n.focus(); n.classList.add("cc-input-err"); } return; }
        const editAttr = saveBtn.closest(".cc-form")?.dataset.edit;
        const editIdx = (editAttr !== "" && editAttr != null) ? Number(editAttr) : null;
        const idx = _saveCustomStrategy(name, notes, cards, editIdx);
        _applyStrategyHighlights();
        renderDetail(idx);
        return;
      }
      const edit = e.target.closest("#hd-edit");
      if (edit) { renderCreate(Number(edit.dataset.strat)); return; }
      const del = e.target.closest("#hd-delete");
      if (del) {
        const di = Number(del.dataset.strat);
        const label = HELP_STRATEGIES[di]?.label || "this strategy";
        if (window.confirm(`Delete "${label}"? This can't be undone.`)) {
          _deleteCustomStrategy(di);
          _applyStrategyHighlights();
          renderList();
        }
        return;
      }
      const act = e.target.closest("#hd-activate");
      if (act) { toggleStrategy(Number(act.dataset.strat)); return; }
      const tile = e.target.closest(".hd-card-tile");
      if (tile && tile.dataset.uid) {
        const uid = Number(tile.dataset.uid);
        let found = null;
        for (const s of HELP_STRATEGIES) { const c = (s.cards||[]).find(x => x.repUid === uid); if (c) { found = c; break; } }
        if (found) { try { openZoom(uid, found.name, found.text, found.species); } catch (_) {} }
      }
    });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && modal.classList.contains("open")) closeModal(); });

    // Apply any persisted highlights once the board first renders.
    setTimeout(() => { try { _applyStrategyHighlights(); } catch (_) {} }, 800);

    // ── Tutorial bridge ─────────────────────────────────────────────
    // Lets the (separate) tutorial system drive the Strategy guide by exact
    // label without reaching into this IIFE's private state: open/close the
    // modal, verify which strategies are active, and reset/restore them around
    // the B-Lob tutorial. All lookups are by label so they survive the index
    // shifts custom strategies cause, never by a hardcoded array index.
    function _idxByLabel(label) {
      const want = String(label || "").trim().toLowerCase();
      return HELP_STRATEGIES.findIndex(s => s && String(s.label || "").trim().toLowerCase() === want);
    }
    function _rerenderHelpOpen() {
      if (!modal.classList.contains("open")) return;
      if (modal.classList.contains("detail") && _curDetail >= 0) renderDetail(_curDetail);
      else renderList();
    }
    window.__ccHelpTut = {
      open: openModal,
      close: closeModal,
      isOpen: () => modal.classList.contains("open"),
      inDetail: () => modal.classList.contains("detail"),
      detailIndex: () => _curDetail,
      // Force the list view (so Suggested Combos is visible) even if the player
      // drilled into a strategy's detail page.
      showList: () => { if (modal.classList.contains("open")) renderList(); },
      indexByLabel: _idxByLabel,
      // The family symbol(s) a strategy wears. Shared with the Player Home
      // "How to play → Strategies" page so a plan is stamped with the same
      // mark there as it is on the in-game 💡 Help screen.
      stratArtHtml: _stratArtHtml,
      isActive: (label) => { const i = _idxByLabel(label); return i >= 0 && _activeStrategies.has(i); },
      activeLabels: () => [..._activeStrategies].map(i => HELP_STRATEGIES[i] && HELP_STRATEGIES[i].label).filter(Boolean),
      // Replace the whole active set from a list of labels (used to restore the
      // player's pre-tutorial strategies). Re-applies highlights + re-renders.
      setActiveLabels: (labels) => {
        _activeStrategies.clear();
        (Array.isArray(labels) ? labels : []).forEach(lbl => { const i = _idxByLabel(lbl); if (i >= 0) _activeStrategies.add(i); });
        _saveActiveStrategies(); _applyStrategyHighlights(); _rerenderHelpOpen();
      },
      // Turn OFF specific strategies if active (so the player can turn them ON
      // themselves during the tutorial). Never toggles an inactive one on, so it
      // can't accidentally flip an already-active strategy.
      ensureInactive: (labels) => {
        let changed = false;
        (Array.isArray(labels) ? labels : [labels]).forEach(lbl => {
          const i = _idxByLabel(lbl);
          if (i >= 0 && _activeStrategies.has(i)) { _activeStrategies.delete(i); changed = true; }
        });
        if (changed) { _saveActiveStrategies(); _applyStrategyHighlights(); _rerenderHelpOpen(); }
        return changed;
      },
    };
  })();


  // Call instead of submitAction(act) for play actions.
  // If the card has a usable star ability and this action skips it,
  // shows a confirmation. Otherwise calls submitAction(act) immediately.
  function _playOrConfirmStarSkip(act, currentActions) {
    const isPlay = act && (act.kind === "play_to_ocean" || act.kind === "play_ocean");
    if (!isPlay || act.use_star) { submitAction(act); return; }
    const sym = act.star_symbol;
    if (!sym) { submitAction(act); return; }
    // Only warn when the star IS currently available (a use_star:true variant
    // exists). Matched on face_uid too: a two-sided card shares one card_uid but
    // only one of its faces normally has the ★, so a card_uid-only match could
    // pull in the star twin of the OTHER face.
    const starVariant = (currentActions || []).find(a =>
      a.use_star &&
      Number(a.card_uid) === Number(act.card_uid) &&
      Number(a.face_uid ?? a.card_uid) === Number(act.face_uid ?? act.card_uid) &&
      String(a.kind) === String(act.kind) &&
      Number(a.ocean_uid ?? -1) === Number(act.ocean_uid ?? -1)
    );
    if (!starVariant) { submitAction(act); return; }
    // Star ability label read from the FACE this action plays, not faces[0],
    // on a two-sided card the other face usually has no ★ at all.
    const abilityLabel = _actionStarText(act) || "its star ability";
    const msg = document.getElementById("star-skip-msg");
    // The engine only fires a ★ for a use_star play, so the honest framing is
    // "★ is switched off", not "discard a matching symbol" (which would do
    // nothing on this variant).
    if (msg) msg.textContent =
      `★ Star ability is switched off, so ${act.face_name || "this card"} will be played WITHOUT "${abilityLabel}". `
      + `Go back and tick ★ Star ability to use it (you'll pay with a ${sym} card).`;
    _starSkipPendingCb = () => submitAction(act);
    // "Let me go back" turns the ★ on for them and re-plays the star variant,
    // so the fix is one click instead of "cancel, hunt for the tickbox, retry".
    _starSkipBackCb = () => {
      const toggle = document.getElementById("pv-star-toggle");
      if (toggle && !toggle.checked) {
        toggle.checked = true;
        try { toggle.dispatchEvent(new Event("change", { bubbles: true })); } catch (_) {}
      }
      _playOrConfirmStarSkip(starVariant, currentActions);
    };
    _starSkipLabels("Use the ★ instead", "Play without the ★");
    document.getElementById("star-skip-modal")?.classList.add("open");
  }

  function updatePaymentBadge() {
    const info = document.getElementById("pv-payment-info");
    const txt  = document.getElementById("pv-payment-text");
    if (selectedPayment.size > 0) {
      info.classList.add("visible");
      txt.textContent = `Pay: ${selectedPayment.size} card(s)`;
    } else {
      info.classList.remove("visible");
    }
  }

  // ── Score display (animate on change) ─────────────────────────
  function updateScoreBadge(score, handCount) {
    const el = document.getElementById("pv-my-score-badge");
    const cur = Number(el.dataset.score || 0);
    const next = Number(score || 0);
    el.dataset.score = next;
    if (cur !== next && cur !== 0) {
      const diff = next - cur;
      el.style.transition = "none";
      el.style.color = diff > 0 ? "var(--green)" : "var(--red)";
      setTimeout(() => { el.style.transition = "color 1s"; el.style.color = "var(--gold)"; }, 900);
    }
    const hc = Number(handCount ?? 0);
    el.textContent = "📊 " + next + " pts · 🃏" + hc;
  }

  // ── Main payload renderer ──────────────────────────────────────
  let legalActions = [];
  let myIdx = null;     // game index (position in gs.players), used for players array lookups
  let mySeatIdx = null; // seat index, used for tokens, can_act, undo, hosting checks
  let canInteract = false;
  let _latestPlayers = [];
  let _latestRoundCount = 0;
  let _latestSeatsForSurf = [];      // seat snapshot from payload.seats (away/inactive)
  // payload.votes: what the Vote Kick / Skip Turn buttons on the seat pills
  // read. Worked out per viewer on the server (one ballot per PERSON, which
  // in competitive is not the same thing as one per seat), so the client only
  // ever renders what it is handed here.
  let _latestVotes = { ballot_seat: null, kick: [], skip: null };
  let _prevActiveSeatForIdle = null; // last active_action_seat, used to reset idle timer on turn change

  // ── Per-payload challenge observer state ─────────────────────────
  // Tracks events that need diffing between payloads (e.g. "the score I had
  // before this move" vs "the score the next payload shows").
  let _chObsPreMoveScore   = null;  // my score snapshot taken right before a move
                                    //  is submitted, compared to the next payload's
                                    //  score to detect 'better_spot'
  let _chObsPlaysThisGame     = 0;    // free animal plays this game (for free_animal_week)
  // Pool tracking, diffed every payload to detect resets, provenance, etc.
  let _chObsPrevPoolUids      = new Set(); // entry_uid set last payload
  let _chObsPrevPoolSize      = 0;
  let _chObsPoolEntryOwner    = new Map(); // entry_uid -> name of player who added it
  let _chObsPoolEntryAddedTurn= new Map(); // entry_uid -> round_count when it was added
  let _chObsPoolPrevCurPlayer = null; // current_player seen on the PREVIOUS payload, owned
                                      //  by _challObservePool ONLY (must not be shared with
                                      //  _challObserveStarCombo, which mutates its own tracker
                                      //  earlier in the same observer pass).
  // ── Daily-only observers ──────────────────────────────────────────
  // These went out with the dailies in 1.6.54 and come back with them. Each
  // one exists because its challenge asks about a SEQUENCE, a streak, a
  // before/after, a "who put that there", which a single payload cannot
  // answer on its own.
  let _chObsStarTurnPlayer    = null; // the current_player at the moment a ★ was activated
  let _chObsStarTurnStartScore= null; // turn-start score recorded when the ★ was activated
  let _chObsPrevTurnPlayer    = null; // last-seen current_player for turn-end detection
  let _chObsPrevMyBoardLen    = 0;    // my board size last payload (for the *_start dailies)
  let _chObsPoolJustResetAt   = 0;    // when the pool last reset (0 = no fresh-draw window open)
  let _chObsPoolWatcherStreak = 0;    // consecutive draws from pool from OTHER players' cards
  let _chObsCompSelfDiscarded = new Set(); // entry_uids put in pool by THIS device's seats
                                           // (for set_it_up, competitive only)
  let _chObsPrevMyHandCount   = 0;    // hand size last payload (for discard_duty)
  let _chObsSurfaceStreak     = 0;    // consecutive play_to_ocean direction="up"
  let _chObsFloorStreak       = 0;    // consecutive play_to_ocean direction="down"
  let _chObsPrevMyBoardCards    = new Set(); // face_uids on my board last payload
  let _chObsSpeciesPlayedGame   = new Set(); // species placed this game
  let _chObsOceanTypesPlayedGame= new Set(); // distinct ocean names this game
  let _chObsLastTurnStartScore  = null;     // my score at the start of my CURRENT turn
                                            //  (snapshotted on turn-boundary observer; used
                                            //   for breaker_turn at turn-end)

  // Fires the matching *_start daily challenge for the player's first
  // ocean of the game. Idempotent, the report function only ticks ACTIVE
  // slots that match the id, so this is safe to call on rejoin/refresh.
  const _CH_FIRST_OCEAN_MAP = {
    "coral reef":     "coral_start",
    "deep ocean":     "deep_start",
    "mangrove":       "mangrove_start",
    "pier":           "pier_start",
    "arctic ocean":   "arctic_start",
    "kelp forest":    "kelp_start",
    "tide pool":      "tide_pool_start",
    "artificial reef":"artificial_start",
  };
  function _challObserveFirstOcean(me) {
    const board = (me && Array.isArray(me.board)) ? me.board : [];
    const curLen = board.length;
    // Detect a 0 -> >=1 transition. Also handles the rejoin-mid-game case
    // (we start at 0 and the first observed render already has >=1).
    if (_chObsPrevMyBoardLen === 0 && curLen >= 1) {
      const oceanName = String(board[0]?.ocean?.name || "").trim().toLowerCase();
      const challengeId = _CH_FIRST_OCEAN_MAP[oceanName];
      if (challengeId) {
        try { window._reportDailyChallengeProgress?.(challengeId, 0, { complete: true }); } catch {}
      }
    }
    _chObsPrevMyBoardLen = curLen;
  }

  // 'combo_current' detection, when a star ability was activated this
  // turn, on the turn boundary check whether the player gained 15+ pts
  // during the turn. If so, fire the daily challenge.
  function _challObserveStarCombo(state, players) {
    const curP = state?.current_player || null;
    // Only act on turn boundary (current_player changes).
    if (curP === _chObsPrevTurnPlayer) return;
    // The player who JUST FINISHED their turn:
    const finishedPlayer = _chObsPrevTurnPlayer;
    _chObsPrevTurnPlayer = curP;
    if (!finishedPlayer) return;
    if (!_chObsStarTurnPlayer || _chObsStarTurnPlayer !== finishedPlayer) return;

    // Verify it's me who just finished a star turn.
    const meName = (players.find(p => p.index === myIdx) || {}).name;
    if (finishedPlayer !== meName) {
      _chObsStarTurnPlayer = null;
      _chObsStarTurnStartScore = null;
      return;
    }

    // Compute turn delta.
    const meEntry = players.find(p => p.name === finishedPlayer);
    if (meEntry) {
      const endScore = Number(meEntry.score || 0);
      const startScore = (_chObsStarTurnStartScore != null) ? _chObsStarTurnStartScore : endScore;
      if ((endScore - startScore) >= 15) {
        try { window._reportDailyChallengeProgress?.("combo_current", 0, { complete: true }); } catch {}
      }
    }
    _chObsStarTurnPlayer = null;
    _chObsStarTurnStartScore = null;
  }

  // 'better_spot' detection, when a move was just submitted, we took a
  // pre-move score snapshot. If the next observed score is higher than
  // that snapshot, the move landed the animal in a higher-scoring ocean.
  function _challObserveMoveScore(me) {
    if (_chObsPreMoveScore === null) return;
    const curScore = Number(me?.score || 0);
    if (curScore > _chObsPreMoveScore) {
      // Achievement better_spot: a move raised my score; combined with a win at game end.
      _gameAchTracker.betterSpot = true;
      // Daily better_spot asks only for the move, not the win.
      try { window._reportDailyChallengeProgress?.("better_spot", 0, { complete: true }); } catch {}
    }
    // Compare just once per move action (good or bad outcome both clear it).
    _chObsPreMoveScore = null;
  }

  // Pool observer, tracks who put each card into the pool and when, so a
  // later pickup can tell whose setup it was. Hooks into the per-payload diff.
  function _challObservePool(state, players) {
    const poolNow = Array.isArray(state.pool) ? state.pool : [];
    const curPlayer = state.current_player || null;

    const nowUids = new Set(poolNow.map(e => Number(e.entry_uid)));
    const newEntries = [...nowUids].filter(u => !_chObsPrevPoolUids.has(u));

    // The player who LAST took an action is whoever was the current player
    // BEFORE this payload's diff. If the current_player just changed, the
    // previous one acted (they discarded into the pool as their turn ended).
    // If not, the current one acted (still their turn). We track the previous
    // payload's current_player in our OWN var (_chObsPoolPrevCurPlayer), updated
    // at the end of this function, so nothing else in the observer pass can
    // advance it early (which would make the "turn just changed" branch dead
    // code and misattribute every end-of-turn discard to the NEXT player).
    const lastActor = (curPlayer && curPlayer === _chObsPoolPrevCurPlayer)
      ? curPlayer
      : (_chObsPoolPrevCurPlayer || curPlayer);

    const meName = (players.find(p => p.index === myIdx) || {}).name;

    // Record provenance for any newly-added pool entries.
    if (newEntries.length && lastActor) {
      const round = Number(state.round_count) || 0;
      for (const uid of newEntries) {
        _chObsPoolEntryOwner.set(uid, lastActor);
        _chObsPoolEntryAddedTurn.set(uid, round);
        // Competitive: track if this card was put into the pool by one of
        // this device's seats (set_it_up requires opposite-hand pickup later).
        if (typeof compMode !== "undefined" && compMode) {
          const ownerSeat = (Array.isArray(players) ? players : [])
            .find(p => p.name === lastActor)?.index;
          if (Array.isArray(compMySeats) && compMySeats.includes(ownerSeat)) {
            _chObsCompSelfDiscarded.add(uid);
          }
        }
      }
    }

    // Pool reset detection: pool was 9+ (about to overflow) → 0 (cleared).
    // Provenance dies with the pool it described.
    if (_chObsPrevPoolSize >= 9 && poolNow.length === 0) {
      _chObsPoolEntryOwner.clear();
      _chObsPoolEntryAddedTurn.clear();
      // Pool resets are triggered by whoever just placed the 10th card.
      // If it was me, pool_cleaner completes.
      if (lastActor === meName) {
        try { window._reportDailyChallengeProgress?.("pool_cleaner", 0, { complete: true }); } catch {}
      }
      // Mark fresh-pool window open so the next pool draw can fire fresh_current.
      _chObsPoolJustResetAt = Date.now();
    }

    _chObsPrevPoolUids = nowUids;
    _chObsPrevPoolSize = poolNow.length;
    // Remember this payload's current_player so the NEXT diff can tell whether
    // the turn flipped (and thus who actually added any new pool entries).
    _chObsPoolPrevCurPlayer = curPlayer;
  }

  // Species map, match the server's species strings to weekly challenge ids.
  const _CH_SPECIES_TO_WEEKLY = {
    "bird":         "bird_week",
    "crustacean":   "crustacean_week",
    "coral":        "coral_week",
    "game fish":    "game_fish_week",
    "cephalopod":   "cephalopod_week",
    "baitfish":     "bait_fish_week",
    "bait fish":    "bait_fish_week",
    "mammal":       "mammal_week",
    "invertebrate": "invertebrate_week",
    "crosscurrent": "crosscurrent_week",
  };

  // Species / ocean / hand observer, fires per-card-placed events for the
  // species weekly counters, plus the per-game distinct-species and
  // distinct-ocean challenges, plus the discard_duty hand-trim detector.
  function _challObserveSpeciesAndOcean(me) {
    const board = (me && Array.isArray(me.board)) ? me.board : [];

    // Walk every animal-attachment slot to collect all card uids currently
    // on my board, with their species.
    const curCardUids = new Set();
    const speciesByUid = new Map();
    for (const ocean of board) {
      // Track distinct ocean types this game.
      const oceanName = String(ocean?.ocean?.name || "").trim();
      if (oceanName) _chObsOceanTypesPlayedGame.add(oceanName.toLowerCase());
      // Achievement reef_reunion: a single Ocean holding both a Clownfish and
      // a Blue Tang.
      let hasClownfish = false, hasBlueTang = false;
      for (const dir of ["up", "down", "left", "right"]) {
        const cards = Array.isArray(ocean[dir]) ? ocean[dir] : [];
        for (const c of cards) {
          const uid = Number(c.uid || c.face_uid || 0);
          if (uid) {
            curCardUids.add(uid);
            const sp = String(c.species || "").toLowerCase().trim();
            if (sp) speciesByUid.set(uid, sp);
          }
          const nm = String(c.name || "").toLowerCase().trim();
          if (nm === "clownfish") hasClownfish = true;
          if (nm === "blue tang") hasBlueTang = true;
        }
      }
      if (hasClownfish && hasBlueTang) _gameAchTracker.reefReunion = true;
    }

    // Detect newly-placed cards (in curCardUids but not in _chObsPrevMyBoardCards).
    for (const uid of curCardUids) {
      if (_chObsPrevMyBoardCards.has(uid)) continue;
      const sp = speciesByUid.get(uid);
      if (!sp || sp === "ocean") continue; // ocean cards aren't animals
      // Weekly: species-specific counts.
      const cid = _CH_SPECIES_TO_WEEKLY[sp];
      if (cid) {
        try { window._reportWeeklyChallengeProgress?.(cid, 1); } catch {}
      }
      // Weekly: critter_collector, total animal cards this week (target 50).
      try { window._reportWeeklyChallengeProgress?.("critter_collector", 1); } catch {}

      // Achievement humuhumunukuapuaa: cephalopods placed in one turn (target 5).
      if (sp === "cephalopod") {
        _gameAchTracker.cephThisTurn = (_gameAchTracker.cephThisTurn || 0) + 1;
        if (_gameAchTracker.cephThisTurn > (_gameAchTracker.maxCephInTurn || 0)) {
          _gameAchTracker.maxCephInTurn = _gameAchTracker.cephThisTurn;
        }
        // Grant the moment 5 cephalopods are on the board this turn, don't wait
        // for game end. unlockAchievement is idempotent and also grants the
        // linked Reef Triggerfish avatar.
        if (_gameAchTracker.cephThisTurn >= 5) {
          try {
            const _uid = window.__fishAuthUser?.()?.uid;
            if (_uid && typeof window.__fishUnlockAchievement === "function") {
              window.__fishUnlockAchievement(_uid, "humuhumunukuapuaa");
            }
          } catch {}
        }
      }

      // Per-game distinct species set.
      _chObsSpeciesPlayedGame.add(sp);
      if (_chObsSpeciesPlayedGame.size >= 6) {
        try { window._reportWeeklyChallengeProgress?.("balanced_ocean", 0, { complete: true }); } catch {}
      }
    }

    // mini_ecosystem (daily), 4 different species groups in one game, the
    // same count balanced_ocean reads at 6.
    if (_chObsSpeciesPlayedGame.size >= 4) {
      try { window._reportDailyChallengeProgress?.("mini_ecosystem", 0, { complete: true }); } catch {}
    }

    // the_all_blue_weekly, 8 distinct Oceans on my board in one game.
    if (_chObsOceanTypesPlayedGame.size >= 8) {
      try { window._reportWeeklyChallengeProgress?.("the_all_blue_weekly", 0, { complete: true }); } catch {}
    }

    // discard_duty, at end of turn, was forced to discard down to 10.
    // Detect via hand size dropping from >10 to exactly 10 between payloads.
    const curHand = Number(me?.hand_count ?? (Array.isArray(me?.hand) ? me.hand.length : 0));
    if (_chObsPrevMyHandCount > 10 && curHand === 10) {
      try { window._reportDailyChallengeProgress?.("discard_duty", 0, { complete: true }); } catch {}
    }
    _chObsPrevMyHandCount = curHand;

    _chObsPrevMyBoardCards = curCardUids;
  }

  // Main per-payload observer entry point. Add new observers here over
  // time, keeping them all in one place makes the diff state easy to
  // reason about and easy to reset on game-end / leave.
  function _runChallengeObservers(me, state, phase, players) {
    if (phase !== "running") return;
    if (!me) return;
    _challObserveMoveScore(me);
    _challObservePool(state, players);
    _challObserveSpeciesAndOcean(me);
    _challObserveFirstOcean(me);
    _challObserveStarCombo(state, players);
  }

  // Reset all observer state when leaving the room so a brand-new game
  // starts counting from zero.
  function _resetChallengeObservers() {
    _chObsPreMoveScore = null;
    _chObsPlaysThisGame = 0;
    _chObsPrevPoolUids = new Set();
    _chObsPrevPoolSize = 0;
    _chObsPoolEntryOwner = new Map();
    _chObsPoolEntryAddedTurn = new Map();
    _chObsPoolPrevCurPlayer = null;
    _chObsPrevMyBoardCards = new Set();
    _chObsSpeciesPlayedGame = new Set();
    _chObsOceanTypesPlayedGame = new Set();
    _chObsLastTurnStartScore = null;
    // Back to 0 so the NEXT game's first ocean is seen as a 0 -> 1 transition
    // and can re-fire the *_start dailies.
    _chObsPrevMyBoardLen = 0;
    _chObsStarTurnPlayer = null;
    _chObsStarTurnStartScore = null;
    _chObsPrevTurnPlayer = null;
    _chObsPoolJustResetAt = 0;
    _chObsPoolWatcherStreak = 0;
    _chObsCompSelfDiscarded = new Set();
    _chObsPrevMyHandCount = 0;
    _chObsSurfaceStreak = 0;
    _chObsFloorStreak = 0;
  }

  function renderPayload(payload) {
    const state   = payload.state || {};
    const lw      = payload.legal_actions || {};
    legalActions  = Array.isArray(lw.actions) ? lw.actions : [];
    const viewer  = payload.viewer || {};
    // viewer.seat_index is used as both the player-lookup key (players[i].index
    // is seat_idx in the server payload) and the token/action key. They're the
    // same value, seat_index is canonical for competitive and normal games.
    myIdx    = Number.isInteger(viewer.seat_index) ? viewer.seat_index : null;
    mySeatIdx = myIdx;
    _myIdxGlobal  = myIdx;
    const players = Array.isArray(state.players) ? state.players : [];
    _latestPlayers = players;
    // Refresh the live face table before anything renders from it.
    try { noteLiveAvatars(players, payload.spectators); } catch (e) {}
    if (state.round_count != null) _latestRoundCount = Number(state.round_count) || 0;
    const me      = players.find(p => p.index === myIdx) || null;
    const phase   = payload.room?.phase || "lobby";

    // Per-payload challenge observer (first ocean type, etc.).
    try { _runChallengeObservers(me, state, phase, players); } catch (e) { /* non-fatal */ }

    // ── Match stats tracking ─────────────────────────────
    if (phase === "running" && !_matchStartMs) {
      _matchStartMs = Date.now();
      _endRevealMs = 0; // fresh game, playtime clock restarts at the next end screen
      // Capture the player's LOCAL date at game start. Streak credit is given
      // for the day a game STARTED (so a game begun at 11:55pm that ends after
      // midnight still counts for the start day). Read at game-end in saveGameStats.
      try { _gameStartLocalDate = _streakLocalDateStr(new Date()); } catch { _gameStartLocalDate = ""; }
      // Start the per-game achievement tracker clean. Without this, per-turn
      // and per-game counters (cephThisTurn, baitFishThisTurn, maxCephInTurn,
      // hermitSixBaitDone, …) leak across games and can cause both missed and
      // false unlocks. Also reset the challenge-observer diff state.
      try { window.__fishResetGameAchTracker?.(roomId); } catch {}
      try { _resetChallengeObservers(); } catch {}
      // Clear any strategies the player had active in a previous game so the
      // card highlights don't carry over. They can re-select fresh each game.
      try {
        if (typeof _activeStrategies !== "undefined") {
          _activeStrategies.clear();
          _saveActiveStrategies();
          _applyStrategyHighlights();
        }
      } catch (_) {}
      // Reset the strategy confirmation so the end-game panel re-populates fresh.
      try { _confirmedStrategies = null; _strategyConfirmSaved = false; } catch (_) {}
      // Snapshot which challenges are already done so we can show what was earned THIS game
      try {
        if (typeof window._getCompletedChallengeSnapshot === "function") {
          _preGameChallengeSnapshot = window._getCompletedChallengeSnapshot();
        }
      } catch {}
    }
    if (phase === "running" && players.length) {
      const curP = state.current_player || "";
      const round = _latestRoundCount;

      // Turn-boundary detection: when current_player changes, the PREVIOUS
      // player just finished their turn, compute their turn's score delta.
      if (curP !== _prevCurrentPlayer) {
        if (_prevCurrentPlayer && _turnStartScores[_prevCurrentPlayer] != null) {
          const prevP = players.find(p => p.name === _prevCurrentPlayer);
          if (prevP) {
            const turnDelta = Number(prevP.score || 0) - _turnStartScores[_prevCurrentPlayer];
            if (turnDelta > _bestTurnPts) { _bestTurnPts = turnDelta; _bestTurnNames = [_prevCurrentPlayer]; }
            else if (turnDelta > 0 && turnDelta === _bestTurnPts && !_bestTurnNames.includes(_prevCurrentPlayer)) {
              _bestTurnNames.push(_prevCurrentPlayer);
            }
            // Daily/Weekly: breaker_turn, Score 50+ in one turn (weekly only)
            //                              Actually weekly says target 50 → completes
            const meName = (players.find(p => p.index === myIdx) || {}).name;
            if (turnDelta >= 50 && _prevCurrentPlayer === meName) {
              try { window._reportWeeklyChallengeProgress?.("breaker_turn", 0, { complete: true }); } catch {}
            }
          }
        }
        // Record starting score for the new current player's turn
        if (curP) {
          const newP = players.find(p => p.name === curP);
          if (newP) _turnStartScores[curP] = Number(newP.score || 0);
        }
        // Reset per-turn cephalopod counter on each turn boundary (humuhumunukuapuaa).
        _gameAchTracker.cephThisTurn = 0;
        // Loggerhead Sea Turtle: finalize the turn that just ended, a qualifying
        // chain is a Turtle turn where I played 10+ cards. Then reset per-turn.
        if (_gameAchTracker.turtlePlayedThisTurn && Number(_gameAchTracker.cardsPlayedThisTurn || 0) >= 10)
          _gameAchTracker.turtleBigChains = (_gameAchTracker.turtleBigChains || 0) + 1;
        _gameAchTracker.turtlePlayedThisTurn = false;
        _gameAchTracker.cardsPlayedThisTurn = 0;
        // Hermit Crab: a qualifying turn is a Hermit Crab turn with 6+ Bait Fish played.
        if (_gameAchTracker.hermitUsedThisTurn && Number(_gameAchTracker.baitFishThisTurn || 0) >= 6)
          _gameAchTracker.hermitSixBaitDone = true;
        _gameAchTracker.hermitUsedThisTurn = false;
        _gameAchTracker.baitFishThisTurn = 0;
        _prevCurrentPlayer = curP;

        // Turn-change notification: show what the PREVIOUS player did.
        // Primary source: turn_summaries[].actions from the server (authoritative,
        // includes both faces of every two-sided card, works for bots and humans).
        if (_drawPrevPlayer) {
          const summaries = Array.isArray(payload.turn_summaries) ? payload.turn_summaries : [];
          // Find the most recent summary for the player who just finished.
          const prevSummary = [...summaries].reverse().find(s => s.player === _drawPrevPlayer);
          const serverActions = prevSummary?.actions;
          if (Array.isArray(serverActions) && serverActions.length > 0) {
            showTurnActionsNotif(_drawPrevPlayer, serverActions);
          } else {
            // Fallback: diff-based approach for backwards compatibility with older server.
            const poolNow = Array.isArray(state.pool) ? state.pool : [];
            const nowUidSet = new Set(poolNow.map(e => Number(e.entry_uid)));
            const drawnFromPool = (_drawTurnStartPool || []).filter(e => !nowUidSet.has(Number(e.entry_uid)));
            // Deck draws are COUNTED off deck_remaining, never inferred from
            // "2 minus the pool draws". That assumption reported "Drew 2 from
            // deck" over every turn that played a card and drew nothing.
            const deckNow = Number(state.deck_remaining);
            const deckCount = (_drawTurnStartDeck != null && Number.isFinite(deckNow))
              ? Math.max(0, _drawTurnStartDeck - deckNow)
              : 0;
            const prevBoardUids = _drawTurnStartBoards[_drawPrevPlayer] || new Set();
            const prevPlayerNow = players.find(p => p.name === _drawPrevPlayer);
            const prevBoardNow = Array.isArray(prevPlayerNow?.board) ? prevPlayerNow.board : [];
            const newOceans = prevBoardNow.filter(o => !prevBoardUids.has(Number(o.ocean_uid)));
            const playedOceanName = newOceans.length > 0 ? (newOceans[0].ocean?.name || null) : null;
            if (drawnFromPool.length > 0 || deckCount > 0 || playedOceanName) {
              showDrawNotif(_drawPrevPlayer, drawnFromPool, deckCount, playedOceanName);
            }
          }
        }
        const poolNow = Array.isArray(state.pool) ? state.pool : [];
        _drawTurnStartPool = [...poolNow];
        _drawTurnStartDeck = Number.isFinite(Number(state.deck_remaining))
          ? Number(state.deck_remaining) : null;
        // Snapshot each player's board oceans for fallback diff
        _drawTurnStartBoards = {};
        players.forEach(p => {
          _drawTurnStartBoards[p.name] = new Set(
            (Array.isArray(p.board) ? p.board : []).map(o => Number(o.ocean_uid))
          );
        });
        _drawPrevPlayer = curP;
      }

      // Per-payload tracking for goby / first-to-100 / score map
      players.forEach(p => {
        const prev = (_prevScoreMap[p.name] != null) ? _prevScoreMap[p.name] : null;
        const score = Number(p.score || 0);
        // First-to-100: record round_count when player first crosses 100
        if (prev !== null && score >= 100 && prev < 100 && _first100Crossings[p.name] == null) {
          _first100Crossings[p.name] = round;
        }
        _prevScoreMap[p.name] = score;
        // Shot the Moon: detect when someone's mandarin goby count decreases while another player has 3+
        const goby = Number(p.score_breakdown?.mandarin_goby?.count || 0);
        const prevGoby = _prevGobyMap[p.name] || 0;
        if (goby < prevGoby && !_shotTheMoonName) {
          const otherHas3 = players.some(q => q.name !== p.name && Number(q.score_breakdown?.mandarin_goby?.count || 0) >= 3);
          if (otherHas3) _shotTheMoonName = curP || p.name;
        }
        _prevGobyMap[p.name] = goby;
      });

      // Shoot the Moon: track if the viewer ever has all 4 Mandarin Gobies on their board at once
      if (me) {
        const myGobyCount = Number(me.score_breakdown?.mandarin_goby?.count || 0);
        if (myGobyCount >= 4) _gameAchTracker.gotAllGobies = true;
      }

      // Star ability tracking, limited to the current viewer's free play windows
      // because the server only sends legal_actions to the viewer.
      const fpa = Array.isArray(lw.free_play_species) && lw.free_play_species.length > 0;
      if (fpa && !_prevFreePlayActive && curP) _starCounts[curP] = (_starCounts[curP] || 0) + 1;
      _prevFreePlayActive = fpa;
    }
    const current = state.current_player || "";
    const isMyTurn = Boolean(viewer.can_act);
    // Suppress canInteract for any payload arriving within 600ms of our last
    // action submission, the payload is almost certainly a stale poll that
    // raced the action.  The post-action refreshStateAfterAction() will supply
    // the authoritative state once the in-flight poll has cleared.
    const _staleWindow = _lastActionMs > 0 && (Date.now() - _lastActionMs) < 600;
    canInteract = isMyTurn && !_staleWindow;

    const mustDiscard   = Boolean(lw.must_discard_to_ten);
    const discardExcess = Number(lw.discard_excess || 0);

    // Entering discard phase: kill any stale payment mode so it doesn't
    // overlay "Use as Payment" buttons on top of discard-selectable cards
    // and hide the Confirm Discard button behind the payment UI guard.
    if (mustDiscard && !_prevMustDiscard) {
      if (pendingPayAction) exitPaymentMode();
      selectedDiscard.clear();
    }
    _prevMustDiscard = mustDiscard;

    const endGame       = state.end_game || {};
    const endTriggered  = Boolean(endGame.triggered);

    // end-game cinematic: only fire when triggered transitions false→true
    // within this session. _prevEndTriggered starts as true (and resets to
    // true on cleanup) so stale/old state arriving on game entry can never
    // spuriously trigger the animation.
    if (endTriggered && !_prevEndTriggered && endGame.end_game_uid != null) {
      const triggerPlayer = state.current_player || "";
      showEndGameCinematic(endGame.end_game_uid, triggerPlayer, isMyTurn);
      _gameAchTracker.endGameSeen = true;
    }
    _prevEndTriggered = endTriggered;

    // score badge
    if (me) updateScoreBadge(me.score ?? 0, me.hand_count ?? (Array.isArray(me.hand) ? me.hand.length : 0));

    // name badge
    const nameEl = document.getElementById("pv-my-name-badge");
    if (me && !nameEl.textContent) nameEl.textContent = me.name;

    // waiting room overlay: show during lobby phase, hide once game starts
    // Show the waiting room whenever the room is still in lobby phase.
    // This applies to both normal and competitive games, compMode must NOT
    // skip it, because competitive rooms also need all 4 seats filled before
    // the host can start. (compMode=true was previously blocking the waiting
    // room for competitive lobbies, causing an instant empty-game jump.)
    if (phase === "lobby") {
      const startFn = async () => {
        const r = await apiPost(`/api/rooms/${roomId}/start`,
          { seat_token: compMode ? (compTokens[compMySeats[0]] || getSeatToken()) : getSeatToken(),
            host_token: compMode ? compHostToken || getHostToken() : getHostToken(),
            create_key: getCreateKey() },
          { timeoutMs: 8000 });
        if (!r.ok) showToast("Could not start: " + (r.data?.error || r.status), "err");
        refreshState();
      };
      // Pass ALL seats so the waiting room shows who has joined.
      const lobbySeats = Array.isArray(payload.seats) ? payload.seats : [];
      // Authoritative competitive flag from the server (set only when the room
      // was created competitive); fall back to the local compMode mirror.
      const isCompetitiveRoom = Boolean(payload?.room?.competitive) || !!compMode;
      const isQuickPlayRoom = Boolean(payload?.room?.quick_play);
      const viewerIsHost = Boolean(
        payload?.viewer?.is_host
        || (compMode ? compHostToken || getHostToken() : getHostToken())
      );
      showWaitingRoom(
        roomId,
        viewerIsHost,
        payload?.room?.visibility,
        isQuickPlayRoom
      );
      updateWaitingRoom(lobbySeats, Boolean(payload.can_start), startFn,
        viewerIsHost,
        isCompetitiveRoom,
        isQuickPlayRoom);
      // NOTE: the game NEVER auto-starts. The host must click Start Game.
    } else {
      hideWaitingRoom();
      try { window._igcpSetVisible?.(true); } catch {}
      try { window._bsSetVisible?.(true); } catch {}
    }

    // turn banner + "your turn" toast
    const banner = document.getElementById("pv-turn-banner");
    const endBtn = document.getElementById("pv-end-turn-inline");
    if (endTriggered && isMyTurn) {
      // Trigger player still has their turn, make it obvious they need to act
      banner.className = "my-turn";
      banner.textContent = "★ YOUR FINAL TURN, draw or play a card! ★";
      endBtn.classList.add("pulse-glow");
      setPlayAgainCallout(turnWaitsOnEndTurn(lw) && !_staleWindow);
    } else if (endTriggered) {
      banner.className = "endgame";
      const left = endGame.final_turns_remaining;
      banner.textContent = `⚠ END GAME, ${Number.isFinite(left) ? left+" final turn(s) left" : "Final round"}`;
      endBtn.classList.remove("pulse-glow");
      setPlayAgainCallout(false);
    } else if (isMyTurn) {
      const isReplayTurn = Boolean(lw.is_replay_turn);
      // The banner announces the extra turn at the TOP of the screen; the
      // callout repeats it over the End Turn button at the bottom, which is
      // where the player actually has to do something to hand the turn on.
      // The callout also covers the Hermit Crab / Sea Turtle open window,
      // which the banner does not announce at all: see turnWaitsOnEndTurn.
      setPlayAgainCallout(turnWaitsOnEndTurn(lw) && !_staleWindow);
      if (!_staleWindow) {
        banner.className = "my-turn";
        if (compMode) {
          // compGetHandName is the ONE source of hand names (seat-numbered
          // Hand 1–4, and whatever the player renamed them to). The banner used
          // to number my hands 1/2 on its own, so P2's "Hand 3" showed up here
          // as "HAND 1" and a renamed hand never appeared at all.
          const activeSeat = Number(payload.active_action_seat);
          const myName = compMySeats[0] < 2 ? compP1Name : compP2Name;
          banner.textContent = `✦  ${myName.toUpperCase()}, ${compGetHandName(activeSeat).toUpperCase()}  ✦`;
        } else if (isReplayTurn) {
          banner.textContent = "★ PLAY AGAIN, take another turn! ★";
        } else {
          banner.textContent = "✦  YOUR TURN  ✦";
        }
        endBtn.classList.add("pulse-glow");
      }
      // Track Play Again for the Horned Puffin avatar regardless of the window.
      if (!_prevReplayTurn && isReplayTurn && _gameAchTracker) _gameAchTracker.playAgainUses = (_gameAchTracker.playAgainUses || 0) + 1;
      _prevReplayTurn = isReplayTurn;
    } else if (compMode && compMySeats.includes(Number(payload.active_action_seat))) {
      // Competitive handoff: the turn HAS come to one of my hands, but this
      // payload was fetched with the other hand's token so viewer.can_act is
      // still false. The corrective re-fetch (see applyServerPayload) is already
      // in flight: say what's happening instead of flashing "their turn…".
      banner.className = "their-turn";
      banner.textContent = `✦  Switching to ${compGetHandName(Number(payload.active_action_seat))}…  ✦`;
      endBtn.classList.remove("pulse-glow");
      setPlayAgainCallout(false);
    } else {
      banner.className = "their-turn";
      // Competitive: while the opponent plays, the board has already moved on to
      // the hand I play NEXT (the server switches it the moment my turn ends).
      // Say which hand that is, or the wait reads as "why did my board change?".
      const _nextHand = (compMode && mySeatIdx !== null && compMySeats.includes(mySeatIdx))
        ? compGetHandName(mySeatIdx) : "";
      banner.textContent = _nextHand
        ? `${_nextHand} is up next  ·  ${current ? current + "'s turn…" : "waiting…"}`
        : (current ? `${current}'s turn…` : "Waiting…");
      endBtn.classList.remove("pulse-glow");
      setPlayAgainCallout(false);
      _lastActionMs = 0; // confirmed not our turn, reset grace window
    }
    _prevTurnIdx = state.turn_index;
    // Razorbill Auk avatar: the "same turn" window ends when it's no longer my turn.
    if (!isMyTurn && _gameAchTracker) _gameAchTracker.razorbillThisTurn = 0;

    // status bar
    if (mustDiscard) {
      setStatus(`Discard exactly ${discardExcess} card(s), cannot go below 10`);
    } else if (isMyTurn) {
      setStatus("Cast your line");
    } else {
      setStatus(payload.status_note || `Waiting for ${current}…`);
    }

    // deck count, shown beside the deck + in the hover tooltip, NEVER printed on
    // the card-back art itself.
    const deckNum = Number(state.deck_remaining ?? state.deck_size ?? state.deck_count ?? (Array.isArray(state.deck)?state.deck.length:0));
    const _deckLbl = deckNum === 1 ? "1 card" : `${deckNum} cards`;
    document.getElementById("pv-deck-num").textContent = _deckLbl;
    const _deckTipEl = document.getElementById("pv-deck-tip");
    if (_deckTipEl) _deckTipEl.textContent = `${_deckLbl} left in the deck`;
    const _deckPileEl = document.getElementById("pv-draw-deck");
    if (_deckPileEl) _deckPileEl.title = `${_deckLbl} left, click to draw`;
    const _deckFaceEl = document.getElementById("pv-deck-count-face");
    if (_deckFaceEl) _deckFaceEl.style.opacity = deckNum > 0 ? "" : "0.3";

    // hand entry map, pull symbol up to top level for payment matching
    handEntryMap.clear();
    if (me && Array.isArray(me.hand)) {
      for (const entry of me.hand) {
        const faceData = Array.isArray(entry.faces) && entry.faces.length > 0 ? entry.faces[0] : entry;
        const faceUid = entry.face_uid ?? faceData.uid ?? entry.uid;
        handEntryMap.set(Number(entry.entry_uid ?? entry.uid ?? faceUid), {
          ...entry, uid: faceUid, symbol: faceData.symbol || entry.symbol || ""
        });
      }
    }

    const freePlaySpecies = Array.isArray(lw.free_play_species) ? lw.free_play_species : [];
    const tarponActive = Boolean(lw.tarpon_discard_active);

    // Tarpon avatar: count discard cycles where a full 9–10 card hand was
    // emptied into the Pool via Tarpon.
    try {
      const myHandNow = Number(me?.hand_count ?? (Array.isArray(me?.hand) ? me.hand.length : 0));
      if (!_prevTarponActive && tarponActive) {
        // Phase just began, the pre-Tarpon hand was the previous render's count.
        _tarponStartHand = Math.max(_lastHandCount, myHandNow);
        selectedDiscard.clear();   // start each Tarpon cycle with a clean selection
      }
      if (tarponActive && _gameAchTracker && myHandNow === 0) {
        _gameAchTracker.tarponHandHitZero = true;
      }
      if (_prevTarponActive && !tarponActive) {
        selectedDiscard.clear();   // phase ended, don't leak picks into a later discard
        if (_gameAchTracker) {
          // Count only if the hand was full (9–10) and emptied entirely.
          if (_gameAchTracker.tarponHandHitZero && _tarponStartHand >= 9) {
            _gameAchTracker.tarponFullDiscards = (_gameAchTracker.tarponFullDiscards || 0) + 1;
          }
          _gameAchTracker.tarponHandHitZero = false;
        }
      }
      _prevTarponActive = tarponActive;
      _lastHandCount = myHandNow;
    } catch {}

    // ── Card movement animation pre-pass ─────────────────────────
    // Snapshot pool slot rects BEFORE renderPool wipes them, then diff
    // pool/hand counts so we can fly removed pool cards, hook-reveal deck
    // draws, and ripple-reveal newly-added pool cards after render.
    const _animOldPoolRects = _snapshotPoolRectsForAnim();
    const _animDiff = _computeDrawAnimDiff(players, Array.isArray(state.pool) ? state.pool : []);
    // Board-clear tide: when the Pool overflows every card is washed out to the
    // discard pile in one step. Detect that from the discard-pile count jumping
    // by ≥10 (see _poolOverflowCleared, reliable even when the Pool lands
    // non-empty afterward), capture the doomed cards now, before renderPool
    // wipes them, and let the tide own that exit, so we don't also fly those
    // same cards toward a player's avatar.
    const _overflowCleared = _poolOverflowCleared(Number(state.discard_pile_count ?? state.discard_count ?? 0));
    const _tideSnap = _captureTidePoolClear(_overflowCleared);
    if (_tideSnap) _animDiff.removedPoolUids = [];
    // Snapshot prev hand UIDs before renderHand mutates _prevHandUIDs.
    const _animPrevHandUIDs = new Set(_prevHandUIDs);
    if (_animDiff.addedPoolUids.length) _pvAnim._suppressFlipIn = true;

    // ── Surf's Up!! sync from server seat snapshot ───────────
    try {
      const seatsArr = Array.isArray(payload.seats) ? payload.seats : [];
      _latestSeatsForSurf = seatsArr;
      const _v = payload.votes;
      _latestVotes = (_v && typeof _v === "object")
        ? { ballot_seat: _v.ballot_seat ?? null,
            kick: Array.isArray(_v.kick) ? _v.kick : [],
            skip: (_v.skip && typeof _v.skip === "object") ? _v.skip : null }
        : { ballot_seat: null, kick: [], skip: null };
      // The buttons live in the action bar, not on a seat, so nothing else
      // redraws them: they have to be repainted here or they show the tally
      // from whenever they were last touched.
      try { updateVoteButtons(); } catch (_) {}
      const mySeat = (Number.isInteger(myIdx)) ? seatsArr.find(s => s && s.index === myIdx) : null;
      const wasAway = _imAway;
      _imAway = Boolean(mySeat && mySeat.is_away);
      if (wasAway !== _imAway) _updateSurfBtnLabel();
      // If I just returned (away→not away), reset idle timer and maybe nudge to discard.
      if (wasAway && !_imAway) {
        resetIdleTimer();
        const myHandCount = (me && Array.isArray(me.hand)) ? me.hand.length : 0;
        if (myHandCount > 10) {
          _showWelcomeBackToast("Welcome back! Discard down to 10 cards before continuing.");
        } else {
          _showWelcomeBackToast("Welcome back!");
        }
      }
      // Turn boundary, reset idle timer when active player changes
      const aas = payload.active_action_seat;
      if (aas !== _prevActiveSeatForIdle) {
        _prevActiveSeatForIdle = aas;
        resetIdleTimer();
      }
    } catch (e) {}

    // ── AFK-vote challenge sync ──────────────────────────────────
    // Server flags afk_challenge.seat when >=50% of the other active players
    // report the current player AFK. If that's ME, show the 20s "Are you
    // still here?" popup; clearing the challenge (resolve/cancel) hides it.
    try {
      const ch = payload.afk_challenge;
      const challengingMe = ch && Number.isInteger(myIdx) && Number(ch.seat) === Number(myIdx);
      if (challengingMe && Date.now() >= _afkSuppressUntil) {
        _showAfkChallenge(Number(ch.remaining));
      } else {
        _hideAfkChallenge();
      }
    } catch (e) {}

    renderPool(Array.isArray(state.pool) ? state.pool : [], legalActions);
    _pvAnim._suppressFlipIn = false;
    renderOpponents(players.filter(p => p.index !== myIdx), state.turn_index);
    renderMyBoard(me, legalActions, isMyTurn);
    renderHand(me, legalActions, mustDiscard, discardExcess);
    renderPlayerSeats(players, state.turn_index, myIdx);
    // Make sure the server has our current avatar + background for this seat (self-throttled).
    if (myIdx != null) { try { pushMySeatAvatar(); } catch (e) {} try { pushMySeatBackground(); } catch (e) {} }
    renderActionBar(legalActions, isMyTurn, mustDiscard, discardExcess, freePlaySpecies, tarponActive);
    renderGuideBar(me, legalActions, isMyTurn, mustDiscard, discardExcess, freePlaySpecies, tarponActive);
    try { window._applyStrategyHighlights && window._applyStrategyHighlights(); } catch (e) {}
    // The guide bar and the phase banners come and go on their own, and
    // renderHand() early-returns when the hand itself did not change, so the
    // column has to be re-fitted here as well: a banner appearing is exactly
    // the moment the bottom of the screen used to eat the hand.
    try { fitGameColumn(); } catch (e) {}
    try { updateBottomDockOffset(); } catch (e) {}

    // Fire the animations after layout settles.
    requestAnimationFrame(() => {
      try {
        _runDrawAnimations({
          oldPoolRects: _animOldPoolRects,
          removedPoolUids: _animDiff.removedPoolUids,
          addedPoolUids:   _animDiff.addedPoolUids,
          handDeltas:      _animDiff.handDeltas,
          prevHandUIDs:    _animPrevHandUIDs,
          players, myIdx,
          prevTurnIdx: _prevTurnIdx,
          curTurnIdx: Number.isInteger(state.turn_index) ? state.turn_index : null,
        });
        _pvAnim.applyPendingRippleReveals();
        if (_tideSnap) _playTideSweep(_tideSnap);
      } catch (e) { /* never block render on animation issues */ }
      _prevHandCountsForAnim = _animDiff.newHandCounts;
    });
    // undo button: always visible; disabled+dimmed when not eligible
    const undoInfo = payload.undo || {};
    const undoBtn = document.getElementById("pv-undo-btn");
    if (undoBtn) {
      // Clear the AFK-forced flag once it's no longer this player's turn,
      // the forced draw has resolved and future turns start fresh.
      if (!isMyTurn) _afkForced = false;
      // eligible_seat is a seat index; compare to mySeatIdx (never game index).
      // Competitive: the view moves to your OTHER hand the instant your turn
      // ends, so the hand holding the undo is normally NOT the hand on screen.
      // The undo belongs to the person, not the hand: accept either of my two
      // seats (the click handler already sends the eligible seat's own token).
      const undoIsMine = mySeatIdx !== null && (
        mySeatIdx === undoInfo.eligible_seat
        || (compMode && Array.isArray(compMySeats)
            && compMySeats.includes(mySeatIdx)
            && compMySeats.includes(undoInfo.eligible_seat))
      );
      // Block undo when the action was auto-drawn due to an AFK vote (player did not interact).
      // Also block while a request is already in flight (undoInfo.requested), an AI
      // mid-turn may still be picking it up, so a second click would be a no-op.
      const canUndo = Boolean(undoInfo.valid) && !Boolean(undoInfo.requested) && undoIsMine && !_afkForced;
      undoBtn.style.display = "";
      undoBtn.disabled = !canUndo;
      undoBtn.title = _afkForced
        ? "Undo is not available, your cards were drawn automatically because you did not respond to the AFK vote."
        : "Undo your last turn, stays available through bot turns; only locks once another human plays after you";
    }

    renderLog(payload.log_tail);
    updateMenuScores(players, myIdx);
    updateCompMenuHands(players, payload.active_action_seat);
    const _mrc = document.getElementById("pv-menu-room-code");
    if (_mrc) _mrc.textContent = roomId || "-";
    const _termBtn = document.getElementById("pv-menu-terminate-btn");
    if (_termBtn) _termBtn.style.display = (payload.viewer?.is_host || Boolean(getHostToken())) ? "" : "none";
    try { if (typeof window._syncAiSpeedBar === "function") window._syncAiSpeedBar(payload); } catch (e) {}

    const discBanner = document.getElementById("pv-discard-banner");
    if (mustDiscard) {
      discBanner.textContent = `Discard exactly ${discardExcess} card(s) to return to 10, click cards then Confirm`;
      discBanner.classList.add("visible");
    } else {
      discBanner.classList.remove("visible");
    }

    // end game overlay. Capture any competitive forfeit result first so the
    // ranked-result handler records the win/loss by forfeit (not by score).
    _forfeitResult = (payload.forfeit && typeof payload.forfeit === "object") ? payload.forfeit : null;
    renderEndGame(payload.winner || null, Array.isArray(payload.final_scores) ? payload.final_scores : []);

    // chat, once shown for this game, never re-hide it from a later poll tick
    // (a single stale/transient "lobby" phase read must not strand the button
    // hidden with nothing left to click; open/close stays purely local per player).
    const chatBtn = document.getElementById("pv-chat-btn");
    if (phase !== "lobby") {
      chatBtn.style.display = "";
      document.getElementById("pv-chat-panel").classList.toggle("open", _chatPanelOpen);
    }
    const chatMsgs = Array.isArray(payload.chat_messages) ? payload.chat_messages : [];
    renderChatMessages(chatMsgs);
    if (_chatPanelOpen && _chatView === "room") {
      const chatTitle = document.getElementById("pv-chat-title");
      if (chatTitle) chatTitle.textContent = pvcRoomChatLabels().title;
    }
    const chatPlayers = phase === "lobby"
      ? (Array.isArray(payload.seats) ? payload.seats : [])
          .filter(seat => seat.kind === "human" && seat.claimed_name)
          .map(seat => ({ index: seat.index, name: seat.claimed_name }))
      : players;
    updateChatTargetOptions(chatPlayers, mySeatIdx ?? myIdx);

    // Spectator list (shown to everyone; spectators have isSpectating()===true)
    if (Array.isArray(payload.spectators)) {
      _specRenderSpectatorList(payload.spectators);
    }

    // If we are spectating, handle board-view on seat click and check for kick
    if (isSpectating()) {
      _specShowPanel(true);
      // Keep the server holding our current icon + background (self-throttled),
      // the same guarantee a seated player gets on every poll.
      try { pushMySeatAvatar(); } catch (e) {}
      try { pushMySeatBackground(); } catch (e) {}
      // Detect if we've been kicked (our token gone, server won't return ok)
      // The poll error path handles room not found; kicked spectators get a 403
      // which is caught by the applyServerPayload guard. If state has spectator:true
      // but our token is no longer in the spectators list, we've been kicked.
      const stillInList = (payload.spectators || []).some(s => {
        // Server sends token_tail for display; we compare name as best-effort fallback
        return s._token === _spectatorToken || s.token_tail === _spectatorToken.slice(-6);
      });
      if (payload.spectator === true && !stillInList && (payload.spectators || []).length >= 0) {
        // Token was valid (got spectator state) but we're not in the list, kicked.
        // Guard: only trigger if spectators array is present and populated by server.
        if (payload.spectators !== undefined) {
          leaveSpectator();
          showToast("You were removed from spectator mode by player vote.", "err");
        }
      }

      // Wire seat avatar clicks to view that player's board
      document.querySelectorAll(".pv-seat[data-player-index]").forEach(seat => {
        if (seat._specWired) return;
        seat._specWired = true;
        seat.addEventListener("click", () => {
          const idx = Number(seat.dataset.playerIndex);
          _spectatorViewingIdx = idx;
          const p = players.find(pl => pl.index === idx);
          const lbl = document.getElementById("spec-viewing-label");
          if (lbl) {
            lbl.textContent = `Viewing ${p ? (p.name || `Player ${idx + 1}`) : `Player ${idx + 1}`}'s board`;
            lbl.style.display = "";
          }
          if (p && typeof openBoardFocus === "function") {
            // Show the read-only board overlay (#pv-board-focus) for this player.
            // (Was referencing a non-existent "board-focus-overlay" element and
            // an "_openBoardFocus" function, so clicking a seat did nothing.)
            try { openBoardFocus(p); } catch (e) { console.warn("[spectate] openBoardFocus failed:", e); }
          }
        });
      });
    }
  }

  // ── Animation state ────────────────────────────────────────────
  let _prevHandUIDs    = new Set();
  let _prevBoardCards  = new Set(); // "oceanUid|dir|idx|faceUid"

  // ── Pool renderer ──────────────────────────────────────────────
  let _prevPoolUids = [];
  let _latestPool = [];
  let _latestPoolActions = [];
  let _poolDrawActions = null; // cached draw actions for deck-click handler
  // Hand-over-10 draw warning state
  let _drawWarnBypass = false;       // set true momentarily after user confirms
  let _pendingDrawAction = null;     // the draw action awaiting user confirmation

  // ══ Card-movement animation module ════════════════════════════════
  // Hook Reveal (deck), pool-to-player fly, Ripple Reveal (pool entry).
  // State diff in renderPayload feeds the animation queue.
  const _pvAnim = (function () {
    const layer = () => document.getElementById("pv-anim-layer");
    let running = 0;
    let _suppressFlipIn = false;
    const pendingPoolReveals = new Map();   // faceUid → true (cards to ripple in)

    function isBusy() { return running > 0; }

    function rectOf(el) {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { left: r.left, top: r.top, width: r.width, height: r.height };
    }

    function deckRect() {
      const face = document.querySelector("#pv-draw-deck .pv-deck-face");
      return rectOf(face) || rectOf(document.getElementById("pv-draw-deck"));
    }

    function poolWrapRect() {
      return rectOf(document.getElementById("pv-pool-wrap"));
    }

    function playerAnchorRect(playerIdx, isLocal) {
      // Local player: land in hand zone. Others: land at avatar.
      if (isLocal) {
        const hz = document.getElementById("pv-hand-zone") || document.getElementById("pv-hand");
        return rectOf(hz);
      }
      const seat = document.querySelector(`.pv-seat[data-player-index="${playerIdx}"] .pv-seat-avatar-wrap`);
      return rectOf(seat) || rectOf(document.querySelector(`.pv-seat[data-player-index="${playerIdx}"]`));
    }

    function makeAnimCard(faceUid, faceDown) {
      const card = document.createElement("div");
      card.className = "pv-anim-card" + (faceDown ? " face-down" : "");
      const face = document.createElement("div");
      face.className = "pv-anim-face";
      if (faceUid) {
        const img = document.createElement("img");
        img.src = imagePathForUid(faceUid); img.alt = "";
        face.appendChild(img);
      }
      const back = document.createElement("div");
      back.className = "pv-anim-back";
      card.appendChild(face);
      card.appendChild(back);
      return card;
    }

    // Animate a card from one rect to another along a curved (hook) path.
    // mode: "hook" (deck draw - flips mid-flight) | "straight" (pool draw - face-up).
    function flyCard(fromRect, toRect, opts = {}) {
      return new Promise((resolve) => {
        if (!fromRect || !toRect) { resolve(); return; }
        const mode = opts.mode || "straight";
        const faceUid = opts.faceUid || 0;
        const startFaceDown = mode === "hook";
        const duration = Math.max(280, Math.min(620, opts.duration || 420));
        const card = makeAnimCard(faceUid, startFaceDown);
        if (mode === "hook") card.classList.add("hook-trail");

        const fromCx = fromRect.left + fromRect.width / 2;
        const fromCy = fromRect.top  + fromRect.height / 2;
        const toCx   = toRect.left   + toRect.width  / 2;
        const toCy   = toRect.top    + toRect.height / 2;
        // Scale start to match source thumbnail size, end at target hand size
        const startScale = Math.max(.4, Math.min(1, (fromRect.width || 70) / 90));
        const endScale   = Math.max(.4, Math.min(1, (toRect.width || 90) / 200));

        card.style.left = (fromCx - 45) + "px";
        card.style.top  = (fromCy - 63) + "px";
        card.style.transform = `scale(${startScale}) rotate(0deg)`;
        card.style.opacity = "1";

        const host = layer();
        if (!host) { resolve(); return; }
        host.appendChild(card);
        running += 1;

        // Single curved path via Web Animations API. Mid keyframe is the arc apex.
        requestAnimationFrame(() => {
          const midX = (fromCx + toCx) / 2;
          const midY = Math.min(fromCy, toCy) - Math.max(50, Math.abs(toCx - fromCx) * 0.18);
          const dx1 = midX - fromCx, dy1 = midY - fromCy;
          const dx2 = toCx - fromCx, dy2 = toCy - fromCy;
          const midScale = (startScale + endScale) / 2 * 1.08;
          const midRot = mode === "hook" ? 180 : 3;
          const endRot = mode === "hook" ? 360 : 0;

          const keyframes = [
            { transform: `translate(0,0) scale(${startScale}) rotate(0deg)`, opacity: 1 },
            { transform: `translate(${dx1}px,${dy1}px) scale(${midScale}) rotate(${midRot}deg)`, opacity: 1, offset: 0.55 },
            { transform: `translate(${dx2}px,${dy2}px) scale(${endScale}) rotate(${endRot}deg)`, opacity: 1 },
          ];
          const anim = card.animate(keyframes, { duration, easing: "cubic-bezier(.32,.72,.18,1.05)", fill: "forwards" });
          anim.onfinish = () => {
            card.style.transition = "opacity .18s ease";
            card.style.opacity = "0";
            setTimeout(() => { card.remove(); running = Math.max(0, running - 1); resolve(); }, 180);
          };
        });
      });
    }

    function playRippleAt(rect) {
      const host = layer();
      if (!host || !rect) return;
      const size = Math.max(rect.width, rect.height) * 1.2;
      const r = document.createElement("div");
      r.className = "pv-ripple";
      r.style.width = size + "px"; r.style.height = size + "px";
      r.style.left = (rect.left + rect.width / 2 - size / 2) + "px";
      r.style.top  = (rect.top  + rect.height / 2 - size / 2) + "px";
      host.appendChild(r);
      setTimeout(() => r.remove(), 600);
    }

    // After renderPool runs, surface any new cards that should ripple in.
    function applyPendingRippleReveals() {
      if (!pendingPoolReveals.size) return;
      const wrap = document.getElementById("pv-pool-wrap");
      if (!wrap) { pendingPoolReveals.clear(); return; }
      let delay = 0;
      pendingPoolReveals.forEach((_v, uid) => {
        const el = wrap.querySelector(`.pv-pool-card[data-face-uid="${uid}"]`);
        if (!el) return;
        el.classList.remove("flip-in");
        el.style.opacity = "0";
        setTimeout(() => {
          const r = el.getBoundingClientRect();
          playRippleAt({ left: r.left, top: r.top, width: r.width, height: r.height });
          el.style.opacity = "";
          el.classList.add("surfacing");
          el.addEventListener("animationend", () => el.classList.remove("surfacing"), { once: true });
        }, delay);
        delay += 110;
      });
      pendingPoolReveals.clear();
    }

    function queuePoolReveal(uid) { pendingPoolReveals.set(Number(uid), true); }

    // Ripple ring at each newly-arrived hand card. Card surfacing comes from
    // the .deal-in class on the card itself (handSurfaceIn keyframes).
    function rippleNewHandCards(prevHandUIDsSet) {
      const cards = document.querySelectorAll("#pv-hand .pv-hand-card.deal-in");
      if (!cards.length) return;
      let delay = 0;
      cards.forEach((el) => {
        setTimeout(() => {
          const r = el.getBoundingClientRect();
          if (r.width <= 0) return;
          playRippleAt({ left: r.left, top: r.top, width: r.width, height: r.height });
        }, delay);
        delay += 90;
      });
    }

    return { flyCard, playRippleAt, queuePoolReveal, applyPendingRippleReveals,
             rippleNewHandCards,
             isBusy, deckRect, poolWrapRect, playerAnchorRect, rectOf,
             get _suppressFlipIn() { return _suppressFlipIn; },
             set _suppressFlipIn(v) { _suppressFlipIn = !!v; } };
  })();

  // ── Tide sweep: board-clear animation ────────────────────────────
  // The shared Pool caps at 10 cards; the moment it fills, the server washes
  // every card to the discard pile in a single step (the client sees the pool
  // jump from 9 → 0). We mark that with an incoming tide: a foam-crested wave
  // rolls in from the left and drags each card out to sea as the crest reaches
  // it. Fires only on that overflow clear, so it stays a rare, welcome flourish.
  let _tideSweepActive = false;
  // Last-seen discard-pile size, used to detect the overflow clear. Reset to
  // null on game/room change in _leaveGameCleanup so a stale count from a
  // previous game can never spuriously fire the tide.
  let _prevDiscardCount = null;

  // Was there a Pool overflow clear between the last render and this one?
  // The server washes the whole Pool to the discard pile the instant it hits
  // 10 cards, and it adds cards one at a time, so after a batch discard the
  // Pool usually lands NON-empty (e.g. 8 → 9 → 10-clear → 1). Watching for
  // pool→0 therefore misses the clear most of the time. Instead we watch the
  // discard-pile count: a wash moves exactly 10 cards into it, and nothing
  // else grows it by that much mid-game (drafting from the pool moves cards to
  // a hand, not the discard pile), so a jump of ≥10 is an unambiguous clear.
  function _poolOverflowCleared(curDiscardCount) {
    const cur = Number.isFinite(curDiscardCount) ? curDiscardCount : 0;
    const prev = _prevDiscardCount;
    _prevDiscardCount = cur;
    if (prev == null) return false;        // first render, no baseline yet
    return (cur - prev) >= 10;
  }

  // Snapshot the doomed pool cards (position + art) right before renderPool
  // wipes the DOM. Returns null unless this render is a real overflow clear.
  function _captureTidePoolClear(overflowCleared) {
    try {
      if (!overflowCleared) return null;   // only fires on the overflow clear
      if (_tideSweepActive) return null;
      if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return null;
      const wrap = document.getElementById("pv-pool-wrap");
      if (!wrap) return null;
      // Wash away whatever cards are on screen (the pre-clear Pool). Usually a
      // full-ish board; if the clear tipped over from a low pool we simply wash
      // the fewer cards that were showing, still reads as the board sweeping out.
      const cards = Array.from(wrap.querySelectorAll(".pv-pool-card"));
      const cells = cards.map(el => {
        const r = el.getBoundingClientRect();
        const img = el.querySelector("img");
        return { left: r.left, top: r.top, width: r.width, height: r.height,
                 src: img ? img.src : "" };
      }).filter(c => c.width > 0 && c.height > 0);
      if (!cells.length) return null;      // nothing on screen to wash
      const left   = Math.min(...cells.map(c => c.left));
      const right   = Math.max(...cells.map(c => c.left + c.width));
      const top    = Math.min(...cells.map(c => c.top));
      const bottom = Math.max(...cells.map(c => c.top + c.height));
      return { cells, left, right, top, bottom };
    } catch (e) { return null; }
  }

  // Play the tide: clone the washed cards into the fixed anim layer (the real
  // pool underneath is already empty), then roll a wave across them left→right.
  function _playTideSweep(snap) {
    const host = document.getElementById("pv-anim-layer");
    if (!host || !snap || !snap.cells.length) return;
    _tideSweepActive = true;

    const padY    = 34;   // wave reaches well above/below the two card rows
    const leadIn  = 56;   // crest starts just left of the leftmost card
    const trailOut = 70;  // …and finishes well past the rightmost card
    const bandTop  = snap.top - padY;
    const bandH    = (snap.bottom - snap.top) + padY * 2;
    const crestStart = snap.left - leadIn;    // crest x at t = 0
    const crestEnd   = snap.right + trailOut; // crest x at t = D
    const span = Math.max(1, crestEnd - crestStart);
    // Constant-velocity sweep so each card's wash-away lines up with the crest.
    // Weighty and slow, this only fires on a full-board clear, so let the tide
    // take its time rolling across.
    const D = Math.round(Math.min(2400, Math.max(1600, span * 2.9)));
    const waveW = Math.min(440, Math.max(260, span * 0.7));

    const nodes = [];

    // 1) Clone each pool card and time its wash + spray to when the crest arrives.
    snap.cells.forEach(c => {
      const cx = c.left + c.width / 2;
      const arrival = Math.max(0, Math.min(1, (cx - crestStart) / span));
      const delay = Math.round(arrival * D);
      const el = document.createElement("div");
      el.className = "pv-tide-card";
      el.style.left = c.left + "px";
      el.style.top  = c.top + "px";
      el.style.width  = c.width + "px";
      el.style.height = c.height + "px";
      el.style.animationDelay = delay + "ms";
      if (c.src) {
        const img = document.createElement("img");
        img.src = c.src; img.alt = "";
        el.appendChild(img);
      }
      host.appendChild(el);
      nodes.push(el);

      // Spray: a handful of foam droplets kicked up from the card as the crest
      // reaches it, they arc up (mostly forward, in the sweep direction) and
      // fall back, so each card literally bursts into foam as it's washed away.
      for (let i = 0; i < 5; i++) {
        const d = document.createElement("div");
        d.className = "pv-tide-drop";
        const sz = (5 + Math.random() * 7).toFixed(1);
        d.style.width = d.style.height = sz + "px";
        d.style.left = (c.left + c.width  * (0.2 + Math.random() * 0.6)) + "px";
        d.style.top  = (c.top  + c.height * (0.15 + Math.random() * 0.4)) + "px";
        d.style.setProperty("--dx", Math.round((Math.random() * 2 - 0.4) * 26) + "px");
        d.style.setProperty("--dy", -(34 + Math.round(Math.random() * 40)) + "px");
        d.style.setProperty("--drop-dur", (560 + Math.round(Math.random() * 260)) + "ms");
        d.style.animationDelay = (delay + Math.round(Math.random() * 90)) + "ms";
        host.appendChild(d);
        nodes.push(d);
      }
    });

    // 2) The wave, a translucent body with a churning foam crest on its leading
    //    (right) edge. Its right edge starts at crestStart and sweeps to crestEnd.
    const wave = document.createElement("div");
    wave.className = "pv-tide-wave";
    wave.style.top    = bandTop + "px";
    wave.style.height = bandH + "px";
    wave.style.width  = waveW + "px";
    wave.style.left   = (crestStart - waveW) + "px";
    wave.style.setProperty("--tide-dist", (crestEnd - crestStart) + "px");
    wave.style.setProperty("--tide-dur", D + "ms");
    host.appendChild(wave);
    nodes.push(wave);

    // 3) Clean up once the last card has fully washed away.
    setTimeout(() => {
      nodes.forEach(n => n.remove());
      _tideSweepActive = false;
    }, D + 1100);
  }

  // Snapshot pool slot positions BEFORE renderPool wipes the DOM.
  // Used to fly removed pool cards from their old position.
  function _snapshotPoolRectsForAnim() {
    const map = new Map();
    document.querySelectorAll("#pv-pool-wrap .pv-pool-card").forEach(el => {
      const uid = Number(el.dataset.faceUid || 0);
      if (uid) {
        const r = el.getBoundingClientRect();
        map.set(uid, { left: r.left, top: r.top, width: r.width, height: r.height });
      }
    });
    return map;
  }

  // Compute hand-count deltas vs previous render and pick most-likely recipient
  // for each removed pool card. Returns { handDeltas, removedPoolUids, addedPoolUids }.
  function _computeDrawAnimDiff(players, currentPool) {
    const newHandCounts = {};
    (players || []).forEach(p => {
      newHandCounts[p.index] = Number(p.hand_count ?? (Array.isArray(p.hand) ? p.hand.length : 0));
    });
    const handDeltas = {};
    Object.keys(newHandCounts).forEach(k => {
      const prev = (_prevHandCountsForAnim[k] != null) ? _prevHandCountsForAnim[k] : newHandCounts[k];
      handDeltas[k] = newHandCounts[k] - prev;
    });
    const newPoolUids = new Set((currentPool || []).map(e => {
      const f = (Array.isArray(e.faces) && e.faces[0]) ? e.faces[0] : e;
      return Number(f.uid ?? e.entry_uid ?? e.uid);
    }));
    const removed = _prevPoolUids.filter(u => !newPoolUids.has(u));
    const added   = [...newPoolUids].filter(u => !_prevPoolUids.includes(u));
    return { handDeltas, newHandCounts, removedPoolUids: removed, addedPoolUids: added };
  }
  let _prevHandCountsForAnim = {};

  // Run all pending draw animations for this state transition.
  function _runDrawAnimations({ oldPoolRects, removedPoolUids, addedPoolUids, handDeltas, prevHandUIDs, players, myIdx, prevTurnIdx, curTurnIdx }) {
    if (!removedPoolUids.length && !addedPoolUids.length) return;

    // The player who just acted: previous turn index (their hand grew this poll).
    // Fall back to whoever's hand grew the most.
    let recipientIdx = (prevTurnIdx != null && handDeltas[prevTurnIdx] > 0) ? prevTurnIdx : null;
    if (recipientIdx == null) {
      let best = null, bestDelta = 0;
      Object.keys(handDeltas).forEach(k => {
        if (handDeltas[k] > bestDelta) { bestDelta = handDeltas[k]; best = Number(k); }
      });
      recipientIdx = best;
    }

    const totalGrowth = recipientIdx != null ? Math.max(0, handDeltas[recipientIdx] || 0) : 0;
    const deckDrawCount = Math.max(0, totalGrowth - removedPoolUids.length);

    const recipientIsLocal = (recipientIdx != null && recipientIdx === myIdx);

    // 1) Pool draws.
    //    Local recipient: skip the fly, the new hand cards will ripple in (handled by renderHand's .deal-in)
    //    plus we add a ripple ring at each landing spot. The leaving pool slot
    //    already disappears via the next render; a quick lift-off would feel jittery.
    //    Other recipients: fly the actual pool card image toward their avatar.
    removedPoolUids.forEach((uid) => {
      if (recipientIsLocal) return;
      const fromR = oldPoolRects.get(uid);
      if (!fromR || recipientIdx == null) return;
      const toR = _pvAnim.playerAnchorRect(recipientIdx, false);
      _pvAnim.flyCard(fromR, toR, { faceUid: uid, mode: "straight", duration: 440 });
    });

    // 2) Deck draws.
    //    Local recipient: skip the fly, ripple effect happens in the hand.
    //    Other recipients: hook-reveal cards flying from the deck to their avatar.
    if (deckDrawCount > 0 && recipientIdx != null && !recipientIsLocal) {
      const fromR = _pvAnim.deckRect();
      const toR = _pvAnim.playerAnchorRect(recipientIdx, false);
      for (let i = 0; i < deckDrawCount; i++) {
        setTimeout(() => _pvAnim.flyCard(fromR, toR, { faceUid: 0, mode: "hook", duration: 480 }), i * 130);
      }
    }

    // 3) Local hand ripple: ripple ring at each newly arrived hand card position.
    if (recipientIsLocal) {
      // Defer to next frame so renderHand has placed the new cards in the DOM.
      requestAnimationFrame(() => _pvAnim.rippleNewHandCards(prevHandUIDs || _prevHandUIDs));
    }

    // 4) Pool entries: queue ripple-reveal for any added pool cards.
    addedPoolUids.forEach(uid => _pvAnim.queuePoolReveal(uid));
  }

  function _drawFromDeck(drawActions) {
    if (_pvAnim.isBusy()) return;  // wait for current animations to finish
    const act = drawActions.find(a => a.kind==="draw" && Number(a.draw_from_pool)===0);
    if (!act) { showToast("Cannot draw from deck right now.", "warn"); return; }
    submitAction({ ...act, pool_pick_uids: [] });
  }
  function _drawFromPool(drawActions, faceUid) {
    if (_pvAnim.isBusy()) return;  // wait for current animations to finish
    const act = drawActions.find(a => a.kind==="draw" && Number(a.draw_from_pool)===1);
    if (!act) { showToast("Cannot draw from pool right now.", "warn"); return; }
    submitAction({ ...act, pool_pick_uids: [faceUid] });
  }

  function renderPool(pool, actions) {
    _latestPool = pool;
    _latestPoolActions = actions;
    renderPoolModal();
    const wrap = document.getElementById("pv-pool-wrap");
    const curUids = pool.map(e => Number((Array.isArray(e.faces)&&e.faces[0]?e.faces[0].uid:null) ?? e.uid ?? 0));
    const prevSet = new Set(_prevPoolUids);
    _prevPoolUids = curUids;
    cl(wrap);

    // Collect available draw actions
    const drawActions = actions.filter(a => a.kind==="draw");
    _poolDrawActions = drawActions;
    const canDrawPool = drawActions.some(a => Number(a.draw_from_pool) === 1);
    const canDrawDeck = drawActions.some(a => Number(a.draw_from_pool) === 0);
    // Detect second-draw phase: server only returns draw actions when player has drawn 1 already
    const isSecondDraw = drawActions.length > 0 && !actions.some(a => a.kind !== "draw" && a.kind !== "end_turn");

    // Wire deck click: each click draws exactly 1 card from the deck
    const deckPile = document.getElementById("pv-draw-deck");
    if (canDrawDeck && canInteract) {
      deckPile.style.cursor = "pointer";
      deckPile.onclick = () => _drawFromDeck(drawActions);
      deckPile.querySelector(".pv-deck-face").style.borderColor = "var(--cyan)";
    } else {
      deckPile.style.cursor = "default";
      deckPile.onclick = null;
      deckPile.querySelector(".pv-deck-face").style.borderColor = "";
    }

    // Update pick hint
    const hint = document.getElementById("pv-pool-pick-hint");
    if (hint) {
      if (isSecondDraw && canInteract) {
        hint.textContent = "Choose your second card, click the Deck or draw one from the pool";
        hint.classList.add("visible");
      } else {
        hint.classList.remove("visible");
      }
    }

    if (!pool.length) {
      const empty = document.createElement("span");
      empty.style.cssText = "font-size:13px;color:var(--muted);";
      empty.textContent = "The pool is empty";
      wrap.appendChild(empty);
      return;
    }

    pool.forEach((entry) => {
      const face = (Array.isArray(entry.faces) && entry.faces.length > 0) ? entry.faces[0] : entry;
      const faceUid = Number(face.uid ?? entry.entry_uid ?? entry.uid);
      const isNew = !prevSet.has(faceUid);
      const div = document.createElement("div");
      // Skip the legacy flip-in for new cards, Ripple Reveal will play instead.
      div.className = "pv-pool-card" + (isNew && !_pvAnim._suppressFlipIn ? " flip-in" : "");
      div.dataset.faceUid = String(faceUid);
      div.dataset.species = face.species || "";
      if (starText(face.text||"")) div.classList.add("has-star");
      const img = document.createElement("img");
      img.src = imagePathForUid(faceUid); img.alt = face.name||""; img.loading="lazy";
      div.appendChild(img);
      div.title = (canDrawPool && canInteract)
        ? `${face.name || faceUid}, click to draw this card from the pool`
        : (face.name || String(faceUid));

      if (canDrawPool && canInteract) {
        // Each pool card click draws exactly 1 card from the pool immediately
        div.addEventListener("click", (e) => {
          e.stopPropagation();
          _drawFromPool(_poolDrawActions, faceUid);
        });
        div.draggable = true;
        div.addEventListener("dragstart", (e) => {
          e.dataTransfer.effectAllowed = "move";
          e.dataTransfer.setData("application/x-fish-pool-draw", JSON.stringify({ faceUid }));
          div.classList.add("dragging");
        });
        div.addEventListener("dragend", () => div.classList.remove("dragging"));
      } else {
        div.addEventListener("click", (e) => {
          e.stopPropagation();
          openZoom(faceUid, face.name, face.text, face.species);
        });
      }

      wrap.appendChild(div);
    });

    // Hand zone drop target, drag a pool card here to draw it immediately
    const handZone = document.getElementById("pv-hand-zone");
    if (canDrawPool && canInteract) {
      handZone.ondragover = (ev) => {
        if (!ev.dataTransfer.types.includes("application/x-fish-pool-draw")) return;
        ev.preventDefault();
        ev.dataTransfer.dropEffect = "move";
        handZone.classList.add("pool-drag-over");
      };
      handZone.ondragleave = (ev) => {
        if (!handZone.contains(ev.relatedTarget)) handZone.classList.remove("pool-drag-over");
      };
      handZone.ondrop = (ev) => {
        ev.preventDefault();
        handZone.classList.remove("pool-drag-over");
        let data = {};
        try { data = JSON.parse(ev.dataTransfer.getData("application/x-fish-pool-draw") || "{}"); } catch {}
        const uid = Number(data.faceUid);
        if (!uid) return;
        _drawFromPool(drawActions, uid);
      };
    } else {
      handZone.ondragover = null;
      handZone.ondragleave = null;
      handZone.ondrop = null;
      handZone.classList.remove("pool-drag-over");
    }

    // Pool drop zone, drag a hand card here to discard it to the pool (payment)
    const poolArea = document.getElementById("pv-pool-area");
    const discardActions = actions.filter(a => a.kind === "discard_to_pool");
    if (discardActions.length) {
      poolArea.classList.add("can-drop");
      poolArea.title = "Drag a card here to discard it as payment";
    } else {
      poolArea.classList.remove("can-drop");
      poolArea.title = "";
    }
    poolArea.ondragover = discardActions.length ? (ev) => {
      ev.preventDefault(); ev.dataTransfer.dropEffect = "move";
      poolArea.classList.add("drag-over");
    } : null;
    poolArea.ondragleave = () => { poolArea.classList.remove("drag-over"); };
    poolArea.ondrop = discardActions.length ? (ev) => {
      ev.preventDefault();
      poolArea.classList.remove("drag-over");
      let cardData = {};
      try { cardData = JSON.parse(ev.dataTransfer.getData("application/x-fish-card") || "{}"); } catch {}
      const entryUid = Number(cardData.entryUid);
      const faceUid  = Number(cardData.faceUid);
      if (!entryUid && !faceUid) return;
      const act = discardActions.find(a =>
        Number(a.card_uid) === entryUid || Number(a.face_uid) === faceUid
      );
      if (!act) { showToast("Can't discard that card to pool right now.", "warn"); return; }
      submitAction(act);
    } : null;
    try { window._applyStrategyHighlights && window._applyStrategyHighlights(); } catch (e) {}
  }

  // ── Player seat row (6 fixed slots, 3-left / 3-right of hand) ─
  // Self-contained: does NOT reference the IIFE-scoped avatar helpers
  // (AVATAR_OPTIONS / resolveAvatarUrl / _activeProfile), those are
  // private to the auth IIFE and unreachable from this scope, which
  // previously threw a ReferenceError and prevented any seat from
  // rendering. The local player's chosen avatar is read via
  // window.__fishMyAvatarUrl() (exposed by the IIFE) when available.
  const PV_SEAT_AVATARS = [
    "/avatars/mullet.png", "/avatars/sardine.png", "/avatars/flying-fish.png",
    "/avatars/bunker.png", "/avatars/bonito.png",  "/avatars/mahi-mahi.png",
    "/avatars/roosterfish.png", "/avatars/blue-tang.png", "/avatars/clownfish.png",
    "/avatars/blue-marlin.png", "/avatars/barracuda.png", "/avatars/manta-ray.png",
  ];
  function pvSeatHash(s) {
    const t = String(s || "player");
    let h = 0;
    for (let i = 0; i < t.length; i++) h = ((h << 5) - h + t.charCodeAt(i)) | 0;
    return Math.abs(h);
  }
  function pvSeatDefaultAvatar(seed) {
    return PV_SEAT_AVATARS[pvSeatHash(seed) % 12];
  }

  // ── One live source for every face in the game ────────────────
  // The server relays each player's and spectator's CURRENT avatar on every
  // state tick. Resolve every in-game face through here, so someone who
  // changes their icon mid-game changes on ALL of them at once. Each surface
  // used to answer the question its own way and get stuck: a chat line kept
  // the avatar frozen into the message when it was sent, the draw notification
  // and the final standings asked Firestore by nickname behind a 12s cache
  // (and drew a name-hash stranger for anyone without a profile doc), so the
  // seat row was the only place a change actually showed up.
  let _liveAvatarByName = Object.create(null);
  function noteLiveAvatars(players, spectators) {
    const next = Object.create(null);
    (Array.isArray(players) ? players : []).forEach(p => {
      if (p && p.name && p.avatar) next[String(p.name)] = String(p.avatar);
    });
    (Array.isArray(spectators) ? spectators : []).forEach(s => {
      if (!s || !s.name || !s.avatar) return;
      // A spectator's chat lines are sent under a prefixed name (see
      // submit_spectator_chat), so key both spellings or the prefix costs
      // them their face on every line they type.
      next[String(s.name)] = String(s.avatar);
      next["[Spectator] " + String(s.name)] = String(s.avatar);
    });
    _liveAvatarByName = next;
  }
  // The avatar this player is wearing right now, "" if the server hasn't told
  // us one yet. My own equipped icon wins for me: it is already true on this
  // client, while the relayed copy is a server round-trip behind, so without
  // this my own face would lag a tick behind everyone else's view of it.
  function pvLiveAvatar(name) {
    const n = String(name || "");
    if (!n) return "";
    try {
      const mine = latestPayload && latestPayload.viewer && latestPayload.viewer.name;
      if (mine && n === String(mine) && typeof window.__fishMyAvatarUrl === "function") {
        const m = String(window.__fishMyAvatarUrl() || "");
        if (m) return m;
      }
    } catch (e) {}
    return _liveAvatarByName[n] || "";
  }
  // Fingerprint of every face on screen: surfaces that skip redundant
  // re-renders diff this so an avatar change still repaints them. My own
  // equipped icon has to be in here too: it is the one face that changes
  // without the relayed table changing, so leaving it out meant my new icon
  // reached everyone else's copy of my chat lines before it reached mine.
  function pvLiveAvatarKey() {
    let mine = "";
    try {
      if (typeof window.__fishMyAvatarUrl === "function") mine = String(window.__fishMyAvatarUrl() || "");
    } catch (e) {}
    try { return JSON.stringify(_liveAvatarByName) + "|" + mine; } catch (e) { return "|" + mine; }
  }

  // Push our chosen avatar to the server for this seat so every other client
  // renders our own icon (and sees changes immediately). Self-throttled: only
  // sends when the avatar actually changed.
  let _lastPushedAvatar = "";
  function pushMySeatAvatar() {
    if (!roomId) return;
    let myUrl = "";
    try {
      if (typeof window.__fishMyAvatarUrl === "function") myUrl = String(window.__fishMyAvatarUrl() || "");
    } catch (e) { myUrl = ""; }
    let myCard = null;
    try {
      const c = window.__ccMyCard;
      if (c && Number(c.level) > 0) {
        myCard = {
          level: Math.max(0, Math.min(100, Math.round(Number(c.level) || 0))),
          xp: Math.max(0, Math.round(Number(c.xp) || 0)),
          xp_goal: Math.max(0, Math.round(Number(c.xp_goal) || 0)),
          best: Math.max(0, Math.round(Number(c.best) || 0)),
          games: Math.max(0, Math.round(Number(c.games) || 0)),
          title: String(c.title || "").slice(0, 32),
        };
      }
    } catch (e) { myCard = null; }
    // The plate is part of the key: it changes without the avatar changing, and
    // the throttle would otherwise never send the new one.
    const key = roomId + "|" + myUrl + "|" + (myCard ? JSON.stringify(myCard) : "");
    if (!myUrl || key === _lastPushedAvatar) return;
    // Spectating: no seat, but we still have a face in the spectator list and
    // on our chat lines: equip under the spectator token instead.
    if (isSpectating()) {
      _lastPushedAvatar = key;
      try {
        apiPost(`/api/rooms/${_spectatorRoomId}/avatar`,
          { spectator_token: _spectatorToken, avatar: myUrl }, { timeoutMs: 6000 }).catch(() => {});
      } catch (e) {}
      return;
    }
    const tok = (typeof getSeatToken === "function") ? getSeatToken() : "";
    if (!tok) return;
    _lastPushedAvatar = key;
    try {
      // Only send a plate we actually know. The server reads an absent field as
      // "leave it alone", so a client that has not worked its own out yet must
      // not blank numbers the seat is already showing.
      const body = Object.assign({ seat_token: tok, avatar: myUrl }, myCard || {});
      apiPost(`/api/rooms/${roomId}/avatar`, body, { timeoutMs: 6000 }).catch(() => {});
    } catch (e) {}
  }
  window.__fishPushSeatAvatar = pushMySeatAvatar;
  // Both pushes are throttled on "same value as last time". When the session
  // changes hands the next person may be wearing what the last one wore, and
  // the throttle would then send nothing at all, so the memory is cleared with
  // everything else that belonged to the previous identity.
  window.__fishForgetPushedAvatar = function () { _lastPushedAvatar = ""; _lastPushedBg = ""; };

  // Push our equipped background to the server for this seat so every client
  // renders it behind our avatar. Self-throttled like the avatar push.
  let _lastPushedBg = "";
  function pushMySeatBackground() {
    if (!roomId) return;
    let myBg = "";
    try { if (typeof window.__fishEquippedBackground === "function") myBg = String(window.__fishEquippedBackground() || ""); } catch (e) { myBg = ""; }
    const key = roomId + "|" + myBg;
    if (key === _lastPushedBg) return;
    if (isSpectating()) {          // no seat: equip under the spectator token
      _lastPushedBg = key;
      try {
        apiPost(`/api/rooms/${_spectatorRoomId}/background`,
          { spectator_token: _spectatorToken, background: myBg }, { timeoutMs: 6000 }).catch(() => {});
      } catch (e) {}
      return;
    }
    const tok = (typeof getSeatToken === "function") ? getSeatToken() : "";
    if (!tok) return;
    _lastPushedBg = key;
    try {
      apiPost(`/api/rooms/${roomId}/background`, { seat_token: tok, background: myBg }, { timeoutMs: 6000 }).catch(() => {});
    } catch (e) {}
  }
  window.__fishPushSeatBackground = pushMySeatBackground;
  // Called when the player equips/removes a background mid-session.
  window.__fishReportBackground = function () { _lastPushedBg = ""; try { pushMySeatBackground(); } catch (e) {} };

  function renderPlayerSeats(players, turnIndex, myIdx) {
    const leftEl  = document.getElementById("pv-seats-left");
    const rightEl = document.getElementById("pv-seats-right");
    if (!leftEl || !rightEl) return;

    let myAvatarUrl = "";
    try {
      if (typeof window.__fishMyAvatarUrl === "function") {
        myAvatarUrl = String(window.__fishMyAvatarUrl() || "");
      }
    } catch (e) { myAvatarUrl = ""; }

    // Include per-seat background AND my own equipped background in the render
    // key, otherwise equipping/removing a background doesn't change name/score/
    // avatar/turn, the key stays identical, and the seat never re-renders (so a
    // removed background stays stuck on screen).
    let _myBgKey = "";
    try { if (typeof window.__fishEquippedBackground === "function") _myBgKey = String(window.__fishEquippedBackground() || ""); } catch (_) { _myBgKey = ""; }
    const _seatsKey = JSON.stringify(
      (players||[]).map(p=>{const _sm=(_latestSeatsForSurf||[]).find(s=>s&&s.index===p.index);return{i:p.index,n:p.name,s:p.score,hc:p.hand_count??(Array.isArray(p.hand)?p.hand.length:0),av:p.avatar,bg:String(p.background||""),aw:Boolean(_sm&&_sm.is_away),kk:Boolean(_sm&&_sm.kicked)};})
    ) + "|" + turnIndex + "|" + myAvatarUrl + "|" + _myBgKey;
    if (_seatsKey === _seatsRenderKey && leftEl.children.length > 0) return;
    _seatsRenderKey = _seatsKey;
    leftEl.innerHTML  = "";
    rightEl.innerHTML = "";

    for (let slot = 0; slot < 8; slot++) {
      const p = (players || []).find(pl => pl && pl.index === slot) || null;
      const cluster = slot < 4 ? leftEl : rightEl;
      const seat = document.createElement("div");

      if (!p) {
        seat.className = "pv-seat pv-seat-empty";
        const aw = document.createElement("div");
        aw.className = "pv-seat-avatar-wrap";
        aw.textContent = "🔒";
        const nm = document.createElement("div");
        nm.className = "pv-seat-name";
        nm.textContent = "Empty";
        // Score placeholder keeps empty seats the same height as filled ones
        const sc = document.createElement("div");
        sc.className = "pv-seat-score pv-seat-score-empty";
        sc.textContent = "-";
        seat.appendChild(aw);
        seat.appendChild(nm);
        seat.appendChild(sc);
        cluster.appendChild(seat);
        continue;
      }

      const isActive = p.index === turnIndex;
      const isMe     = p.index === myIdx;
      seat.className = "pv-seat"
        + (isActive ? " active-turn" : "")
        + (isMe && !canInteract ? " pv-seat-me-avatar-clickable" : "");
      seat.dataset.playerIndex = String(p.index);

      // Resolve avatar: own → use equipped url directly.
      // Others → check the nick cache first (synchronous) so fast state
      // redraws don't keep reverting to the fallback while the async query
      // is still in-flight. If not cached yet, fall back and kick off the
      // lookup; the next redraw will pick up the cached value synchronously.
      const fallbackAvatar = (typeof pvSeatDefaultAvatar === "function")
        ? pvSeatDefaultAvatar(p.name || `seat${slot}`)
        : PV_SEAT_AVATARS[slot % 12];
      // Authoritative source: each player's OWN avatar carried per-seat in the
      // game state (p.avatar), so every player has a separate icon and a change
      // propagates immediately. For MY seat my local equipped value wins, the
      // same way it does for the background below, the relayed copy is a
      // round-trip behind, so preferring it made my own new icon sit on the old
      // one until the next poll came back.
      let initialUrl = fallbackAvatar;
      if (isMe && myAvatarUrl) initialUrl = myAvatarUrl;
      else if (p.avatar) initialUrl = p.avatar;

      const aw = document.createElement("div");
      aw.className = "pv-seat-avatar-wrap";
      const img = document.createElement("img");
      img.src = _avSrc(initialUrl);
      img.alt = p.name || `Seat ${slot + 1}`;
      img.onerror = () => { img.onerror = null; img.src = "/avatars/mullet.png"; };
      aw.appendChild(img);
      // Exclusive background behind this player's avatar. Mine comes from my
      // equipped selection; others' from the per-seat value the server relays.
      // For my own seat my local equipped value is authoritative, including ""
      // (just removed) which must override any stale server-relayed background,
      // otherwise removal appears to do nothing until the server catches up.
      let seatBg = String(p.background || "");
      if (isMe) {
        try {
          if (typeof window.__fishEquippedBackground === "function") {
            seatBg = String(window.__fishEquippedBackground() || "");
          }
        } catch (_) {}
      }
      _applyAvBg(aw, seatBg);

      const nm = document.createElement("div");
      nm.className = "pv-seat-name";
      const plabel = document.createElement("span");
      plabel.className = "pv-seat-plabel";
      plabel.textContent = `P${p.index + 1}`;
      const nmText = document.createElement("span");
      nmText.textContent = p.name || `P${p.index + 1}`;
      // In-game seats know a display NAME, not a uid, the Prestige sweep
      // resolves either. Seats sit on the dark board, so the readability plate
      // (when one is needed) has to be the dark one.
      if (p.name && !isLikelyAiName(p.name)) {
        nmText.setAttribute("data-cc-pname", p.name);
        nmText.setAttribute("data-cc-surface", "dark");
      }
      nm.appendChild(plabel);
      nm.appendChild(nmText);
      nm.title = `${p.name || `Player ${p.index + 1}`}, report by typing "P${p.index + 1} is AFK"`;

      const sc = document.createElement("div");
      sc.className = "pv-seat-score";
      const hcSeat = p.hand_count ?? (Array.isArray(p.hand) ? p.hand.length : 0);
      sc.textContent = (p.score ?? 0) + " pts · 🃏" + hcSeat;

      seat.appendChild(aw);
      seat.appendChild(nm);
      seat.appendChild(sc);
      if (isMe) {
        const badge = document.createElement("div");
        badge.className = "pv-seat-me-badge";
        badge.textContent = "YOU";
        seat.appendChild(badge);
      }
      // Surf's Up Away / inactive-eligible badges from the seat snapshot
      const _seatMeta = (_latestSeatsForSurf || []).find(s => s && s.index === p.index) || null;
      const _isAway     = Boolean(_seatMeta && _seatMeta.is_away);
      const _isEligible = Boolean(_seatMeta && _seatMeta.inactive_eligible);
      // Removed by vote: the chair is a bot now, and the pill has to say so or
      // the table is left wondering why that player stopped answering.
      if (_seatMeta && _seatMeta.kicked) {
        const kb = document.createElement("div");
        kb.className = "pv-seat-kicked-badge";
        kb.textContent = "Removed";
        kb.title = `${p.name || "This player"} was removed by a vote. A bot is playing their seat.`;
        seat.appendChild(kb);
      }
      if (_isAway) {
        const ab = document.createElement("div");
        ab.className = "pv-seat-away-badge";
        ab.textContent = "🌊 Away";
        seat.appendChild(ab);
      } else if (_isEligible && !isMe && isActive) {
        const db = document.createElement("button");
        db.className = "pv-seat-draw2-btn";
        db.type = "button";
        db.textContent = "Draw 2 Cards";
        db.title = `Draw 2 cards for ${p.name || "this player"} and end their turn`;
        db.addEventListener("click", (ev) => {
          ev.stopPropagation();
          try { window._fishDrawForInactive(p.index, p.name); } catch (e) {}
        });
        seat.appendChild(db);
      }
      seat.addEventListener("click", () => {
        if (isMe) {
          // Own seat: open avatar gallery on other players' turns; block on yours.
          if (canInteract) {
            showToast("You can't change your icon on your turn.", "warn");
          } else if (typeof window.__fishOpenAvatarGallery === "function") {
            window.__fishOpenAvatarGallery();
          }
        } else {
          try { openBoardFocus(p); } catch (e) {}
        }
      });
      try { attachBoardHover(seat, p); } catch (e) {}
      seat.title = isMe
        ? (canInteract ? "Can't change avatar on your turn" : "Click to change your avatar")
        : `Hover for ${p.name || `Player ${slot + 1}`}'s board, click to enlarge`;

      cluster.appendChild(seat);
    }
    // Prestige badges + name colours on the seat cluster. The sweep is
    // debounced and skips nodes it already painted, so calling it on every
    // seat re-render costs nothing.
    try { window.__ccRefreshNames?.(); } catch (_) {}
  }

  // ── Vote Kick / Skip Turn, in the action bar ──────────────────
  // Both of these used to be chat commands, or nothing at all: to pass a quiet
  // player's turn you typed "P3 is AFK" (and had to know that), and to get rid
  // of somebody who was ruining the game there was no way at all short of
  // everyone leaving. They are buttons now, sat next to Surf's Up, which is
  // the same kind of thing pointed the other way: that one says "I have
  // stepped away", these two are about somebody else.
  //
  // The two rules are deliberately different, and the buttons say which is
  // which:
  //   Skip Turn  costs one turn and needs HALF the other players.
  //   Vote Kick  is permanent and needs EVERY other player.
  //
  // Skip Turn needs no target picker: there is only ever one player whose turn
  // it is. Vote Kick opens one, because any of the others could be the target.
  let _kickPickerOpen = false;
  let _voteInFlight = false;

  function closeKickPicker() {
    const picker = document.getElementById("pv-kick-picker");
    if (picker) picker.classList.remove("open");
    const btn = document.getElementById("pv-kick-btn");
    if (btn) btn.setAttribute("aria-expanded", "false");
    _kickPickerOpen = false;
  }
  // Any click outside, or Escape, puts it away.
  document.addEventListener("click", (e) => {
    if (!_kickPickerOpen) return;
    const wrap = document.getElementById("pv-kick-wrap");
    if (wrap && wrap.contains(e.target)) return;
    closeKickPicker();
  }, true);
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && _kickPickerOpen) closeKickPicker();
  });

  function _kickInfoFor(seatIndex) {
    return (_latestVotes.kick || []).find(k => k && k.seat === seatIndex) || null;
  }
  function _skipInfoFor(seatIndex) {
    const sk = _latestVotes.skip;
    return (sk && sk.seat === seatIndex) ? sk : null;
  }

  async function _sendVote(path, body, okMsg) {
    if (!roomId || _voteInFlight) return;
    const token = getSeatToken();
    if (!token) { try { showToast("No seat token, re-join the game first.", "err"); } catch {} return; }
    _voteInFlight = true;
    try {
      const r = await apiPost(`/api/rooms/${roomId}/${path}`,
        Object.assign({ seat_token: token }, body), { timeoutMs: 8000 });
      const d = r && r.data;
      if (!d || !d.ok) {
        try { showToast((d && d.error) || "That vote didn't go through.", "warn"); } catch {}
      } else if (okMsg) {
        try { showToast(okMsg(d), d.kicked ? "ok" : "info"); } catch {}
      }
      refreshState();
    } catch (e) {
      try { showToast("Could not reach the server, check your connection.", "err"); } catch {}
    } finally {
      _voteInFlight = false;
      closeKickPicker();
    }
  }

  // One row of the kick picker: a player, their tally, and what pressing it does.
  function _kickRow(info) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "pv-vote-row pv-vote-kick" + (info.mine ? " voted" : "");
    btn.setAttribute("role", "menuitem");
    const top = document.createElement("span");
    top.className = "pv-vote-row-label";
    top.textContent = (info.name || `Player ${info.seat + 1}`) + (info.mine ? " ✓" : "");
    const sub = document.createElement("span");
    sub.className = "pv-vote-row-hint";
    if (info.blocked) {
      btn.disabled = true;
      sub.textContent = "the host runs the lobby";
    } else {
      sub.textContent = info.mine
        ? `${info.votes}/${info.needed} · tap to take your vote back`
        : `${info.votes}/${info.needed} · everyone must agree`;
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        _sendVote("kick_player",
          { target_seat_index: info.seat, undo: Boolean(info.mine) },
          (d) => d.kicked
            ? `${d.name} was removed from the game.`
            : `Kick vote: ${d.votes}/${d.needed}.`);
      });
    }
    btn.appendChild(top);
    btn.appendChild(sub);
    return btn;
  }

  function openKickPicker() {
    const picker = document.getElementById("pv-kick-picker");
    if (!picker) return;
    picker.innerHTML = "";
    const head = document.createElement("div");
    head.className = "pv-vote-head";
    head.textContent = "Remove a player";
    picker.appendChild(head);
    (_latestVotes.kick || []).forEach(info => picker.appendChild(_kickRow(info)));
    const foot = document.createElement("div");
    foot.className = "pv-vote-foot";
    foot.textContent = "Everyone else has to agree. This is permanent.";
    picker.appendChild(foot);
    picker.classList.add("open");
    const btn = document.getElementById("pv-kick-btn");
    if (btn) btn.setAttribute("aria-expanded", "true");
    _kickPickerOpen = true;
    _clampToWindow(picker, document.getElementById("pv-kick-wrap"));
  }

  // The picker hangs off a button that can sit anywhere along a full-width
  // action bar, so anchoring it to one corner puts it off the side of the
  // window at some window sizes. Slide it back inside, measuring rather than
  // guessing, because how far it hangs over depends on the window.
  function _clampToWindow(menu, anchorEl) {
    try {
      const pad = 6;
      menu.style.left = "";
      menu.style.right = "";
      const anchor = anchorEl.getBoundingClientRect();
      const box = menu.getBoundingClientRect();
      const room = window.innerWidth;
      // Where it should sit in the window: its current place, pulled inside
      // whichever edge it is over. A menu wider than the window itself just
      // starts at the left edge rather than being pushed off the right.
      const maxLeft = Math.max(pad, room - box.width - pad);
      const wantLeft = Math.min(Math.max(pad, box.left), maxLeft);
      if (Math.abs(wantLeft - box.left) < 1) return;
      menu.style.right = "auto";
      menu.style.left = Math.round(wantLeft - anchor.left) + "px";
    } catch (_) {}
  }

  // Repaint both buttons from the tallies the last payload carried. A button
  // with nothing behind it is hidden outright rather than disabled: in a game
  // against bots there is nobody to vote with, and a permanently dead control
  // in the action bar is just clutter.
  function updateVoteButtons() {
    const skipBtn = document.getElementById("pv-skip-turn-btn");
    const kickWrap = document.getElementById("pv-kick-wrap");
    const kickBtn = document.getElementById("pv-kick-btn");
    if (!skipBtn || !kickWrap || !kickBtn) return;

    const skip = _latestVotes.skip;
    if (!skip) {
      skipBtn.style.display = "none";
    } else {
      skipBtn.style.display = "";
      const who = skip.name || `Player ${skip.seat + 1}`;
      skipBtn.disabled = Boolean(skip.blocked || skip.mine || _voteInFlight);
      skipBtn.classList.toggle("voted", Boolean(skip.mine));
      skipBtn.textContent = skip.mine
        ? `⏭ Skipping ${who} ${skip.votes}/${skip.needed}`
        : `⏭ Skip ${who}'s Turn${skip.votes ? ` ${skip.votes}/${skip.needed}` : ""}`;
      skipBtn.title = skip.blocked
        ? `${who} can't be skipped right now.`
        : skip.mine
          ? `You voted to skip ${who}'s turn (${skip.votes} of ${skip.needed} needed).`
          : `Vote to make ${who} draw 2 and pass. Needs half the other players `
            + `(${skip.votes} of ${skip.needed} so far).`;
    }

    const kicks = _latestVotes.kick || [];
    if (!kicks.length) {
      kickWrap.style.display = "none";
      if (_kickPickerOpen) closeKickPicker();
    } else {
      kickWrap.style.display = "";
      const cast = kicks.reduce((n, k) => n + (k.votes || 0), 0);
      const mine = kicks.some(k => k.mine);
      kickBtn.disabled = Boolean(_voteInFlight);
      kickBtn.classList.toggle("has-votes", cast > 0);
      kickBtn.textContent = cast > 0 ? `🚫 Vote Kick (${cast})` : "🚫 Vote Kick";
      kickBtn.title = mine
        ? "You have a kick vote running. Removing a player takes everyone else."
        : "Vote to remove a player for good. Every other player has to agree.";
      // Keep an open picker in step with the tallies that just landed.
      if (_kickPickerOpen) openKickPicker();
    }
  }

  document.getElementById("pv-skip-turn-btn")?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    const skip = _latestVotes.skip;
    if (!skip || skip.blocked || skip.mine) return;
    _sendVote("skip_turn", { target_seat_index: skip.seat },
      (d) => d.challenge_started
        ? `${d.name} has 20 seconds to answer.`
        : `Voted to skip ${d.name}'s turn (${d.votes}/${d.needed}).`);
  });

  document.getElementById("pv-kick-btn")?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    if (_kickPickerOpen) { closeKickPicker(); return; }
    openKickPicker();
  });

  // ── Opponent renderer ──────────────────────────────────────────
  function renderOpponents(opponents, turnIndex) {
    const el = document.getElementById("pv-opponents");
    if (!opponents.length) { cl(el); el.className = ""; return; }

    const _oppKey = JSON.stringify(opponents.map(p=>({
      i:p.index, n:p.name, s:p.score,
      bo:p.board_oceans, bh:p.board_hand, hand_count:p.hand_count,
      av:p.avatar_url
    }))) + "|" + turnIndex + "|" + pvFullBoards;
    if (_oppKey === _opponentsRenderKey && el.children.length > 0) return;
    _opponentsRenderKey = _oppKey;
    cl(el);
    el.className = "";

    const n = opponents.length;

    // ── Full boards mode (≤3 opponents = ≤4 players total) ──────
    if (pvFullBoards && n <= 3) {
      el.classList.add(`opp-${n}`, "full-mode");
      // Scale factor to keep boards readable at various player counts
      const zoom = n === 1 ? 0.58 : n === 2 ? 0.46 : 0.34;
      // opp at index 1 is "across" for 2-3 opponents; index 0 is across for 1 opponent
      const acrossIdx = n === 1 ? 0 : 1;
      const posClasses = n === 1 ? [""] : n === 2 ? ["opp-pos-left","opp-pos-across"] : ["opp-pos-left","opp-pos-across","opp-pos-right"];
      opponents.forEach((p, idx) => {
        const outer = document.createElement("div");
        outer.className = posClasses[idx] || "";
        const wrap = document.createElement("div");
        wrap.className = "pv-opp-full-wrap" + (p.index === turnIndex ? " active-turn" : "");
        wrap.title = `Hover for a peek at ${p.name || `Player ${p.index}`}'s board, click to enlarge`;
        wrap.addEventListener("click", () => openBoardFocus(p));
        try { attachBoardHover(wrap, p); } catch (e) {}
        // Label stays readable regardless of rotation
        const hc = p.hand_count ?? (Array.isArray(p.hand) ? p.hand.length : 0);
        const lbl = document.createElement("div"); lbl.className = "pv-opp-full-label";
        lbl.innerHTML = `${p.index===turnIndex?"▶ ":""}${p.name||`Player ${p.index}`}<span class="opp-score">${p.score??0} pts</span><span style="font-size:10px;color:var(--muted);margin-left:6px;">🃏${hc}</span>`;
        wrap.appendChild(lbl);
        // Board content, scale + rotate across opponent
        const boardEl = renderReadOnlyBoard(p);
        boardEl.style.zoom = String(zoom);
        if (idx === acrossIdx) boardEl.style.transform = "rotate(180deg)";
        wrap.appendChild(boardEl);
        outer.appendChild(wrap);
        el.appendChild(outer);
      });
      return;
    }

    // 4+ opponents: mini card layout
    if (n >= 4) {
      el.classList.add("opp-many");
      opponents.forEach(p => {
        const mini = document.createElement("div");
        mini.className = "pv-opp-mini" + (p.index === turnIndex ? " active-turn" : "");
        const hdr = document.createElement("div"); hdr.className = "pv-opp-header";
        const nm = document.createElement("div"); nm.className = "pv-opp-name";
        nm.textContent = (p.index === turnIndex ? "▶ " : "") + (p.name || `Player ${p.index}`);
        const sc = document.createElement("div"); sc.className = "pv-opp-score";
        const hcMini = p.hand_count ?? (Array.isArray(p.hand) ? p.hand.length : 0);
        sc.textContent = `${p.score ?? 0} pts · 🃏${hcMini}`;
        hdr.appendChild(nm); hdr.appendChild(sc); mini.appendChild(hdr);
        const thumbs = document.createElement("div"); thumbs.style.cssText = "display:flex;flex-wrap:wrap;gap:2px;margin-top:4px;";
        (Array.isArray(p.board) ? p.board : []).slice(0, 5).forEach(ocean => {
          const img = document.createElement("img");
          img.src = imagePathForUid(ocean.ocean?.uid ?? ocean.ocean_uid);
          img.style.cssText = "width:30px;border-radius:3px;";
          img.loading = "lazy"; thumbs.appendChild(img);
        });
        mini.appendChild(thumbs);
        mini.addEventListener("click", () => openBoardFocus(p));
        try { attachBoardHover(mini, p); } catch (e) {}
        el.appendChild(mini);
      });
      return;
    }

    el.classList.add(`opp-${Math.min(n, 3)}`);

    // Position classes: first opp → across (top in 3-player), remaining → left then right
    const posClasses = n === 1 ? [""] : n === 2 ? ["opp-pos-left", "opp-pos-across"] : ["opp-pos-left", "opp-pos-across", "opp-pos-right"];
    const posLabels  = n === 1 ? [""] : n === 2 ? ["Left", "Across"] : ["Left", "Across", "Right"];

    opponents.forEach((p, idx) => {
      const posClass = posClasses[idx] || "";
      const posLabel = posLabels[idx] || "";

      const wrap = document.createElement("div");
      wrap.className = posClass;

      if (posLabel) {
        const lbl = document.createElement("div"); lbl.className = "opp-pos-label";
        lbl.textContent = posLabel; wrap.appendChild(lbl);
      }

      const card = document.createElement("div");
      card.className = "pv-opp-card" + (p.index === turnIndex ? " active-turn" : "");

      // header
      const hdr = document.createElement("div"); hdr.className = "pv-opp-header";
      const nm  = document.createElement("div"); nm.className = "pv-opp-name";
      nm.textContent = (p.index===turnIndex?"▶ ":"") + (p.name||`Player ${p.index}`);
      const sc  = document.createElement("div"); sc.className = "pv-opp-score";
      const hcCard = p.hand_count ?? (Array.isArray(p.hand) ? p.hand.length : 0);
      sc.textContent = `${p.score??0} pts · 🃏${hcCard}`;
      hdr.appendChild(nm); hdr.appendChild(sc); card.appendChild(hdr);

      // face-down hand cards strip, use hand_count for opponents (server sends hand:[])
      const handSize = (Array.isArray(p.hand) && p.hand.length > 0)
        ? p.hand.length
        : (p.hand_count ?? p.hand_size ?? 0);
      if (handSize > 0) {
        const handStrip = document.createElement("div");
        handStrip.className = "pv-opp-hand";
        const show = Math.min(handSize, 12);
        for (let i = 0; i < show; i++) {
          const fc = document.createElement("div");
          fc.className = "pv-fd-card";
          fc.style.left = `${i * 14}px`;
          fc.style.zIndex = i;
          handStrip.appendChild(fc);
        }
        handStrip.style.width = `${Math.min(show, 12) * 14 + 21}px`;
        if (handSize > 12) {
          const extra = document.createElement("span");
          extra.style.cssText = "position:absolute;left:"+((show*14)+4)+"px;font-size:10px;color:var(--muted);top:8px;";
          extra.textContent = `+${handSize-12}`;
          handStrip.appendChild(extra);
        }
        card.appendChild(handStrip);
      }

      // stats
      const stats = document.createElement("div"); stats.className = "pv-opp-stats";
      stats.innerHTML = `<span>Hand: ${handSize}</span><span>Oceans: ${Array.isArray(p.board)?p.board.length:0}</span>`;
      card.appendChild(stats);

      // mini ocean thumbnails
      const miniBoard = document.createElement("div"); miniBoard.className = "pv-opp-mini-board";
      (Array.isArray(p.board)?p.board:[]).slice(0,5).forEach(ocean => {
        const hub = document.createElement("div"); hub.className = "pv-mini-ocean";
        const img = document.createElement("img");
        img.src = imagePathForUid(ocean.ocean?.uid ?? ocean.ocean_uid);
        img.alt = ocean.ocean?.name || ""; img.loading="lazy"; hub.appendChild(img);
        const attached = (ocean.up?.length||0)+(ocean.down?.length||0)+(ocean.left?.length||0)+(ocean.right?.length||0);
        if (attached > 0) {
          const cnt = document.createElement("span"); cnt.className = "pv-mini-count";
          cnt.textContent = "+"+attached; hub.appendChild(cnt);
        }
        miniBoard.appendChild(hub);
      });
      const board = Array.isArray(p.board) ? p.board : [];
      if (board.length > 5) {
        const more = document.createElement("span"); more.className = "pv-tag";
        more.textContent = `+${board.length-5}`; miniBoard.appendChild(more);
      }
      card.appendChild(miniBoard);
      card.title = `Hover for a quick peek at ${p.name || `Player ${p.index}`}'s board, click to enlarge`;
      card.addEventListener("click", () => openBoardFocus(p));
      try { attachBoardHover(card, p); } catch (e) {}
      wrap.appendChild(card);
      el.appendChild(wrap);
    });
  }

  // ── Score breakdown modal ──────────────────────────────────────
  function openScoreBreakdown() {
    const payload = latestPayload;
    const content = document.getElementById("pv-score-content");
    while (content.firstChild) content.removeChild(content.firstChild);

    const players = Array.isArray(payload?.state?.players) ? payload.state.players : [];
    if (!players.length) {
      const msg = document.createElement("p");
      msg.style.cssText = "color:var(--muted);font-size:13px;";
      msg.textContent = "No score data yet, scores appear once cards are played.";
      content.appendChild(msg); return;
    }

    // Player count header
    const countMap = {2:"Two",3:"Three",4:"Four",5:"Five",6:"Six",7:"Seven",8:"Eight",9:"Nine",10:"Ten"};
    const countLabel = countMap[players.length] || String(players.length);
    const countEl = document.createElement("div");
    countEl.style.cssText = [
      "font-family:'Cinzel',serif",
      "font-size:1rem",
      "font-weight:900",
      "color:var(--cyan)",
      "text-align:center",
      "margin-bottom:14px",
      "letter-spacing:.1em",
      "text-transform:uppercase",
      "padding:8px 0",
      "border-bottom:1px solid rgba(48,200,240,.2)",
    ].join(";");
    countEl.textContent = `⚓ ${countLabel}-Player Game`;
    content.appendChild(countEl);

    const sorted = [...players].sort((a, b) => Number(b.score||0) - Number(a.score||0));

    // Leaderboard pills
    const lbRow = document.createElement("div"); lbRow.className = "sb-leaderboard";
    sorted.forEach((p, i) => {
      const rankClass = i===0?"sb-rank-1":i===1?"sb-rank-2":i===2?"sb-rank-3":"sb-rank-n";
      const isMe = Number(p.index) === _myIdxGlobal;
      const pill = document.createElement("div"); pill.className = "sb-rank-pill";
      const badge = document.createElement("div"); badge.className = `sb-rank-badge ${rankClass}`;
      badge.textContent = i+1;
      pill.appendChild(badge);
      pill.appendChild(document.createTextNode(`${p.name}${isMe?" (you)":""}, ${Number(p.score||0)} pts`));
      if (isMe) {
        const you = document.createElement("span"); you.className = "sb-you"; you.textContent = "YOU";
        pill.appendChild(you);
      }
      lbRow.appendChild(pill);
    });
    content.appendChild(lbRow);

    sorted.forEach((p, rank) => {
      const isMe = Number(p.index) === _myIdxGlobal;
      const rankClass = rank===0?"sb-rank-1":rank===1?"sb-rank-2":rank===2?"sb-rank-3":"sb-rank-n";
      const block = document.createElement("div"); block.className = "sb-player-block";

      const head = document.createElement("div"); head.className = "sb-player-head";
      const badge = document.createElement("div"); badge.className = `sb-rank-badge ${rankClass}`;
      badge.textContent = rank+1; head.appendChild(badge);
      const nameEl = document.createElement("span"); nameEl.textContent = p.name;
      if (isMe) nameEl.style.color = "var(--cyan)"; head.appendChild(nameEl);
      if (isMe) {
        const you = document.createElement("span"); you.className = "sb-you"; you.textContent = "YOU";
        head.appendChild(you);
      }
      const total = document.createElement("span"); total.className = "sb-total-pill";
      total.textContent = `${Number(p.score||0)} pts`; head.appendChild(total);
      block.appendChild(head);

      const full = p?.score_breakdown?.full;
      const rows = full && Array.isArray(full.card_rows) ? full.card_rows : [];
      if (!rows.length) {
        const none = document.createElement("div"); none.style.cssText = "font-size:11px;color:var(--muted);";
        none.textContent = "No scored cards yet."; block.appendChild(none);
      } else {
        rows.forEach(row => {
          const rowEl = document.createElement("div"); rowEl.className = "sb-card-row";
          const nameRow = document.createElement("div");
          const rowTotal = Number(row.total||0);
          const sign = rowTotal >= 0 ? "+" : "";
          nameRow.innerHTML = `<span class="sb-card-name">${row.card_uid}:${row.card_name}</span>
            <span style="color:var(--muted);font-size:10px;"> (${row.is_ocean?"Ocean":"Animal"} · Ocean #${row.ocean_uid})</span>
            <span class="sb-card-pts" style="float:right;">${sign}${rowTotal} pts</span>`;
          rowEl.appendChild(nameRow);
          const comps = Array.isArray(row.components) ? row.components : [];
          if (comps.length) {
            const compDiv = document.createElement("div"); compDiv.className = "sb-card-components";
            compDiv.textContent = comps.map(c => {
              const pts = Number(c.points||0);
              return `${pts>=0?"+":""}${pts} ${String(c.reason||"").trim()}`;
            }).join("  ·  ");
            rowEl.appendChild(compDiv);
          }
          block.appendChild(rowEl);
        });
      }
      content.appendChild(block);
    });

    document.getElementById("pv-score-modal").classList.add("open");
  }

  document.getElementById("pv-my-score-badge").addEventListener("click", openScoreBreakdown);
  document.getElementById("pv-score-close").addEventListener("click", () => {
    document.getElementById("pv-score-modal").classList.remove("open");
  });
  document.getElementById("pv-score-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("pv-score-modal"))
      document.getElementById("pv-score-modal").classList.remove("open");
  });
  // pv-scores-btn was removed from HTML; replaced by pv-menu-scores-btn in dropdown

