        nextStats.lifetime_free_baitfish = Number(nextStats.lifetime_free_baitfish || 0) + Number(_gameAchTracker?.freeBaitfishUses || 0);
        nextStats.lifetime_sea_urchin_draws = Number(nextStats.lifetime_sea_urchin_draws || 0) + Number(_gameAchTracker?.seaUrchinDraws || 0);
        nextStats.lifetime_sea_star_draws = Number(nextStats.lifetime_sea_star_draws || 0) + Number(_gameAchTracker?.seaStarDraws || 0);
        nextStats.lifetime_sea_cucumber_draws = Number(nextStats.lifetime_sea_cucumber_draws || 0) + Number(_gameAchTracker?.seaCucumberDraws || 0);
        nextStats.lifetime_sea_anemone_draws = Number(nextStats.lifetime_sea_anemone_draws || 0) + Number(_gameAchTracker?.seaAnemoneDraws || 0);
        nextStats.lifetime_sea_anemone_plays = Number(nextStats.lifetime_sea_anemone_plays || 0) + Number(_gameAchTracker?.seaAnemonePlayedThisGame || 0);
        nextStats.lifetime_sea_cucumber_played = Number(nextStats.lifetime_sea_cucumber_played || 0) + Number(_gameAchTracker?.seaCucumberPlayedThisGame || 0);
        nextStats.lifetime_baitfish_played = Number(nextStats.lifetime_baitfish_played || 0) + Number(_gameAchTracker?.baitfishPlayedThisGame || 0);

