  // ── Exclusive Backgrounds (donation / code-unlocked) ───────────
  // Cosmetic backgrounds that render behind your avatar everywhere it appears.
  // One per in-game ocean. 1,000 Critter Coins each, unlocked by entering a donation code.
  const EXCLUSIVE_BACKGROUNDS = [
    { id:"bg-kelp",           name:"Kelp Forest",      img:"/backgrounds/bg-kelp.png",            facts:"Golden kelp swaying in sunlit green water." },
    { id:"bg-coral-reef",     name:"Coral Reef",       img:"/backgrounds/bg-coral-reef.png",      facts:"A vivid coral garden bursting with color." },
    { id:"bg-artificial-reef",name:"Artificial Reef",  img:"/backgrounds/bg-artificial-reef.png", facts:"A sunken structure reclaimed by the sea." },
    { id:"bg-tide-pool",      name:"Tide Pool",        img:"/backgrounds/bg-tide-pool.png",       facts:"A shimmering rocky pool left by the tide." },
    { id:"bg-arctic",         name:"Arctic Ocean",     img:"/backgrounds/bg-arctic.png",          facts:"Icy blue water beneath drifting floes." },
    { id:"bg-deep",           name:"Deep Ocean",       img:"/backgrounds/bg-deep.png",            facts:"The dark, mysterious open deep." },
    { id:"bg-pier",           name:"Pier",             img:"/backgrounds/bg-pier.png",            facts:"Pilings and dappled light under the dock." },
    { id:"bg-mangrove",       name:"Mangrove",         img:"/backgrounds/bg-mangrove.png",        facts:"Tangled roots mirrored in warm, shallow water." },
  ];
  const _BG_BY_ID  = Object.fromEntries(EXCLUSIVE_BACKGROUNDS.map(b => [b.id, b]));
  const _BG_BY_IMG = Object.fromEntries(EXCLUSIVE_BACKGROUNDS.map(b => [b.img, b]));
  // Synthetic "remove background" tile, always unlocked, always sorts first,
  // so clearing an equipped background is a normal tile click (like picking
  // any other background) instead of a hidden button on the equipped tile.
  const _BG_NONE = { id:"__none__", name:"No Background", img:"", facts:"Just your avatar, no scene behind it." };

  // ── Exclusive Skins (Store) ────────────────────────────────────
  // Derived from the avatar registry above (unlock.type === "shop"). These are
  // ordinary avatars gated behind a Critter-Coins purchase, so every downstream
  // avatar path (in-game seat display, gallery, chat, leaderboard) just works.
  const PHST_SKIN_COIN_PRICE = 2000; // 2,000 Critter Coins per skin
  const EXCLUSIVE_SKINS   = ANIMAL_AVATARS.filter(a => a.unlock && a.unlock.type === "shop");
  const _SKIN_IMG_SET     = new Set(EXCLUSIVE_SKINS.map(s => s.img));

  // ── Player Perks (Store) ───────────────────────────────────────
  // Critter-Coin consumables. Declared out here, beside the skin price, because
  // BOTH halves of the app need them: the Store renders the price tags and the
  // gallery/profile layer runs the spend transactions (see __fishBuyStreakShield
  // and friends). One declaration = the tag on the card can never disagree with
  // the amount actually charged.
  const PHST_SHIELD_COIN_PRICE  = 500;   // covers one missed day of a daily streak
  const PHST_EMOTE_PACK_PRICE   = 500;   // one pack of critter chat emotes
  const PHST_EMOTE_PACK_SIZE    = 5;     // critters granted per Emote Pack
  const PHST_REEARN_COIN_PRICE  = 2500;  // buy back one traded-away critter
  const PHST_PERK_STACK_MAX     = 3;     // hoard cap per stackable consumable

  // ── Username changes ───────────────────────────────────────────
  // ONE free rename per account, then this much per change, with no waiting
  // period either way (build 1.6.48 replaced the old 24-hour cooldown and its
  // Name Change Token). Declared here so the first-sign-in promise, the
  // Settings note and the amount actually charged are the same number.
  const PHST_RENAME_COIN_PRICE  = 100;   // per username change after the free one
  function backgroundById(id){ return _BG_BY_ID[id] || null; }
  function normalizeBgUrl(u){
    let s = String(u||"").trim();
    if (!s) return "";
    const i = s.indexOf("/backgrounds/");
    if (i >= 0) s = s.slice(i);
    s = s.split("?")[0];
    return s.startsWith("/backgrounds/") ? s : "";
  }
  // Competitive rank tier ordering (Unranked < Bronze < Silver < Gold < Diamond < Emerald < King).
  function rankTierValue(rankName){
    const n = String(rankName||"").trim().toLowerCase();
    if (!n || n === "unranked") return 0;
    if (n.startsWith("bronze"))  return 1;
    if (n.startsWith("silver"))  return 2;
    if (n.startsWith("gold"))    return 3; // "Golden Grouper …"
    if (n.startsWith("diamond")) return 4;
    if (n.startsWith("emerald")) return 5;
    if (n.startsWith("king"))    return 6;
    return 0;
  }
  const _RANK_TIER_VALUE = { bronze:1, silver:2, gold:3, golden:3, diamond:4, emerald:5, king:6 };
  // Lowercased names of every Game Fish species (for the Sailfish board check).
  const GAME_FISH_NAMES = ANIMAL_AVATARS.filter(a => a.species === "Game Fish").map(a => a.name.toLowerCase());
  const DEFAULT_AVATAR_IMG = "/avatars/mullet.png";
  const _animalByImg = {}, _animalById = {};
  ANIMAL_AVATARS.forEach(a => { _animalByImg[a.img] = a; _animalById[a.id] = a; });
  function animalByImg(img){ return _animalByImg[String(img||"").trim().toLowerCase()] || null; }
  function animalById(id){ return _animalById[id] || null; }
  function animalFacts(a){ return (a && a.facts) ? a.facts : "Fun facts coming soon."; }
  // Numeric unlock progress (0..1) for stat-based animals; null for event/achievement.
  function animalUnlockProgress(a, stats, level){
    const u = a && a.unlock; if (!u) return null;
    if (u.type === "starter")   return 1;
    if (u.type === "level")     return Math.min(1, Number(level||0) / (u.goal||1));
    if (u.type === "comp_wins") return Math.min(1, Number(stats?.lifetime_comp_wins||0) / (u.goal||1));
    if (u.type === "stat")      return Math.min(1, Number(stats?.[u.stat]||0) / (u.goal||1));
    if (u.type === "rank")      return Math.min(1, rankTierValue(stats?.rank_competitive) / (_RANK_TIER_VALUE[u.tier]||1));
    if (u.type === "achievement" && u.achId && u.goal) {
      const achs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const rec = achs[u.achId] || {};
      if (rec.completed) return 1;
      const cur = Number(rec.progress || 0);
      return Math.min(1, cur / u.goal);
    }
    // Events and secrets: return null (no numeric progress bar, shown as "Complete the challenge")
    return null;
  }
  function animalProgressText(a, stats, level){
    const u = a && a.unlock; if (!u) return "";
    if (u.type === "level")     return `Level ${Number(level||0)} / ${u.goal}`;
    if (u.type === "comp_wins") return `${Number(stats?.lifetime_comp_wins||0)} / ${u.goal} Competitive wins`;
    if (u.type === "stat")      return `${Number(stats?.[u.stat]||0)} / ${u.goal}${u.unit ? " " + u.unit : ""}`;
    if (u.type === "rank")      return `Current rank: ${stats?.rank_competitive || "Unranked"}`;
    if (u.type === "achievement" && u.achId && u.goal) {
      const achs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const rec = achs[u.achId] || {};
      if (rec.completed) return "✓ Achievement completed!";
      const cur = Number(rec.progress || 0);
      const goal = u.goal;
      if (goal === 1) return cur > 0 ? "In progress, finish the challenge to unlock" : "Not yet achieved";
      return `${cur} / ${goal} qualifying wins`;
    }
    return "";
  }

  // ── Re-earning an avatar you traded away ─────────────────────────────
  // Trading an item away does NOT undo the progress that unlocked it, so the
  // retroactive unlock sweep used to hand it straight back for free (trade the
  // Horned Puffin, and your 75 banked Play Agains re-unlocked it on the next
  // stats load). When an item leaves an account the server snapshots that
  // account's progress (users/{uid}.traded_away, see _trade_away_after in
  // multiplayer_server.py); everything measured against BANKED progress must be
  // earned AGAIN from that snapshot before an automatic grant returns it.
  // Requirements that are repeatable by nature: one-game feats, hidden clicks,
  // donation codes, Store purchases: are re-done by definition and pass
  // straight through (reaching the grant means the player just did it again).
  const REEARN_GATED_TYPES = new Set(["stat", "comp_wins", "level", "rank", "achievement"]);

  // The most recent trade-away snapshot for `img`, or null if it was never
  // traded away by this account.
  function tradedAwayEntry(profile, img) {
    const want = String(img || "").split("?")[0].toLowerCase();
    const arr = (profile && Array.isArray(profile.traded_away)) ? profile.traded_away : null;
    if (!want || !arr) return null;
    for (let i = arr.length - 1; i >= 0; i--) {
      const e = arr[i];
      if (e && typeof e === "object"
          && String(e.item || "").split("?")[0].toLowerCase() === want) return e;
    }
    return null;
  }

  // What it now takes to get `a` back: { met, prog (0..1 or null), text,
  // repeatable }. `base` is the trade-away snapshot; stats/level are CURRENT.
  function reEarnState(a, base, stats, level) {
    const u = (a && a.unlock) || {};
    const bStats = (base && typeof base.stats === "object" && base.stats) || {};
    const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
    const fmt = n => Math.round(n).toLocaleString();
    const counted = (cur, need, unit) => ({
      met: cur >= need,
      prog: need > 0 ? Math.max(0, Math.min(1, cur / need)) : 1,
      text: `${fmt(Math.min(cur, need))} / ${fmt(need)}${unit ? " " + unit : ""}`,
      repeatable: true,
    });
    if (u.type === "stat") {
      return counted(num(stats?.[u.stat]), num(bStats[u.stat]) + num(u.goal), u.unit || "");
    }
    if (u.type === "comp_wins") {
      return counted(num(stats?.lifetime_comp_wins),
                     num(bStats.lifetime_comp_wins) + num(u.goal), "Competitive wins");
    }
    if (u.type === "level") {
      // "Reach Level N" can't literally happen twice, so the second time is
      // worth what that milestone cost from scratch: earn that XP all over
      // again. Never dead-ends, unlike demanding N more levels past the cap.
      const goalLvl = Math.max(1, Math.min(LEVEL_XP_TOTALS.length, num(u.goal)));
      const cost = LEVEL_XP_TOTALS[goalLvl - 1] || 0;
      const baseXp = num(base && base.total_xp) || num(bStats.total_xp);
      return counted(getStoredTotalXp(stats), baseXp + cost, "XP");
    }
    if (u.type === "rank") {
      // A rank is a standing position, so "again" means CLIMB TO IT again: fall
      // below the tier (a loss streak, or the season reset that puts everyone
      // back to Unranked) and get back up. `dipped` is set the moment we see the
      // player below the tier after the trade: see _noteReEarnRankDip.
      const curName = stats?.rank_competitive || "Unranked";
      const cur  = rankTierValue(curName);
      const need = _RANK_TIER_VALUE[u.tier] || Infinity;
      const below = !!(base && base.dipped) || rankTierValue(base && base.rank) < need;
      return { met: below && cur >= need, prog: null, repeatable: true,
               text: below
                 ? `Climb back to ${u.tier}: you're ${curName}.`
                 : `Drop below ${u.tier} and earn it again (you're ${curName}; the season reset counts).` };
    }
    if (u.type === "achievement") {
      // The badge is one-shot, but achievements.{id}.progress is a lifetime
      // meter that keeps counting every qualifying performance, so doing the
      // achievement's work a second time is measurable.
      const achs = (typeof window.__fishGetUserAchievements === "function")
        ? (window.__fishGetUserAchievements() || {}) : {};
      const cur  = num((achs[u.achId] || {}).progress);
      const wasA = (base && typeof base.achievements === "object" && base.achievements) || {};
      const goal = Math.max(1, num(u.goal) || 1);
      const need = num(wasA[u.achId]) + goal;
      if (goal <= 1) {
        // A one-off feat (beat the Giant Squid, 5 Cephalopods in a turn…):
        // no meaningful bar, just do it once more.
        return { met: cur >= need, prog: null, repeatable: true,
                 text: "Do it once more to earn it back." };
      }
      return counted(cur, need, u.unit || "qualifying wins");
    }
    // Unknown/one-off type: nothing measurable to repeat, so don't auto-grant.
    return { met: false, prog: null, repeatable: false,
             text: "Trade for it to get it back." };
  }

  // ── Animal unlock screen queue (shown on return to the home menu) ──
  let _pendingAnimalUnlocks = [];
  let _animalUnlockShowing = false;
  let _animalUnlockAutoTimer = null;
  function _queueAnimalUnlock(id){
    if (id && animalById(id) && !_pendingAnimalUnlocks.includes(id)) _pendingAnimalUnlocks.push(id);
    // Flag this avatar as "New" for the Avatar Gallery until the player views it.
    if (id) {
      try {
        const k = "cc_new_avatars";
        const s = new Set(JSON.parse(localStorage.getItem(k) || "[]"));
        s.add(id);
        localStorage.setItem(k, JSON.stringify([...s]));
      } catch {}
      // Ring the notification bell so the player can click straight to the animal.
      const a = animalById(id);
      window.__fishNotifPushAnimal?.(id, a ? a.name : id);
    }
    // Show the unlock popup IMMEDIATELY (debounced so several grants earned in
    // the same moment queue up and then display one-by-one). This is what makes
    // an avatar appear the instant it's earned DURING a game, with the Equip
    // Now button, instead of only after the game ends. _showNextAnimalUnlock is
    // guarded by _animalUnlockShowing so this can never double-open.
    clearTimeout(_animalUnlockAutoTimer);
    _animalUnlockAutoTimer = setTimeout(() => { try { _showNextAnimalUnlock(); } catch {} }, 700);
  }
  function _showNextAnimalUnlock(){
    if (_animalUnlockShowing) return;
    const ov = document.getElementById("animal-unlock-overlay");
    if (!ov) return;
    const id = _pendingAnimalUnlocks.shift();
    if (!id) return;
    const a = animalById(id);
    if (!a) { _showNextAnimalUnlock(); return; }
    _animalUnlockShowing = true;
    ov._currentAnimal = a;
    const img = document.getElementById("au-animal-img");
    if (img) { img.src = a.img; img.alt = a.name; }
    const nm = document.getElementById("au-animal-name");   if (nm) nm.textContent = a.name;
    const sp = document.getElementById("au-animal-species"); if (sp) sp.textContent = a.species || "";
    const fc = document.getElementById("au-animal-facts");   if (fc) fc.textContent = animalFacts(a);
    const ht = document.getElementById("au-animal-howto");
    const htTxt = document.getElementById("au-animal-howto-text");
    if (ht) {
      const lbl = a.unlock && a.unlock.label;
      if (htTxt) htTxt.textContent = lbl || "";
      ht.style.display = lbl ? "" : "none";
    }
    ov.classList.add("open");
  }
  function _closeAnimalUnlock(){
    const ov = document.getElementById("animal-unlock-overlay");
    if (ov) { ov.classList.remove("open"); ov._currentAnimal = null; }
    _animalUnlockShowing = false;
    if (_pendingAnimalUnlocks.length) setTimeout(_showNextAnimalUnlock, 350);
  }
  (function wireAnimalUnlockButtons(){
    const yes = document.getElementById("au-btn-yes");
    const no  = document.getElementById("au-btn-no");
    if (yes) yes.addEventListener("click", async () => {
      const ov = document.getElementById("animal-unlock-overlay");
      const a = ov && ov._currentAnimal;
      if (a && typeof window.__fishEquipAvatar === "function") {
        try { await window.__fishEquipAvatar(a.img); } catch {}
      }
      _closeAnimalUnlock();
    });
    if (no) no.addEventListener("click", () => _closeAnimalUnlock());
  })();
  window.__fishQueueAnimalUnlock = _queueAnimalUnlock;
  window.__fishShowAnimalUnlocks = () => { if (_pendingAnimalUnlocks.length) _showNextAnimalUnlock(); };

