    function escapeHtml(value) {
      return String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
    }

    function safeInitial(name) {
      const t = String(name || "").trim();
      return t ? t.charAt(0).toUpperCase() : "?";
    }

    function resolveAvatarUrl(profile, opts) {
      const options = opts || {};
      const includeAuthFallback = !!options.includeAuthFallback;
      const seed = options.seed || profile?.uid || profile?.email || profile?.nickname || "";
      const fromProfile = profile && (
        profile.avatar_url ||
        profile.avatarUrl ||
        profile.photo_url ||
        profile.photoURL
      );
      const profileAvatar = normalizeAvatarUrl(fromProfile || "");
      // Display accepts any known animal image (self or other players); only
      // selection is gated by unlock status.
      if (animalByImg(profileAvatar)) return profileAvatar;
      if (includeAuthFallback && _authUser && _authUser.photoURL) {
        const authAvatar = normalizeAvatarUrl(_authUser.photoURL);
        if (animalByImg(authAvatar)) return authAvatar;
      }
      return getDefaultAvatar(seed);
    }

    function resolveFriendAvatarUrl(rawAvatar, seed) {
      const normalized = normalizeAvatarUrl(rawAvatar || "");
      if (!normalized || !animalByImg(normalized)) return getDefaultAvatar(seed);
      return normalized;
    }

    // Bridge for code outside this IIFE (e.g. in-game player seat row).
    //
    // THIS IS THE FACE EVERY OTHER PLAYER SEES. It feeds the seat rows, the
    // chat lines, and pushMySeatAvatar(), which is what relays the icon to
    // everyone else's screen. It used to answer "/avatars/mullet.png" for
    // anyone without an account, on the old rule that guests could not choose
    // a critter. Guests HAVE been able to choose one since the padlock wall
    // came down: the gallery opens for them, every earnable critter is
    // selectable, and applyAvatarSelection() saves the pick to this browser.
    // The one thing that never got the message was this function, so a guest
    // equipped a critter, watched Player Home change, sat down at a table and
    // was a Mullet again, to themselves and to everybody else.
    //
    // A guest's pick lives in _guestAvatarUrl (mirrored onto _activeProfile),
    // an account's on the profile, so the read order differs by session; both
    // ends still go through the same catalogue check, so a stale or deleted
    // path falls back to the default rather than being sent out as a 404.
    window.__fishMyAvatarUrl = function () {
      try {
        const guest = !_authUser && _guestSessionActive;
        if (!_authUser && !guest) return "/avatars/mullet.png";
        const seed = guest ? (_playerNickname || "guest") : (_authUser?.uid || _playerNickname || "guest");
        const fromProfile = _activeProfile && (
          _activeProfile.avatar_url ||
          _activeProfile.avatarUrl ||
          _activeProfile.photo_url ||
          _activeProfile.photoURL
        );
        const raw = guest ? (_guestAvatarUrl || fromProfile || "") : (fromProfile || _guestAvatarUrl || "");
        const normalized = normalizeAvatarUrl(raw);
        if (normalized && animalByImg(normalized)) return normalized;
        return getDefaultAvatar(seed);
      } catch (e) {
        return "/avatars/mullet.png";
      }
    };

    // Async lookup of another player's chosen avatar by nickname.
    // Entries carry a timestamp and expire after a short TTL so that when a
    // player changes their avatar mid-game, every other client re-fetches and
    // shows the new icon within ~12s (without a stale cache pinning the old
    // one forever). Exposed on window so renderPlayerSeats / chat can read it
    // synchronously (avoiding the "img replaced before lookup resolved" race).
    const _nickAvatarCache = {};   // nick -> { url: string|null, bg: string|null, ts: ms }
    const _NICK_AVATAR_TTL = 12000;
    window._nickAvatarCache = _nickAvatarCache;
    // Synchronous read: last-known avatar url for a nick (or undefined).
    window.__fishAvatarCached = function(nick) {
      const e = nick ? _nickAvatarCache[nick] : null;
      return e ? e.url : undefined;
    };
    // Synchronous read: last-known equipped background for a nick ("" if none/unknown).
    window.__fishBackgroundCached = function(nick) {
      const e = nick ? _nickAvatarCache[nick] : null;
      return e ? (e.bg || "") : "";
    };
    window.__fishAvatarForNick = async function(nick) {
      if (!nick) return null;
      const e = _nickAvatarCache[nick];
      if (e && (Date.now() - e.ts) < _NICK_AVATAR_TTL) return e.url;  // fresh, reuse
      try {
        if (!_db) { _nickAvatarCache[nick] = { url: null, bg: null, ts: Date.now() }; return null; }
        const snap = await _db.collection("users").where("nickname", "==", nick).limit(1).get();
        // Validate against the known avatar set, a stale/invalid stored value
        // (e.g. a deleted "/avatars/avatar-04.png") must NOT be used as an
        // <img> src or it 404s. Return null so callers fall back to the default.
        const data = snap.empty ? {} : (snap.docs[0].data() || {});
        const norm = normalizeAvatarUrl(data.avatar_url || "");
        const url = (norm && animalByImg(norm)) ? norm : null;
        const bgn = normalizeBgUrl(data.background_url || "");
        const bg  = (bgn && _BG_BY_IMG[bgn]) ? bgn : null;
        _nickAvatarCache[nick] = { url, bg, ts: Date.now() };
        return url;
      } catch(e2) {
        // On error keep any prior value but refresh the timestamp so we don't hammer.
        if (!_nickAvatarCache[nick]) _nickAvatarCache[nick] = { url: null, bg: null, ts: Date.now() };
        else _nickAvatarCache[nick].ts = Date.now();
        return _nickAvatarCache[nick].url;
      }
    };
    // Resolve another player's equipped background by nickname (cached alongside
    // their avatar). Returns "" if none. Triggers an avatar fetch if not cached.
    window.__fishBackgroundForNick = async function(nick) {
      if (!nick) return "";
      const e = _nickAvatarCache[nick];
      if (e && (Date.now() - e.ts) < _NICK_AVATAR_TTL) return e.bg || "";
      try { await window.__fishAvatarForNick(nick); } catch {}
      const e2 = _nickAvatarCache[nick];
      return e2 ? (e2.bg || "") : "";
    };

    function renderStatsAvatar(profile, nickname) {
      const wrap = $a("stats-avatar");
      const img = $a("stats-avatar-img");
      const letter = $a("stats-avatar-letter");
      if (letter) letter.textContent = safeInitial(nickname || _playerNickname || "Guest");
      if (!wrap || !img) return;
      const avatarSeed = _authUser?.uid || _playerNickname || nickname || "guest";
      // A guest wears their own pick here, the same one __fishMyAvatarUrl()
      // sends to the table. Only a session with no identity at all falls back
      // to the Mullet.
      const avatarUrl = _authUser
        ? resolveAvatarUrl(profile, { includeAuthFallback: true, seed: avatarSeed })
        : (_guestSessionActive
            ? (typeof window.__fishMyAvatarUrl === "function"
                ? window.__fishMyAvatarUrl()
                : sanitizeSelectableAvatar(_guestAvatarUrl, avatarSeed))
            : "/avatars/mullet.png");
      if (!avatarUrl) {
        wrap.classList.remove("has-image");
        img.removeAttribute("src");
        return;
      }
      img.onerror = () => {
        const fallback = DEFAULT_AVATAR_IMG;
        if (img.src && img.src.includes(fallback)) {
          wrap.classList.remove("has-image");
          img.removeAttribute("src");
          return;
        }
        img.src = fallback;
      };
      img.src = _avSrc(avatarUrl);
      wrap.classList.add("has-image");
      // Own equipped background behind the home/stats avatar.
      try { if (_authUser) _applyAvBg(wrap, _galEquippedBg()); else _applyAvBg(wrap, ""); } catch {}
    }

    // Re-apply my equipped background to all currently-visible own-avatar spots
    // (called right after equip/remove so the change shows without a reload).
    function _applyOwnBackgroundEverywhere() {
      const bg = (typeof _galEquippedBg === "function") ? _galEquippedBg() : "";
      try { const w = $a("stats-avatar"); if (w) _applyAvBg(w, bg); } catch {}
      try { const hi = $a("gal-hero-img"); if (hi && hi.parentElement) _applyAvBg(hi.parentElement, bg); } catch {}
      // In-game: my seat re-applies on the next state render via renderPlayerSeats.
    }

    function formatFriendCodeLabel(name, code) {
      if (!code) return "";
      return `Friend code: ${code}`;
    }

    function toDateFromFirestoreLike(value) {
      if (!value) return null;
      if (value instanceof Date) return value;
      if (typeof value.toDate === "function") {
        try {
          const d = value.toDate();
          return d instanceof Date && !Number.isNaN(d.getTime()) ? d : null;
        } catch {
          return null;
        }
      }
      if (typeof value.seconds === "number") {
        const ms = value.seconds * 1000 + Math.floor((Number(value.nanoseconds || 0) || 0) / 1000000);
        const d = new Date(ms);
        return Number.isNaN(d.getTime()) ? null : d;
      }
      const d = new Date(value);
      return Number.isNaN(d.getTime()) ? null : d;
    }

    function formatLastActiveLabel(profile) {
      if (!_authUser && _guestSessionActive) return "Active now";
      const date = toDateFromFirestoreLike(profile?.last_active);
      if (!date) return "Last active: unknown";
      const diff = Math.max(0, Date.now() - date.getTime());
      const mins = Math.floor(diff / 60000);
      if (mins <= 1) return "Active now";
      if (mins < 60) return `Active ${mins}m ago`;
      const hours = Math.floor(mins / 60);
      if (hours < 24) return `Active ${hours}h ago`;
      const days = Math.floor(hours / 24);
      if (days < 7) return `Active ${days}d ago`;
      return `Active ${date.toLocaleDateString("en-US", { month: "short", day: "numeric" })}`;
    }

    function formatFriendLastActiveLabel(profile, isOnline) {
      if (isOnline) return "Active now";
      const date = toDateFromFirestoreLike(profile?.last_active);
      if (!date) return "Last active: unknown";
      const diff = Math.max(0, Date.now() - date.getTime());
      const mins = Math.floor(diff / 60000);
      if (mins <= 1) return "Last active just now";
      if (mins < 60) return `Last active ${mins}m ago`;
      const hours = Math.floor(mins / 60);
      if (hours < 24) return `Last active ${hours}h ago`;
      const days = Math.floor(hours / 24);
      if (days < 7) return `Last active ${days}d ago`;
      return `Last active ${date.toLocaleDateString("en-US", { month: "short", day: "numeric" })}`;
    }

    function getFriendLastActiveMs(profile) {
      const date = toDateFromFirestoreLike(profile?.last_active);
      return date ? date.getTime() : 0;
    }

    function sortFriendsByFavoriteAndLastActive(entries) {
      return entries.sort((a, b) => {
        const favoriteDifference = Number(b?.favorite === true) - Number(a?.favorite === true);
        if (favoriteDifference) return favoriteDifference;
        const activityDifference = getFriendLastActiveMs(b?.profile) - getFriendLastActiveMs(a?.profile);
        if (activityDifference) return activityDifference;
        const aName = String(a?.profile?.nickname || a?.nickname || "");
        const bName = String(b?.profile?.nickname || b?.nickname || "");
        return aName.localeCompare(bName, undefined, { sensitivity: "base" });
      });
    }

    function getFriendLevelLabel(profile) {
      const statsSource = (profile && typeof profile.stats === "object") ? profile.stats : {};
      return `Level ${resolveHeaderLevel(statsSource)}`;
    }

    function resolveHeaderLevel(statsSource) {
      const src = (statsSource && typeof statsSource === "object") ? statsSource : {};
      const progress = getLevelProgressFromTotalXp(getStoredTotalXp(src));
      return progress.level;
    }

    // Pop a one-by-one "you unlocked …" popup for any avatar that appeared on the
    // account WITHOUT going through the in-client grant path, e.g. the Fish /
    // Amberjack icons granted server-side by a Supporter-Tier purchase (Stripe
    // webhook). A per-account baseline in localStorage records icons we've already
    // shown or that the player already owned, so existing icons never re-pop and
    // each newly granted skin pops individually. Skipped while viewing another
    // player's collection (read-only) so their icons never pop for us.
    const SEEN_ICONS_PREFIX = "cc_seen_icons_";
    function _popNewlyGrantedIcons(uid, icons) {
      if (!uid || _galReadOnly) return;
      const key = SEEN_ICONS_PREFIX + uid;
      const current = (Array.isArray(icons) ? icons : [])
        .filter(s => typeof s === "string" && s.startsWith("/avatars/"));
      let raw = null;
      try { raw = localStorage.getItem(key); } catch {}
      if (raw == null) {
        // First time we've tracked this account → seed silently (don't pop icons
        // the player already owns), then pop only what's granted from here on.
        try { localStorage.setItem(key, JSON.stringify(current)); } catch {}
        return;
      }
      let seen;
      try { seen = new Set(JSON.parse(raw) || []); } catch { seen = new Set(); }
      for (const path of current) {
        if (seen.has(path)) continue;
        seen.add(path);
        const a = _animalByImg[path];
        if (a) _queueAnimalUnlock(a.id);   // queues + shows each one individually
      }
      try { localStorage.setItem(key, JSON.stringify([...seen])); } catch {}
    }

    function syncStatsHeader(profile) {
      const incomingProfile = (profile && typeof profile === "object") ? profile : null;
      const currentAccountProfile = (_authUser && _activeProfile && _activeProfile.uid === _authUser.uid)
        ? _activeProfile
        : null;
      const incomingMatchesCurrentUid = !!(_authUser && incomingProfile && incomingProfile.uid === _authUser.uid);
      const headerProfile = _authUser
        ? (incomingMatchesCurrentUid ? incomingProfile : currentAccountProfile)
        : (incomingProfile || _activeProfile || null);

      if (headerProfile && typeof headerProfile === "object") {
        _playerNickname = String(headerProfile.nickname || "").trim();
        _friendCode = headerProfile.friend_code ? String(headerProfile.friend_code).trim() : "";
      } else if (_authUser) {
        // Prevent cross-account bleed when profile data is not yet loaded.
        _playerNickname = "";
        _friendCode = "";
      }
      const nick = _playerNickname || (_guestSessionActive ? "Guest" : "Player");
      const displayNick = nick;
      const displayFc = formatFriendCodeLabel(nick, _friendCode);
      const nickEl = $a("stats-lobby-nick");
      const fcEl = $a("stats-lobby-fc");
      if (nickEl) {
        nickEl.textContent = displayNick;
        // My own name on the Player Home profile card wears my Prestige colour
        // and badge like everyone else's does.
        if (_authUser && !_guestSessionActive) {
          nickEl.setAttribute("data-cc-pname", _authUser.uid);
          nickEl.setAttribute("data-cc-surface", "light");
          try { window.__ccRefreshNames?.(); } catch (_) {}
        } else {
          nickEl.removeAttribute("data-cc-pname");
        }
      }
      if (fcEl) fcEl.textContent = displayFc;
      const profileBarName = $a("auth-profile-name-text");
      const profileBarFc = $a("auth-profile-fc-text");
      const fcDisplay = $a("auth-my-fc-display");
      if (profileBarName) profileBarName.textContent = nick;
      if (profileBarFc) profileBarFc.textContent = _friendCode ? "#" + _friendCode : "";
      if (fcDisplay) fcDisplay.textContent = _friendCode || "-";

      const statsSource =
        (headerProfile && typeof headerProfile.stats === "object" ? headerProfile.stats : null)
        || (_guestSessionActive ? loadGuestStats(_playerNickname || "guest") : null)
        || {};
      const levelChip = $a("stats-name-level");
      if (levelChip) levelChip.textContent = `Level ${resolveHeaderLevel(statsSource)}`;
      const activeSourceProfile =
        (headerProfile ? headerProfile : null)
        || (!_authUser && _guestSessionActive ? _activeProfile : null)
        || null;
      const activeChip = $a("stats-name-active");
      if (activeChip) activeChip.textContent = formatLastActiveLabel(activeSourceProfile);

      // Total XP + Daily Streak chips in the header
      const totalXpEl = $a("hdr-total-xp");
      if (totalXpEl) {
        const tx = getStoredTotalXp(statsSource);
        totalXpEl.textContent = tx > 0 ? tx.toLocaleString() : "0";
      }
      // Daily streak, computed from streak_days (the single source of truth),
      // so the header chip, sidebar card, and yearly calendar always agree.
      let _streakCount = 0;
      try {
        if (typeof _computeStreakInfo === "function") {
          _streakCount = _computeStreakInfo(statsSource.streak_days).current;
        } else {
          _streakCount = Number(statsSource.daily_streak || 0);
        }
      } catch { _streakCount = Number(statsSource.daily_streak || 0); }
      const streakEl = $a("hdr-streak");
      if (streakEl) streakEl.textContent = _streakCount > 0 ? `${_streakCount} day${_streakCount !== 1 ? "s" : ""}` : "0 days";
      // Critter Coins balance chip, credited server-side on a Stripe purchase
      // (stats.critter_coins). Shows 0 until the wallet is funded.
      const coinsEl = $a("hdr-coins");
      if (coinsEl) {
        const cc = Math.max(0, Math.floor(Number(statsSource.critter_coins) || 0));
        coinsEl.textContent = cc.toLocaleString();
      }
      // Sidebar streak card (big number + XP labels), one source of truth.
      if (typeof window._updateStreakXp === "function") window._updateStreakXp(_streakCount);
      // Weekly Mon→Sun dots, driven by the same streak data.
      if (typeof window._renderStreakWeek === "function") window._renderStreakWeek();

      renderStatsAvatar(headerProfile || _activeProfile, nick);

      // The Discord reward chip sits in this same profile card and its text
      // depends on who is signed in ("+250 to claim" vs "250 claimed"), so it
      // re-syncs from the one place that already runs on sign-in, sign-out and
      // every profile reload. The module itself only re-asks the server when
      // the account actually changed.
      try { window.__ccDiscordSync && window.__ccDiscordSync(); } catch (_) {}
    }

    function setStatsAvatarClickable(enabled) {
      const wrap = $a("stats-avatar");
      if (!wrap) return;
      if (enabled) {
        wrap.classList.add("ph-avatar-clickable");
        wrap.tabIndex = 0;
        wrap.setAttribute("role", "button");
        wrap.setAttribute("aria-label", "Change avatar");
        wrap.title = "Change avatar";
      } else {
        wrap.classList.remove("ph-avatar-clickable");
        wrap.tabIndex = -1;
        wrap.removeAttribute("role");
        wrap.removeAttribute("aria-label");
        wrap.title = "";
      }
    }

    function prepareSignupAvatarSelection(seed) {
      const baseSeed = seed || _authUser?.uid || _authUser?.email;
      // A NEW ACCOUNT starts with the starter critters, never with the wider
      // set a guest session is allowed to wear: otherwise anyone could play one
      // guest game and then seed a fresh account with an earned critter they
      // have not earned. _withOwnedOnly wraps the click handler too, because
      // that runs long after this function has returned.
      _signupAvatarUrl = _withOwnedOnly(() => sanitizeSelectableAvatar(_signupAvatarUrl, baseSeed));
      const rerender = () => {
        _withOwnedOnly(() => {
          renderAvatarGrid("auth-avatar-grid", _signupAvatarUrl, (selected) => {
            _signupAvatarUrl = _withOwnedOnly(() => sanitizeSelectableAvatar(selected, baseSeed));
            rerender();
          });
        });
      };
      rerender();
    }

    function openAvatarPickerModal(opts) {
      const options = opts || {};
      const modal = $a("avatar-picker-modal");
      if (!modal) return;
      // Guests choose an avatar too; applyAvatarSelection() already knows how
      // to persist a guest's pick to this browser instead of an account.
      const forceRequired = !!options.required;
      const guestMode = !!options.guestMode || (!_authUser && _guestSessionActive);
      const seed = guestMode
        ? (_playerNickname || "guest")
        : (_authUser?.uid || _authUser?.email || _playerNickname || "player");
      const currentAvatar = guestMode
        ? normalizeAvatarUrl(_guestAvatarUrl || _activeProfile?.avatar_url || "")
        : normalizeAvatarUrl(_activeProfile?.avatar_url || "");
      _avatarModalSelection = sanitizeSelectableAvatar(currentAvatar, seed);
      const rerender = () => {
        renderAvatarGrid("avatar-modal-grid", _avatarModalSelection, (selected) => {
          _avatarModalSelection = sanitizeSelectableAvatar(selected, seed);
          rerender();
        });
      };
      rerender();
      _avatarSelectionRequired = forceRequired;
      const cancelBtn = $a("avatar-modal-cancel");
      if (cancelBtn) cancelBtn.style.display = _avatarSelectionRequired ? "none" : "";
      setAuthMsg("avatar-modal-err", "", false);
      modal.classList.add("open");
    }

    function closeAvatarPickerModal() {
      if (_avatarSelectionRequired) return;
      const modal = $a("avatar-picker-modal");
      if (modal) modal.classList.remove("open");
      _avatarSelectionRequired = false;
    }

    // Persist + apply an avatar selection (shared by the picker and the
    // post-game unlock screen's "make this my avatar" button).
    async function applyAvatarSelection(selected) {
      // Never equip/persist while viewing another player's collection, the
      // globals are swapped to their data and writes target MY account.
      if (_galReadOnly) return false;
      // Refresh our own nick-avatar cache entry immediately so our chat icon
      // (and anything reading by our nickname) updates instantly on this
      // client; other clients pick it up from Firestore within the TTL.
      try {
        const myNick = (_playerNickname || (_activeProfile && _activeProfile.nickname) || "").trim();
        if (myNick && _nickAvatarCache) {
          _nickAvatarCache[myNick] = { url: normalizeAvatarUrl(selected) || selected, ts: Date.now() };
        }
      } catch {}
      if (_authUser && _db) {
        await _db.collection("users").doc(_authUser.uid).set({ avatar_url: selected }, { merge: true });
        _activeProfile = { ...(_activeProfile || {}), uid: _authUser.uid, avatar_url: selected };
        syncStatsHeader(_activeProfile);
        loadFriendsMini(_authUser.uid);
        renderPhOverview();
        renderPhFriendsList();
      } else if (_guestSessionActive) {
        _guestAvatarUrl = selected;
        localStorage.setItem(GUEST_AVATAR_KEY, selected);
        _activeProfile = {
          ...(_activeProfile || {}),
          nickname: _playerNickname || "Guest",
          avatar_url: selected,
        };
        syncStatsHeader(_activeProfile);
        const previewEl = $a("stats-friends-preview");
        if (previewEl) previewEl.innerHTML = '<div class="ph-empty">No friends added yet.</div>';
      } else {
        throw new Error("no-session");
      }
      // If we're in a game, push the new avatar to the server immediately so
      // every other player sees it on this seat right away.
      try { if (typeof window.__fishPushSeatAvatar === "function") window.__fishPushSeatAvatar(); } catch (e) {}

      // Equipping the Spinner Dolphin summons the Giant Squid challenge (only
      // while the Red Beaded Anemone is still locked).
      try {
        if (String(selected) === "/avatars/spinner-dolphin.png"
            && typeof isAvatarUnlocked === "function"
            && !isAvatarUnlocked("/avatars/sea-anemone.png")) {
          setTimeout(_showGiantSquidChallenge, 450);
        }
      } catch (_) {}
    }

    // ── Giant Squid challenge modal (King of the Critters gate) ──────────
    let _gsChallengeWired = false;
    function _showGiantSquidChallenge() {
      const modal = $a("giant-squid-modal");
      if (!modal) return;
      const msg = $a("gs-challenge-msg");
      const fightBtn = $a("gs-challenge-fight-btn");
      if (msg) msg.textContent = "If you want to save the Red Beaded Anemone, you have to beat me in a fight.";
      if (fightBtn) fightBtn.style.display = "";
      if (!_gsChallengeWired) {
        _gsChallengeWired = true;
        if (fightBtn) fightBtn.addEventListener("click", async () => {
          // Must be King of the Critters to challenge.
          const rank = (_activeProfile && _activeProfile.stats && _activeProfile.stats.rank_competitive) || "";
          if (rankTierValue(rank) < 6) {
            if (msg) msg.textContent = "Come back when you are stronger.";
            fightBtn.style.display = "none";
            return;
          }
          modal.classList.remove("open");
          try { if (typeof window.__fishStartGiantSquidChallenge === "function") await window.__fishStartGiantSquidChallenge(); } catch (_) {}
        });
        const laterBtn = $a("gs-challenge-later-btn");
        if (laterBtn) laterBtn.addEventListener("click", () => modal.classList.remove("open"));
        modal.addEventListener("click", (e) => { if (e.target === modal) modal.classList.remove("open"); });
      }
      modal.classList.add("open");
    }

    async function saveAvatarSelection() {
      const wasRequired = !!_avatarSelectionRequired;
      const seed = _authUser?.uid || _playerNickname || "guest";
      const selected = sanitizeSelectableAvatar(_avatarModalSelection, seed);
      if (!selected) {
        setAuthMsg("avatar-modal-err", "Choose an avatar first.", false);
        return;
      }
      setAuthMsg("avatar-modal-err", "Saving…", true);
      try {
        await applyAvatarSelection(selected);
        _avatarSelectionRequired = false;
        const modal = $a("avatar-picker-modal");
        if (modal) modal.classList.remove("open");
        if (_authUser && wasRequired && _pendingOnboardingUid && _pendingOnboardingUid === _authUser.uid) {
          _pendingOnboardingUid = "";
          revealLobby(_playerNickname, _friendCode);
        }
      } catch (e) {
        setAuthMsg("avatar-modal-err", "Could not save avatar. Try again.", false);
      }
    }

    function revealLobby(nickname, code) {
      _playerNickname = (nickname || "").trim();
      _friendCode     = code || "";
      _guestSessionActive = !_authUser;
      // Through the door, by either road (guest or account). Floating game
      // chrome may exist from here on, and not one moment earlier.
      document.body.classList.add("cc-signed-in");
      // Both roads in end here, so this is where a change of person is noticed
      // and the last person's cached data is dropped. It has to run before the
      // lobby paints anything, or the first frame is still the last identity's.
      _ccBecomeIdentity();
      // A registered player is now in their account, drop any stale guest
      // session left in localStorage so it can never later hijack a re-auth
      // (e.g. a token refresh momentarily reading as signed-out) and drop them
      // into a guest "Player" lobby. Guests keep their saved session.
      if (_authUser) {
        try { localStorage.removeItem(GUEST_NICK_KEY); localStorage.removeItem(GUEST_AVATAR_KEY); } catch (_) {}
        ccForgetGuestSessionMark();
      } else if (_guestSessionActive) {
        // The wipe above belongs to whoever just LEFT. A guest arriving gets
        // their own critter and their own unlocked list put back, so a reload
        // no longer costs them the critters they just earned, and nothing they
        // are wearing quietly reverts to the Mullet.
        ccMarkGuestSession(_playerNickname);
        ccRestoreGuestSessionState();
      }
      _activeProfile = {
        ...(_activeProfile || {}),
        nickname: _playerNickname,
        friend_code: _friendCode,
        last_active: new Date(),
      };
      lockNameInputs(_playerNickname);

      // ── Full lobby experience ────────────────────────────────────
      if (_authUser && _playerNickname) {
        const bar = $a("auth-profile-bar");
        if (bar) {
          bar.style.display = "flex";
          const nameEl = $a("auth-profile-name-text");
          const fcEl   = $a("auth-profile-fc-text");
          if (nameEl) nameEl.textContent = _playerNickname;
          if (fcEl)   fcEl.textContent   = _friendCode ? "#" + _friendCode : "";
          const fcDisplay = $a("auth-my-fc-display");
          if (fcDisplay) fcDisplay.textContent = _friendCode || "-";
        }
        // Start presence ping and listen for incoming friend requests
        startPresencePing(_authUser.uid);
        listenForFriendRequests(_authUser.uid);
        // Start DM conversation listener (drives the header unread badge)
        if (typeof _msgStartListListener === "function") _msgStartListListener();
        // Apply any competitive forfeit losses incurred while we were offline.
        try { setTimeout(() => { checkPendingForfeitLosses().catch(() => {}); }, 1500); } catch (_) {}
        // Anything found on the sign-in screen, before this account had a
        // name, is filed against it now. See ccCoralClaim().
        try { ccCoralClaim().catch(() => {}); } catch (_) {}
        // Put this account's clan critter on the Clans nav button right away.
        // It shows from every tab, so it must not wait for the Clans tab to be
        // opened (clans-ui.js also picks this up on its own, just slower).
        try { window.__ccClansPrimeTabIcon && window.__ccClansPrimeTabIcon(); } catch (_) {}
        // ── Prestige on sign-in ────────────────────────────────────
        // Warm the Prestige state (it drives the badge + name colour on every
        // username in the app, so it must be ready before the first
        // leaderboard/friends paint), then, ONLY if this account is sitting at
        // the level cap: ask whether they'd like to ride the next current.
        // Prestige is always optional: the ask has a "Not right now", closes on
        // Escape, starts nothing by itself, and comes back next sign-in.
        try {
          setTimeout(async () => {
            try {
              await window.__ccPrestigePrime?.();
              window.__ccRefreshNames?.();
              await window.__ccPrestigeAsk?.();
            } catch (_) {}
          }, 1200);
        } catch (_) {}
      }
      $a("auth-loading-screen").classList.add("hidden");
      $a("auth-screen").classList.add("hidden");
      showStatsLobby();
      // The full-screen launch splash is a separate-WINDOW (desktop) concept;
      // on mobile we play inline in the tab, so skip it and reveal the home
      // screen directly. Once dismissed (Play or "Continue in this window"),
      // a same-tab reload (e.g. the update-banner "Refresh now" button)
      // should land back in the lobby instead of re-showing the splash.
      let _splashAlreadyDismissed = false;
      try { _splashAlreadyDismissed = sessionStorage.getItem("cc_fs_splash_dismissed") === "1"; } catch (_) {}
      if (!window.CC_IS_MOBILE && !_splashAlreadyDismissed) document.getElementById("cc-fs-splash")?.classList.add("show");
    }

    // Reveal the lobby for a RETURNING guest (auto-restored from a saved
    // nickname). Nothing stands between a guest and the lobby any more, the
    // Terms gate that used to sit here is gone (build 1.6.48).
    function revealGuestLobby(nick) {
      revealLobby(nick, "");
    }

    // Reveal the lobby for a signed-in REGISTERED account. `profile`/`user` are
    // captured by the caller; if a transient auth blip nulled _authUser we
    // re-assert the captured account first, because revealLobby() reads
    // _authUser to decide account-vs-guest and would otherwise fall through to
    // a guest "Player" session.
    function revealRegisteredLobby(nickname, code, profile, user) {
      const acct = _authUser || user || null;
      if (!_authUser && acct) { _authUser = acct; _ccHadAccountUser = true; _guestSessionActive = false; }
      // Safety net: with no account identity at all, back to sign-in rather
      // than silently dropping them into a guest session.
      if (!_authUser) {
        const ls = $a("auth-loading-screen"); if (ls) ls.classList.add("hidden");
        showStep("auth-step-choose");
        return;
      }
      // This account already existed, so a guest snapshot staged on the way in
      // has no home: it is never merged into a history that is already there.
      // Dropped here rather than left lying around, so it cannot be claimed
      // later by an unrelated sign-up on this device. The guest's own blobs go
      // with it: the session that led here is over for real now. The
      // device-wide caches are left alone, because from this point on they
      // belong to the account standing in front of them.
      clearGuestMigration();
      purgeGuestData();
      revealLobby(nickname, code);
      // Signed in with a real account: warm the reward caches now, so the XP
      // boost is known before the first game finishes rather than after.
      try { window.__ccPrimeRewardModules && window.__ccPrimeRewardModules(); } catch (_) {}
      // Accounts that existed before recovery codes did get theirs here: a
      // sign-in is the only moment we are sure it is really them. Does nothing
      // for a Google account, or for one that already has a code.
      try { void ccEnsureRecoveryCode(); } catch (_) {}
    }

    // Ends the guest session in this page. It deliberately does NOT erase what
    // was played: most callers are a sign-in ATTEMPT, and an attempt can be
    // cancelled (a closed Google window, a username already taken). Deleting a
    // guest's afternoon because they backed out of a form would be the worst
    // possible reading of "nothing is saved". The erasing happens at the two
    // moments that really end a guest session: signOutGuestForGood(), and
    // arriving in a real account.
    //
    // The nickname is remembered on the way out, so coming back is one tap on
    // PLAY AS GUEST and the same session is still there.
    function clearGuestSessionStorage() {
      try {
        const nick = (localStorage.getItem(GUEST_NICK_KEY) || "").trim() || ccGuestSessionNick();
        // Offered back on the guest pane of THIS window only, never written to
        // the device: the next person to open the game is a different person
        // and must type their own name.
        if (nick) { try { sessionStorage.setItem(GUEST_RESUME_KEY, nick); } catch (_) {} }
        // The nickname is what auto-restores a guest, so it goes while the
        // sign-in is in flight. The critter is not: it belongs to the session,
        // and a cancelled sign-in gives that session straight back, wearing
        // what it was wearing.
        localStorage.removeItem(GUEST_NICK_KEY);
      } catch (_) {}
      _guestSessionActive = false;
      // Every caller of this is leaving the current identity behind. Drop the
      // Level Pass cache with it, so the sidebar's unclaimed badge cannot show
      // the last account's number to the next one.
      try { window.__ccLevelPassReset && window.__ccLevelPassReset(); } catch (_) {}
    }

    // ── Stats lobby helpers ───────────────────────────────────────
    function showStatsLobby() {
      // Only stay out of the Player Home if a real game board is actually on
      // screen (deep-linked straight into a room). This used to bounce to a
      // long-dead create/join "old lobby" page whenever a stale room id merely
      // lingered in the URL: e.g. right after leaving a tournament, instead of
      // landing on the nice Player Home. Keying off the visible game board means
      // returning home ALWAYS shows the real home (daily/weekly, leaderboards…).
      const _pvGameEl = $a("pv-game");
      if (_pvGameEl && _pvGameEl.style.display && _pvGameEl.style.display !== "none") { return; }
      if (!_authUser && !_guestSessionActive) {
        const sl = $a("auth-stats-lobby");
        if (sl) sl.classList.remove("visible");
        $a("auth-loading-screen").classList.add("hidden");
        $a("auth-screen").classList.remove("hidden");
        showStep("auth-step-choose");
        return;
      }
      const el = $a("auth-stats-lobby");
      if (!el) { return; }
      const legacyLobby = $a("pv-lobby");
      if (legacyLobby) legacyLobby.style.display = "none";
      const gameRoot = $a("pv-game");
      if (gameRoot) gameRoot.style.display = "none";
      [
        "pv-waiting-room",
        "lobby-browser-modal",
        "lb-pw-prompt",
        "new-current-modal",
        "seat-picker-modal",
        "pv-score-modal",
        "comp-overlay",
        "tut-exit-confirm",
        "tut-zoom",
        "pv-board-focus",
        "pv-endgame-overlay",
        "leaderboard-modal",
        "settings-modal",
        "avatar-picker-modal",
        "pv-zoom-modal",
      ].forEach((id) => {
        const modal = $a(id);
        if (modal) modal.classList.remove("open");
      });
      const floatingLog = $a("pv-log-float");
      if (floatingLog) floatingLog.classList.remove("open");
      const chatPanel = $a("pv-chat-panel");
      if (chatPanel) chatPanel.classList.remove("open");
      const chatBtn = $a("pv-chat-btn");
      if (chatBtn) chatBtn.style.display = "none";
      el.classList.add("visible");
      $a("auth-screen").classList.add("hidden");
      // Returning to the lobby restores hidden critters + (re)wires the star.
      try { if (typeof window.__fishResetSecrets === "function") window.__fishResetSecrets(); } catch (_) {}
      try { if (typeof window.__fishInitStaticSecrets === "function") setTimeout(window.__fishInitStaticSecrets, 200); } catch (_) {}
      // Surface the "Rejoin Game" button if a recently-left game is still open.
      try { if (typeof _refreshRejoinButton === "function") _refreshRejoinButton(); } catch (e) {}
      syncStatsHeader(_activeProfile);
      const nick = _playerNickname || "Player";
      // Show sign out for everyone; show Friends only for signed-in users
      const signedEl = $a("stats-lobby-signed-actions");
      if (signedEl) signedEl.style.display = "grid";
      const friendBtn = $a("stats-friend-btn");
      if (friendBtn) friendBtn.style.display = (_authUser && _friendCode) ? "" : "none";
      // The avatar on the profile card opens the gallery for a guest too: they
      // may wear anything they have not had to buy, so the way in has to be
      // there. Only a session with no identity at all (neither account nor
      // guest) has nothing to change.
      setStatsAvatarClickable(!!(_authUser || _guestSessionActive));
      // Guest notice
      const guestNotice = $a("stats-guest-notice");
      if (guestNotice) guestNotice.style.display = _guestSessionActive ? "" : "none";
      // Settings nick display
      const settingsNick = $a("settings-current-nick");
      if (settingsNick) settingsNick.textContent = nick;
      const settingsStatus = $a("settings-account-status");
      if (settingsStatus) {
        // A username-and-password account signs in with a name that never
        // changes, even after the player renames the name everybody else
        // sees. This row is the only place they can go to look it up.
        const loginName = String(_activeProfile?.login_username || "").trim();
        settingsStatus.textContent = !_authUser ? "Guest session"
          : (_authUser.providerData?.[0]?.providerId === "google.com") ? "Google account"
          : loginName ? ("Sign in as " + loginName)
          : "Username and password";
      }
      // Load stats
      if (_authUser) {
        loadAndRenderStats(_authUser.uid);
        loadFriendsMini(_authUser.uid);
      } else {
        _activeProfile = {
          ...(_activeProfile || {}),
          nickname: _playerNickname || "Guest",
          avatar_url: sanitizeSelectableAvatar(_guestAvatarUrl, _playerNickname || "guest"),
        };
        syncStatsHeader(_activeProfile);
        renderStats(loadGuestStats(_playerNickname || "guest"));
        const previewEl = $a("stats-friends-preview");
        if (previewEl) previewEl.innerHTML = '<div class="ph-empty">No friends added yet.</div>';
      }
    }

    async function loadAndRenderStats(uid) {
      const expectedUid = String(uid || "");
      if (!_authUser || _authUser.uid !== expectedUid) return;
      const loadSeq = ++_statsLoadSeq;
      let profile = await loadProfile(uid);
      // SAFETY: Only write defaultGuestStats if the Firestore doc truly does not exist.
      // Never overwrite stats on a transient load error, that was the primary data-loss bug.
      if (_authUser && _db && !profile) {
        try {
          const { reason } = await loadProfileWithReason(uid);
          if (reason === "notfound") {
            // Doc doesn't exist yet, safe to initialise (brand new sign-in, no stats to lose).
            // initStatsIfAbsent re-checks inside a transaction, so even a wrong "notfound"
            // or a concurrent create can never overwrite real stats with defaults.
            await initStatsIfAbsent(uid);
            profile = await loadProfile(uid);
          }
          // reason === "error": leave profile null, don't touch Firestore.
        } catch {}
      } else if (_authUser && _db && profile && (!profile.stats || typeof profile.stats !== "object")) {
        // Profile exists but stats field is missing, use defaults in memory only.
        // Do NOT write to Firestore here: a stale read (transient Firebase error) returning
        // profile without stats would otherwise wipe all previously saved stats via this path.
        // The next game completion will write real stats via saveGameStats() instead.
        profile = { ...profile, stats: defaultGuestStats() };
      }
      if (loadSeq !== _statsLoadSeq || !_authUser || _authUser.uid !== expectedUid) return;
      _activeProfile = profile || null;
      // Load unlocked icons from profile
      _unlockedIcons = Array.isArray(profile?.unlocked_icons)
        ? profile.unlocked_icons.filter(s => typeof s === "string" && s.startsWith("/avatars/"))
        : [];
      // Pop an individual unlock popup for any icon granted out-of-band (e.g. a
      // Supporter-Tier purchase's Fish / Amberjack skins, credited by the webhook).
      try { _popNewlyGrantedIcons(uid, _unlockedIcons); } catch {}
      _unlockedBackgrounds = Array.isArray(profile?.unlocked_backgrounds)
        ? profile.unlocked_backgrounds.map(s => normalizeBgUrl(s)).filter(Boolean)
        : [];
      const savedAvatar = normalizeAvatarUrl(_activeProfile?.avatar_url || "");
      const hasSelectableAvatar = hasStoredSelectableAvatar(profile);
      if (_activeProfile) _activeProfile = { ..._activeProfile, uid };
      if (_activeProfile && savedAvatar) _activeProfile.avatar_url = savedAvatar;
      syncStatsHeader(_activeProfile);
      renderStats(profile && profile.stats ? profile.stats : null);
      if (typeof window.__fishLoadUserAchievements === "function") window.__fishLoadUserAchievements(uid);
      // Avatar-set migration: anyone without a valid (Mullet/unlocked) avatar
      // is silently defaulted to Mullet, no forced picker.
      if (_authUser && _authUser.uid === uid && !hasSelectableAvatar) {
        try { await applyAvatarSelection(DEFAULT_AVATAR_IMG); } catch {}
      }
      // Best-effort popularity load + retroactive grant of already-earned unlocks.
      try { window.__fishLoadIconCounts?.(); } catch {}
      try {
        if (typeof window.__fishSyncStatUnlocks === "function") {
          const _syncNewly = await window.__fishSyncStatUnlocks();
          if (Array.isArray(_syncNewly) && _syncNewly.length) {
            _syncNewly.forEach(id => window.__fishQueueAnimalUnlock?.(id));
            setTimeout(() => window.__fishShowAnimalUnlocks?.(), 1400);
          }
        }
      } catch {}
      // Broke a streak by exactly one day? Show the countdown straight away and
      // offer a Streak Shield (once per missed day). The popup runs last and on
      // a delay so it never lands on top of the unlock popups above.
      try { window._renderStreakRescue?.(); } catch {}
      try {
        const _shieldStats = (profile && profile.stats) ? profile.stats : null;
        if (_shieldStats) setTimeout(() => { try { window.__fishOfferStreakShield?.(_shieldStats); } catch {} }, 2200);
      } catch {}
    }

    const PIE_COLORS = ["#22d8f8","#f0c840","#2ecc71","#e06c75","#c678dd","#e5c07b","#56b6c2","#d19a66"];
    const PIE_COLORS_COMP = ["#f0c840","#e06c75","#c678dd","#22d8f8","#2ecc71","#e5c07b"];

    function renderPieChart(containerId, sizeData, isComp) {
      const el = $a(containerId);
      if (!el) return;
      el.innerHTML = "";
      const entries = Object.entries(sizeData || {})
        .map(([k, v]) => ({ n: parseInt(k), count: Number(v) }))
        .filter(e => e.count > 0)
        .sort((a, b) => a.n - b.n);
      if (!entries.length) { el.classList.remove("visible"); return; }
      el.classList.add("visible");

      const total = entries.reduce((s, e) => s + e.count, 0);
      const colors = isComp ? PIE_COLORS_COMP : PIE_COLORS;
      const S = 120, cx = 60, cy = 60, r = 44, ri = 18; // donut hole
      let angle = -Math.PI / 2;

      // Tooltip (appended to body so it's never clipped)
      const tip = document.createElement("div");
      tip.className = "stats-pie-tooltip";
      document.body.appendChild(tip);

      const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      svg.setAttribute("viewBox", `0 0 ${S} ${S}`);
      svg.setAttribute("class", "stats-pie-svg");
      svg.style.width = svg.style.height = "120px";

      entries.forEach((e, i) => {
        const slice = (e.count / total) * 2 * Math.PI;
        const end = angle + slice;
        const x1 = cx + r * Math.cos(angle),  y1 = cy + r * Math.sin(angle);
        const x2 = cx + r * Math.cos(end),    y2 = cy + r * Math.sin(end);
        const ix1 = cx + ri * Math.cos(end),  iy1 = cy + ri * Math.sin(end);
        const ix2 = cx + ri * Math.cos(angle),iy2 = cy + ri * Math.sin(angle);
        const large = slice > Math.PI ? 1 : 0;
        const d = `M${x1},${y1} A${r},${r} 0 ${large} 1 ${x2},${y2} L${ix1},${iy1} A${ri},${ri} 0 ${large} 0 ${ix2},${iy2} Z`;
        const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
        path.setAttribute("d", d);
        path.setAttribute("fill", colors[i % colors.length]);
        path.setAttribute("stroke", "rgba(4,20,35,.6)");
        path.setAttribute("stroke-width", "1.5");
        const pct = Math.round((e.count / total) * 100);
        path.addEventListener("mouseenter", () => {
          tip.textContent = `${e.n} Players, ${e.count} game${e.count !== 1 ? "s" : ""} (${pct}%)`;
          tip.style.display = "block";
        });
        path.addEventListener("mousemove", ev => {
          tip.style.left = (ev.clientX + 12) + "px";
          tip.style.top  = (ev.clientY - 32) + "px";
        });
        path.addEventListener("mouseleave", () => { tip.style.display = "none"; });
        svg.appendChild(path);
        angle = end;
      });

      // Center label: total games
      const txt = document.createElementNS("http://www.w3.org/2000/svg", "text");
      txt.setAttribute("x", cx); txt.setAttribute("y", cy + 1);
      txt.setAttribute("text-anchor", "middle"); txt.setAttribute("dominant-baseline", "middle");
      txt.setAttribute("fill", "#fff"); txt.setAttribute("font-size", "13");
      txt.setAttribute("font-weight", "800"); txt.setAttribute("font-family", "Nunito, sans-serif");
      txt.textContent = total;
      svg.appendChild(txt);
      const sub = document.createElementNS("http://www.w3.org/2000/svg", "text");
      sub.setAttribute("x", cx); sub.setAttribute("y", cy + 13);
      sub.setAttribute("text-anchor", "middle"); sub.setAttribute("dominant-baseline", "middle");
      sub.setAttribute("fill", "rgba(255,255,255,.45)"); sub.setAttribute("font-size", "7");
      sub.setAttribute("font-family", "Nunito, sans-serif");
      sub.textContent = "games";
      svg.appendChild(sub);

      // Legend
      const legend = document.createElement("div");
      legend.className = "stats-pie-legend";
      const title = document.createElement("div");
      title.className = "stats-pie-title";
      title.textContent = "Players per game";
      legend.appendChild(title);
      entries.forEach((e, i) => {
        const pct = Math.round((e.count / total) * 100);
        const item = document.createElement("div");
        item.className = "stats-pie-legend-item";
        item.innerHTML = `<span class="stats-pie-legend-dot" style="background:${colors[i % colors.length]}"></span>
          <span class="stats-pie-legend-label">${e.n}P</span>
          <span class="stats-pie-legend-count">${e.count} game${e.count !== 1 ? "s" : ""} · ${pct}%</span>`;
        item.addEventListener("mouseenter", () => {
          tip.textContent = `${e.n} Players, ${e.count} game${e.count !== 1 ? "s" : ""} (${pct}%)`;
          tip.style.display = "block";
        });
        item.addEventListener("mousemove", ev => {
          tip.style.left = (ev.clientX + 12) + "px";
          tip.style.top  = (ev.clientY - 32) + "px";
        });
        item.addEventListener("mouseleave", () => { tip.style.display = "none"; });
        legend.appendChild(item);
      });

      el.appendChild(svg);
      el.appendChild(legend);
    }

    function setProfileLevelCard(stats) {
      const source = (stats && typeof stats === "object") ? stats : {};
      const progress = getLevelProgressFromTotalXp(getStoredTotalXp(source));
      const level = progress.level;
      const levelTitle = String(source.level_title || source.level_name || "Ocean Explorer").trim() || "Ocean Explorer";
      const xpCurrent = progress.xpCurrent;
      const xpGoal = progress.xpGoal;
      const fill = Math.max(0, Math.min(100, Math.round((xpCurrent / xpGoal) * 100)));

      const levelLabelEl = $a("stat-level-label");
      if (levelLabelEl) levelLabelEl.textContent = `Level ${level}`;
      // The waiting room draws this on my seat, so it is published from the one
      // place that already works it all out.
      try {
        window.__ccMyCard = {
          level: level, xp: xpCurrent, xp_goal: xpGoal,
          best: Math.max(0, Math.round(Number(source.highest_score) || 0)),
          games: Math.max(0, Math.round(Number(source.completed_games) || 0)),
          title: levelTitle,
        };
        window.__ccMyLevel = level;
      } catch (_) {}
      const levelTitleEl = $a("stat-level-title");
      if (levelTitleEl) levelTitleEl.textContent = levelTitle;
      const xpTextEl = $a("stat-level-xp-text");
      if (xpTextEl) xpTextEl.textContent = `${xpCurrent} / ${xpGoal} XP`;
      const xpFillEl = $a("stat-level-xp-fill");
      if (xpFillEl) xpFillEl.style.width = `${fill}%`;
    }

    function renderStats(stats) {
      const safeStats = getHomeReferenceStats(stats);
      // Show stats block if completed_games > 0, or if any per-size game counts exist
      const anyBySize = Object.values(safeStats.normal_games_by_size || {}).some(n => Number(n) > 0)
        || Object.values(safeStats.comp_games_by_size || {}).some(n => Number(n) > 0);
      const completed = (safeStats.completed_games || 0) > 0 || anyBySize;
      const noGamesEl = $a("stats-no-games");
      const normalBlock = $a("stats-normal-block");
      if (noGamesEl) noGamesEl.style.display = completed ? "none" : "";
      if (normalBlock) normalBlock.style.display = completed ? "" : "none";

      const s = (id, val, opts) => {
        const options = opts || {};
        const fallback = options.fallback ?? "-";
        const allowZero = !!options.allowZero;
        const el = $a(id);
        if (!el) return;
        const hasVal = val != null && val !== "" && (allowZero || val !== 0);
        el.textContent = hasVal ? String(val) : fallback;
      };
      setProfileLevelCard(safeStats);
      s("stat-comp-rank", safeStats.rank_competitive || null, { fallback: "No rank yet." });

      if (!completed) {
        renderPieChart("stat-normal-pie", {}, false);
        return;
      }

      s("stat-normal-wins", safeStats.normal_wins ?? 0, { allowZero: true });
      s("stat-completed", safeStats.completed_games ?? 0, { allowZero: true });
      s("stat-strategy", safeStats.most_played_strategy || null, { fallback: "No games completed yet." });
      renderPieChart("stat-normal-pie", safeStats.normal_games_by_size || {}, false);
    }

    // How many friend profiles the four-row home preview will read to decide
    // which four to show. Comfortably above any real friends list; it exists
    // for the one account that is friends with everybody (see loadFriendsMini).
    const FRIENDS_MINI_PROFILE_MAX = 80;

    async function loadFriendsMini(uid) {
      const miniBox     = $a("stats-friends-mini");
      const previewEl   = $a("stats-friends-preview");
      if (!miniBox || !previewEl) return;
      const friends = await loadFriends(uid);
      // Cache friend nicknames (lowercased) so game-end challenge hooks can
      // detect when an opponent is a friend without re-fetching Firestore.
      try {
        const set = new Set();
        for (const f of (friends || [])) {
          const nk = String(f?.nickname || "").trim().toLowerCase();
          if (nk) set.add(nk);
        }
        window.__fishFriendNicksLower = set;
      } catch {}
      miniBox.style.display = "";
      if (!friends.length) {
        previewEl.innerHTML = '<div class="ph-empty">No friends added yet.</div>';
        return;
      }
      // Sort every friend before taking the four-person preview so favorites
      // stay visible and everyone else appears by most recent activity.
      //
      // Sorting needs each friend's live profile, and that is ONE Firestore
      // read per friend, on every paint of Player Home. For an ordinary
      // account that is a handful. For the dev account, which is friends with
      // every player in the game, it would be one read per player just to
      // choose four rows, so the preview reads a bounded slice: favorites
      // first, because those are the people somebody chose to keep an eye on.
      // The Friends TAB still reads every profile: its "N of M online" tally
      // has to count everybody, and it only runs when the tab is opened.
      const candidates = friends.length > FRIENDS_MINI_PROFILE_MAX
        ? [...friends]
            .sort((a, b) => Number(b?.favorite === true) - Number(a?.favorite === true))
            .slice(0, FRIENDS_MINI_PROFILE_MAX)
        : friends;
      const profiles = await Promise.all(candidates.map(f => loadProfile(f.uid).catch(() => null)));
      const shown = sortFriendsByFavoriteAndLastActive(
        candidates.map((f, i) => ({ ...f, profile: profiles[i] }))
      ).slice(0, 4);
      previewEl.innerHTML = "";
      shown.forEach((f, i) => {
        const profile = f.profile;
        const online = isFriendOnline(profile);
        const liveNick = (profile && profile.nickname) || f.nickname;
        const friendName = escapeHtml(liveNick || "-");
        const levelText = getFriendLevelLabel(profile);
        const activeText = formatFriendLastActiveLabel(profile, online);
        const avatarUrl = resolveFriendAvatarUrl(resolveAvatarUrl(
          { ...(profile || {}), avatar_url: (profile && profile.avatar_url) || f.avatar_url || "" },
          { seed: f.uid || liveNick || `friend-${i}` }
        ), f.uid || liveNick || `friend-${i}`);
        let _fbgn = ""; try { _fbgn = normalizeBgUrl(profile && profile.background_url || ""); if (!_BG_BY_IMG[_fbgn]) _fbgn = ""; } catch {}
        const _fbgStyle = _fbgn ? ` style="${_bgStyle(_fbgn)}"` : "";
        const avatarHtml = avatarUrl
          ? `<div class="ph-fr-av"${_fbgStyle}><img src="${escapeHtml(_avSrc(avatarUrl))}" alt="${friendName} avatar" loading="lazy" referrerpolicy="no-referrer"></div>`
          : `<div class="ph-fr-av">${safeInitial(liveNick || "?")}</div>`;
        const d = document.createElement("div");
        d.className = "ph-fr";
        d.innerHTML = `${avatarHtml}<div class="ph-fr-main"><div class="ph-fr-name" data-cc-pname="${escapeHtml(f.uid || f.nickname || "")}">${friendName}</div><div class="ph-fr-meta">${escapeHtml(levelText)} • ${escapeHtml(activeText)}</div></div><div class="ph-fr-status ${online ? "ph-fr-online" : "ph-fr-offline"}"><div class="ph-fr-dot"></div>${online ? "Online" : "Offline"}</div>`;
        previewEl.appendChild(d);
      });
    }

    // enterGameLobby() removed: it existed only to reveal the legacy create/join
    // "old lobby" page. Deep-link room entry is handled by enterRoom()/the
    // auto-join boot flow, and showStatsLobby() now stays put when a game board
    // is already on screen, so this dead bounce is gone.

    let _lbSize = 2; // current player-count tab
    async function loadLeaderboard(size) {
      _lbSize = Number(size) || 2;
      const listEl = $a("lb-list");
      const errEl  = $a("lb-err");
      if (!listEl) return;
      if (!_db) { if (errEl) errEl.textContent = "Not connected."; return; }
      listEl.innerHTML = '<div style="color:var(--muted);font-size:12px;text-align:center;padding:12px 0;">Loading…</div>';
      if (errEl) errEl.textContent = "";
      try {
        const field = `stats.highest_score_${_lbSize}p`;
        const snap = await _db.collection("users").orderBy(field, "desc").limit(20).get({ source: "server" });
        if (snap.empty) {
          listEl.innerHTML = '<div style="color:var(--muted);font-size:12px;text-align:center;padding:12px 0;">No scores yet for this size.</div>';
          return;
        }
        listEl.innerHTML = "";
        let shown = 0;
        snap.docs.forEach((doc, i) => {
          const d    = doc.data();
          const nick = d.nickname || "Unknown";
          const score = d.stats?.[`highest_score_${_lbSize}p`] || 0;
          if (!score) return;
          shown++;
          const row = document.createElement("div");
          row.className = "lb-row";
          const isMe = (_authUser && doc.id === _authUser.uid);
          row.innerHTML = `
            <span class="lb-rank">#${shown}</span>
            <span class="lb-name${isMe?" lb-you":""}">${nick}${isMe?" (you)":""}</span>
            <span class="lb-score${isMe?" lb-you":""}">${score} pts</span>`;
          listEl.appendChild(row);
        });
        if (shown === 0) {
          listEl.innerHTML = '<div style="color:var(--muted);font-size:12px;text-align:center;padding:12px 0;">No scores yet for this size.</div>';
        }
      } catch(e) {
        if (errEl) errEl.textContent = "Could not load leaderboard.";
      }
    }

    // ── In-game Leaderboard panel ─────────────────────────────────
    let _phLbMode     = "xp";    // XP leaderboard is shown first
    let _phLbSize     = "all";
    let _phLbCompTab  = "cp";
    let _phLbStreakTab = "longest";   // "longest" (best ever) | "current" (live run)
    // uid → saved best-game snapshot for the currently-rendered Casual board.
    // Repopulated on every Casual render; the delegated score-click reads it to
    // open that player's high-scoring game in the game-detail modal.
    let _phLbBestGames = {};
    // Pick the saved game behind a leaderboard row's score: the Overall tab shows
    // the player's all-time best game; a size tab shows their best game AT that
    // table size. Returns null when nothing worth opening was saved.
    function _phLbBestGameFor(d, size) {
      const st = (d && d.stats) || {};
      let bg = null;
      if (size === "all") {
        bg = st.best_game || null;
      } else {
        const m = st.best_game_by_size;
        if (m && typeof m === "object") bg = m[String(size)] || null;
      }
      if (!bg || typeof bg !== "object") return null;
      const hasBoards = Array.isArray(bg.bds) && bg.bds.length > 0;
      const hasScores = Array.isArray(bg.all) && bg.all.length > 0;
      return (hasBoards || hasScores) ? bg : null;
    }
    // Cache of friend UIDs so add-friend cells render instantly (refreshed each open).
    let _lbFriendUids = new Set();
    // Which account the set above belongs to, and when it was read. The friend
    // list only decides whether a leaderboard row shows an "add friend"
    // button, so after the first read it must never hold a board up again:
    // it is refreshed behind the draw instead. Keyed by uid so signing in as
    // somebody else can never inherit the last account's friends.
    let _lbFriendUidsFor = "";
    let _lbFriendUidsAt  = 0;

    /* ── helpers ── */
    function escHtmlPH(s) {
      return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    }
    function phLbAvatarImg(avatarUrl, seed, bgUrl) {
      const raw   = typeof normalizeAvatarUrl === "function" ? normalizeAvatarUrl(avatarUrl || "") : (avatarUrl || "");
      // Only use a stored avatar if it's a real, known avatar, otherwise an
      // invalid value (e.g. an old "/avatars/avatar-04.png") 404s. Fall back
      // to the default mullet. The onerror is a last-resort safety net.
      const valid = (raw && typeof animalByImg === "function" && animalByImg(raw)) ? raw : "";
      const final = valid || (typeof getDefaultAvatar === "function" ? getDefaultAvatar(seed) : "/avatars/mullet.png");
      // Equipped background paints behind the transparent avatar art (no wrapper
      // needed, the <img>'s own background-image shows through transparent pixels).
      let bgn = ""; try { bgn = normalizeBgUrl(bgUrl || ""); if (!_BG_BY_IMG[bgn]) bgn = ""; } catch {}
      const bgStyle = bgn ? ` style="${_bgStyle(bgn)}"` : "";
      return `<img class="ph-lb-avatar" src="${escHtmlPH(_avSrc(final))}" alt="" loading="lazy"${bgStyle} onerror="this.src='/avatars/mullet.png'">`;
    }
    // Returns the HTML for the add-friend cell on a leaderboard row.
    // SVG icons for the leaderboard add-friend cell
    const _LB_ICON_ADD = `<svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true"><circle cx="5.5" cy="4.5" r="3" stroke="currentColor" stroke-width="1.5"/><path d="M0 13c0-3.038 2.462-5.5 5.5-5.5 1.18 0 2.27.372 3.17.998" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" fill="none"/><path d="M11 8v5M8.5 10.5h5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>`;
    const _LB_ICON_FRIENDS = `<svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden="true"><circle cx="5.5" cy="4.5" r="3" stroke="currentColor" stroke-width="1.5"/><path d="M0 13c0-3.038 2.462-5.5 5.5-5.5S11 9.962 11 13" stroke="currentColor" stroke-width="1.5" fill="none"/><path d="M9 8l1.5 1.5L13 7" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    function phLbAddCell(uid, isMe) {
      if (!_authUser || isMe) return `<td class="ph-lb-add-cell"></td>`;
      if (_lbFriendUids.has(uid)) {
        return `<td class="ph-lb-add-cell"><button class="ph-lb-add-btn lb-add-friends" title="Already friends" disabled>${_LB_ICON_FRIENDS}</button></td>`;
      }
      return `<td class="ph-lb-add-cell"><button class="ph-lb-add-btn" data-add-uid="${escHtmlPH(uid)}" title="Add friend">${_LB_ICON_ADD}</button></td>`;
    }
    function phLbRankTitle(cp) {
      const fn = typeof window._compGetRankFromCp === "function" ? window._compGetRankFromCp : null;
      return fn ? fn(Number(cp)||0).division : "-";
    }
    function phLbMedal(n) {
      return n===1?"🥇":n===2?"🥈":n===3?"🥉":`<span style="color:#8aaccc;font-weight:700;">#${n}</span>`;
    }
    function phLbRankClass(n) {
      return n===1?" rank-1":n===2?" rank-2":n===3?" rank-3":"";
    }
    function phLbSizeField(size) {
      // Overall tab ranks by the balanced (player-count-fair) average score;
      // per-size tabs rank by best score for that size.
      return size === "all" ? "stats.balanced_avg_score" : `stats.highest_score_${size}p`;
    }
    function phLbSizeLabel(size) {
      return size === "all" ? "Overall" : `${size}P`;
    }
    // "Your rank" cards are the one place a leaderboard says YOU. They are
    // painted by whichever board last drew and then simply left there, so the
    // previous session's rank card survived a change of person and sat above
    // a guest's boards reading "#1 · Level 99 · 249,800 XP". Hidden and
    // emptied whenever the session changes hands, and again before every
    // board redraws, so a card on screen always belongs to whoever is looking.
    function phLbClearSumCards() {
      document.querySelectorAll("#ph-panel-leaderboard .ph-lb-summary").forEach(card => {
        card.style.display = "none";
        const rank = card.querySelector(".ph-lb-sum-rank");
        if (rank) { rank.textContent = "-"; rank.className = "ph-lb-sum-rank"; }
        const vals = card.querySelector(".ph-lb-sum-vals");
        if (vals) vals.innerHTML = "";
      });
    }

    function phLbSetSumCard(id, rankId, valsId, show, rankNum, vals) {
      const card = $a(id);
      if (!card) return;
      card.style.display = show ? "" : "none";
      if (!show) return;
      const rankEl = $a(rankId);
      if (rankEl) {
        rankEl.textContent = rankNum ? `#${rankNum}` : "-";
        rankEl.className = "ph-lb-sum-rank" + phLbRankClass(rankNum);
      }
      const valsEl = $a(valsId);
      if (valsEl) valsEl.innerHTML = vals;
    }

    /* ── mode / tab switches ── */
    window.phLbSwitchMode = function(mode) {
      _phLbMode = mode;
      const sectionMap = { xp:"xp", casual:"casual", competitive:"comp", wins:"wins", streak:"streak", tourney:"tourney" };
      const btnMap     = { xp:"xp", casual:"casual", competitive:"comp", wins:"wins", streak:"streak", tourney:"tourney" };
      Object.entries(sectionMap).forEach(([m, sec]) => {
        const btn = $a(`ph-lb-${btnMap[m]}-btn`);
        const el  = $a(`ph-lb-${sec}-section`);
        if (btn) btn.classList.toggle("active", m === mode);
        if (el)  el.style.display = m === mode ? "" : "none";
      });
      renderPhLeaderboard();
    };

    window.phLbSetSize = function(size, btn) {
      _phLbSize = size;
      const row = $a("ph-lb-casual-section");
      if (row) row.querySelectorAll(".ph-lb-size-btn").forEach(b => b.classList.toggle("active", b===btn));
      renderPhLeaderboard();
    };

    // Streak board toggle: "longest" (best run ever) vs "current" (live run).
    // Same rows either way, different ranking metric + column headers.
    window.phLbSwitchStreakTab = function(tab, btn) {
      _phLbStreakTab = (tab === "current") ? "current" : "longest";
      ["longest","current"].forEach(t => {
        const b = $a(`ph-lb-streak-${t}-tab`);
        if (b) b.classList.toggle("active", t === _phLbStreakTab);
      });
      renderPhLeaderboard();
    };

    window.phLbSwitchCompTab = function(tab, btn) {
      _phLbCompTab = tab;
      ["cp","single","combined"].forEach(t => {
        const b = $a(`ph-lb-${t}-tab`);
        const s = $a(`ph-lb-${t}-section`);
        if (b) b.classList.toggle("active", t===tab);
        if (s) s.style.display = t===tab ? "" : "none";
      });
      renderPhLeaderboard();
    };

    /* ── main render ── */
    // ── One query behind every board ────────────────────────────────────
    // Each board is "the top N user docs by one stats field". A signed-in
    // player runs that against Firestore. A GUEST holds no Firebase session,
    // and the users collection is not readable without one, so every board
    // used to come back permission-denied: the whole Leaderboard tab read
    // "Could not load", which is how a guest was locked out of the boards
    // without a single padlock being drawn. The server can read it with the
    // service account, so a guest is served the same rows through
    // /api/leaderboard and the renderers below never learn the difference.
    //
    // Returns Firestore-shaped docs ({ id, data() }) either way.
    async function lbTopUsers(field, limit) {
      const n = Math.max(1, Math.min(150, Number(limit) || 50));
      if (_db && _authUser) {
        const snap = await _db.collection("users").orderBy(field, "desc").limit(n).get({ source: "server" });
        return snap.docs;
      }
      const res = await apiFetch(`/api/leaderboard?board=${encodeURIComponent(field)}&limit=${n}`,
                                 { method: "GET", timeoutMs: 8000 });
      const rows = res && res.ok && res.data && Array.isArray(res.data.rows) ? res.data.rows : null;
      if (!rows) throw new Error("leaderboard unavailable");
      return rows.map(r => ({ id: String(r.id || ""), data: () => r }));
    }

    // ── Boards open instantly, then correct themselves ──────────────────────
    // Every board is one ordered query, and the tab used to run it and then
    // sit on "Loading…" until it landed: measured at 4.4 seconds to open
    // Leaderboard cold. The rows a player saw a minute ago are still very
    // nearly the right rows, so they go back up IMMEDIATELY and the real query
    // runs behind them; when it lands the board redraws itself, but only if
    // the player is still looking at that board. Only the first open of a
    // board in a session ever waits for anything.
    //
    // Signed-in and guest rows come from different sources (Firestore docs vs
    // the server's trimmed rows), so they are cached under separate keys and a
    // sign-in can never hand somebody the other one's shape.
    const _lbSnapshot   = new Map();          // key → { docs, at }
    const _lbRefreshing = new Set();
    const LB_SNAP_TTL_MS = 60 * 1000;         // how long a snapshot is used as-is

    function _lbSnapKey(field, limit) {
      return `${_db && _authUser ? "acct" : "guest"}|${field}|${limit}`;
    }
    function _lbPanelOnScreen() {
      const el = $a("ph-panel-leaderboard");
      return !!(el && el.style.display !== "none" && el.offsetParent !== null);
    }

    async function lbTopUsersWarm(field, limit) {
      const key  = _lbSnapKey(field, limit);
      const snap = _lbSnapshot.get(key);
      if (!snap) {                            // never seen: this one has to wait
        const docs = await lbTopUsers(field, limit);
        _lbSnapshot.set(key, { docs, at: Date.now() });
        return docs;
      }
      if (Date.now() - snap.at >= LB_SNAP_TTL_MS && !_lbRefreshing.has(key)) {
        _lbRefreshing.add(key);
        // Remember which board asked, so a refresh that lands after the player
        // has switched modes (or left the tab) never redraws over them.
        const mode = _phLbMode, comp = _phLbCompTab, size = _phLbSize;
        lbTopUsers(field, limit).then(docs => {
          _lbSnapshot.set(key, { docs, at: Date.now() });
          if (_lbPanelOnScreen() && _phLbMode === mode
              && _phLbCompTab === comp && _phLbSize === size) renderPhLeaderboard();
        }).catch(() => {}).finally(() => _lbRefreshing.delete(key));
      }
      return snap.docs;                       // instant, and correct within a minute
    }

    async function _lbRefreshFriendUids() {
      const uid = _authUser && _authUser.uid;
      if (!uid) return;
      const read = () => loadFriends(uid)
        .then(fl => { _lbFriendUids = new Set(fl.map(f => f.uid));
                      _lbFriendUidsFor = uid; _lbFriendUidsAt = Date.now(); })
        .catch(() => { _lbFriendUidsFor = uid; _lbFriendUidsAt = Date.now(); });
      if (_lbFriendUidsFor !== uid) { _lbFriendUids = new Set(); return read(); }
      if (Date.now() - _lbFriendUidsAt > 60000) read();   // behind the draw
    }

    async function renderPhLeaderboard() {
      // No _db check any more: a guest never has one, and lbTopUsers() serves
      // them the same rows from the server. Bailing out here is what left the
      // whole tab reading "Loading…" for ever.
      phLbClearSumCards();
      // Refresh friend UIDs so add-friend cells are accurate. Only the first
      // read of a session is waited for; later ones land behind the board.
      if (_authUser) await _lbRefreshFriendUids();
      if      (_phLbMode === "xp")           await _phLbRenderXp();
      else if (_phLbMode === "casual")       await _phLbRenderCasual();
      else if (_phLbMode === "wins")         await _phLbRenderWins();
      else if (_phLbMode === "streak")       await _phLbRenderStreak();
      else if (_phLbMode === "tourney")      await _phLbRenderTourney();
      else {
        if      (_phLbCompTab === "cp")       await _phLbRenderCp();
        else if (_phLbCompTab === "single")   await _phLbRenderSingle();
        else if (_phLbCompTab === "combined") await _phLbRenderCombined();
      }
      // Paint Prestige badges + name colours onto whichever board just drew.
      try { window.__ccRefreshNames?.(); } catch (_) {}
    }

    async function _phLbRenderXp() {
      const tbody = $a("ph-lb-xp-tbody");
      if (!tbody) return;
      tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Loading…</td></tr>`;
      try {
        // Fetch by total_xp; fall back to level for accounts that only have level stored.
        // Fetch extra to filter out blank/guest accounts (no nickname or 0 XP).
        const docs = await lbTopUsersWarm("stats.total_xp", 50);
        let rows = [], myRank = 0, myRow = null, shown = 0;
        docs.forEach(doc => {
          const d     = doc.data();
          const stats = d.stats || {};
          const nick  = String(d.nickname || "").trim();
          if (!nick || nick.toLowerCase() === "player") return;  // skip blank/guest
          const totalXp = Number(stats.total_xp || 0);
          if (totalXp <= 0) return;
          // Derive level from total_xp, the single source of truth, so the
          // leaderboard always matches the header/profile. A stored stats.level
          // can lag when XP is granted outside a game (e.g. a Supporter-Tier
          // purchase credited server-side by the Stripe webhook).
          const lvl   = getLevelProgressFromTotalXp(totalXp).level;
          const games = Number(stats.completed_games || 0);
          shown++;
          const isMe = !!(_authUser && doc.id === _authUser.uid);
          rows.push({ shown, isMe, lvl, totalXp, games, d, doc });
          if (isMe) { myRank = shown; myRow = { shown, lvl, totalXp, games }; }
        });
        if (!rows.length) {
          tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">No XP data yet.</td></tr>`;
          phLbSetSumCard("ph-lb-xp-summary","ph-lb-xp-rank","ph-lb-xp-sum-vals",false);
          return;
        }
        // Sort: highest level first, then highest XP as tiebreaker.
        rows.sort((a,b) => b.lvl !== a.lvl ? b.lvl - a.lvl : b.totalXp - a.totalXp);
        // Re-assign ranks and find my rank after sort (handles ties correctly, same rank for same level+XP).
        let rank = 0, prevLvl = -1, prevXp = -1;
        rows.forEach(r => {
          if (r.lvl !== prevLvl || r.totalXp !== prevXp) { rank = r.shown; prevLvl = r.lvl; prevXp = r.totalXp; }
          r.rank = rank;
          if (r.isMe) { myRank = rank; myRow = { rank, lvl: r.lvl, totalXp: r.totalXp, games: r.games }; }
        });
        tbody.innerHTML = rows.map(r => {
          const av  = phLbAvatarImg(r.d.avatar_url, r.d.nickname || r.doc.id, r.d.background_url);
          const meC = r.isMe ? " ph-lb-me" : "";
          const you = r.isMe ? `<span class="ph-lb-you-tag">you</span>` : "";
          const sc  = r.rank===1 ? ' ph-lb-score-cell lb-top' : ' ph-lb-score-cell';
          return `<tr class="${meC}" data-uid="${escHtmlPH(r.doc.id)}">
            <td class="ph-lb-rank-cell">${phLbMedal(r.rank)}</td>
            <td><div class="ph-lb-player-cell pub-clickable">${av}<span class="ph-lb-pname" data-cc-pname="${escHtmlPH(r.doc.id)}">${escHtmlPH(r.d.nickname||"Unknown")}</span>${you}</div></td>
            <td class="${sc.trim()}">${escHtmlPH("Lv. " + r.lvl)}</td>
            <td class="ph-lb-score-cell">${r.totalXp.toLocaleString()} XP</td>
            <td class="ph-lb-meta-cell">${r.games.toLocaleString()}</td>
          ${phLbAddCell(r.doc.id, r.isMe)}</tr>`;
        }).join("");
        if (myRow) {
          const v = `<div class="ph-lb-sum-val"><span>Level</span> ${myRow.lvl}</div>
            <div class="ph-lb-sum-val"><span>Total XP</span> ${myRow.totalXp.toLocaleString()} XP</div>
            <div class="ph-lb-sum-val"><span>Games</span> ${myRow.games.toLocaleString()}</div>`;
          phLbSetSumCard("ph-lb-xp-summary","ph-lb-xp-rank","ph-lb-xp-sum-vals",true,myRank,v);
        } else {
          phLbSetSumCard("ph-lb-xp-summary","ph-lb-xp-rank","ph-lb-xp-sum-vals",false);
        }
      } catch(e) {
        console.error("[LB] XP leaderboard error:", e);
        tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Could not load XP leaderboard.</td></tr>`;
      }
    }

    async function _phLbRenderWins() {
      const tbody = $a("ph-lb-wins-tbody");
      if (!tbody) return;
      tbody.innerHTML = `<tr><td colspan="6" class="ph-lb-empty">Loading…</td></tr>`;
      try {
        // Fetch broadly by normal_wins; we'll add comp wins client-side and re-sort.
        const snap = { docs: await lbTopUsersWarm("stats.normal_wins", 75) };
        let rows = [], myRank = 0, myRow = null, shown = 0;
        snap.docs.forEach(doc => {
          const d     = doc.data();
          const stats = d.stats || {};
          const nick  = String(d.nickname || "").trim();
          if (!nick || nick.toLowerCase() === "player") return;
          const casualWins = Number(stats.normal_wins || 0);
          const compWins   = Number(stats.competitive_wins || 0);
          const totalWins  = casualWins + compWins;
          if (totalWins <= 0) return;
          const games    = Number(stats.completed_games || 0);
          const winPct   = games > 0 ? Math.round((totalWins / games) * 100) : 0;
          const strat    = escHtmlPH(stats.most_played_strategy || stats.favorite_strategy || "-");
          shown++;
          const isMe = !!(_authUser && doc.id === _authUser.uid);
          rows.push({ shown, isMe, totalWins, casualWins, compWins, games, winPct, strat, d, doc });
          if (isMe) { myRank = shown; myRow = { shown, totalWins, casualWins, compWins, games, winPct, strat }; }
        });
        if (!rows.length) {
          tbody.innerHTML = `<tr><td colspan="6" class="ph-lb-empty">No win data yet.</td></tr>`;
          phLbSetSumCard("ph-lb-wins-summary","ph-lb-wins-rank","ph-lb-wins-sum-vals",false);
          return;
        }
        rows.sort((a,b) => b.totalWins - a.totalWins);
        // Assign tied ranks.
        let rank = 0, prevWins = -1;
        rows.forEach((r,i) => {
          if (r.totalWins !== prevWins) { rank = i + 1; prevWins = r.totalWins; }
          r.rank = rank;
          if (r.isMe) { myRank = rank; myRow = { rank, totalWins: r.totalWins, casualWins: r.casualWins, compWins: r.compWins, games: r.games, winPct: r.winPct, strat: r.strat }; }
        });
        // Show only top 25 after sort.
        rows = rows.slice(0, 25);
        tbody.innerHTML = rows.map(r => {
          const av  = phLbAvatarImg(r.d.avatar_url, r.d.nickname || r.doc.id, r.d.background_url);
          const meC = r.isMe ? " ph-lb-me" : "";
          const you = r.isMe ? `<span class="ph-lb-you-tag">you</span>` : "";
          const sc  = r.rank===1 ? ' ph-lb-score-cell lb-top' : ' ph-lb-score-cell';
          return `<tr class="${meC}" data-uid="${escHtmlPH(r.doc.id)}">
            <td class="ph-lb-rank-cell">${phLbMedal(r.rank)}</td>
            <td><div class="ph-lb-player-cell pub-clickable">${av}<span class="ph-lb-pname" data-cc-pname="${escHtmlPH(r.doc.id)}">${escHtmlPH(r.d.nickname||"Unknown")}</span>${you}</div></td>
            <td class="${sc.trim()}">${r.totalWins.toLocaleString()}</td>
            <td class="ph-lb-meta-cell">${r.winPct}%</td>
            <td class="ph-lb-meta-cell">${r.games.toLocaleString()}</td>
            <td class="ph-lb-meta-cell">${r.strat}</td>
          ${phLbAddCell(r.doc.id, r.isMe)}</tr>`;
        }).join("");
        if (myRow) {
          const v = `<div class="ph-lb-sum-val"><span>Total Wins</span> ${myRow.totalWins.toLocaleString()}</div>
            <div class="ph-lb-sum-val"><span>Casual</span> ${myRow.casualWins.toLocaleString()} · <span>Comp</span> ${myRow.compWins.toLocaleString()}</div>
            <div class="ph-lb-sum-val"><span>Win Rate</span> ${myRow.winPct}%</div>
            <div class="ph-lb-sum-val"><span>Games</span> ${myRow.games.toLocaleString()}</div>
            <div class="ph-lb-sum-val"><span>Strategy</span> ${myRow.strat}</div>`;
          phLbSetSumCard("ph-lb-wins-summary","ph-lb-wins-rank","ph-lb-wins-sum-vals",true,myRank,v);
        } else {
          phLbSetSumCard("ph-lb-wins-summary","ph-lb-wins-rank","ph-lb-wins-sum-vals",false);
        }
      } catch(e) {
        console.error("[LB] Wins leaderboard error:", e);
        tbody.innerHTML = `<tr><td colspan="6" class="ph-lb-empty">Could not load wins leaderboard.</td></tr>`;
      }
    }

    // ── Daily-streak leaderboard ─────────────────────────────────────
    // One table, two rankings behind a toggle: longest streak EVER and longest
    // CURRENT (live) streak. Both numbers are recomputed from stats.streak_days, the
    // single source of truth (see _computeStreakInfo), because the stored
    // stats.daily_streak is only rewritten when a game finishes, a player who
    // stopped playing keeps a stale-high value in their doc, which would
    // otherwise sit at the top of the "current" board forever.
    //
    // Each board fetches by its OWN stored field (one query, same cost as the
    // Wins board: user docs are big, so a second pass over 75 of them is not
    // free). That is sound because recomputing can only LOWER a stored value,
    // never raise it, so the top-N by stored value always contains the true
    // top-N. It relies on stats.streak_days / daily_streak / streak_longest
    // being written TOGETHER (they are, in both writers: the end-of-game save
    // and __fishUseStreakShield), a doc missing the ordered field is dropped
    // by Firestore, so if that invariant is ever broken this board goes blind.
    function _phLbStreakNums(stats) {
      let info = null;
      try {
        if (typeof _computeStreakInfo === "function") info = _computeStreakInfo(stats.streak_days);
        else if (typeof window._computeStreakInfo === "function") info = window._computeStreakInfo(stats.streak_days);
      } catch (_) { info = null; }
      const storedCur  = Number(stats.daily_streak || 0);
      const storedBest = Number(stats.streak_longest || 0);
      // With streak_days present the computed values win for "current" (stale
      // stored values must not rank) and are maxed for "longest" (a best run is
      // never lost). Without it, fall back to whatever the doc stored.
      const current = info ? (Number(info.current) || 0) : storedCur;
      const longest = info ? Math.max(Number(info.longest) || 0, storedBest) : storedBest;
      const days    = info ? (Number(info.total) || 0) : 0;
      return { current, longest, days };
    }

    async function _phLbRenderStreak() {
      const tbody = $a("ph-lb-streak-tbody");
      if (!tbody) return;
      const byCurrent = _phLbStreakTab === "current";
      // Column headers follow the toggle: ranked metric first.
      const thP = $a("ph-lb-streak-th-primary");
      const thS = $a("ph-lb-streak-th-secondary");
      if (thP) thP.textContent = byCurrent ? "Current Streak" : "Longest Streak";
      if (thS) thS.textContent = byCurrent ? "Longest" : "Current";
      const sumTitle = $a("ph-lb-streak-sum-title");
      if (sumTitle) sumTitle.textContent = byCurrent ? "Your Current Streak" : "Your Longest Streak";
      tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Loading…</td></tr>`;
      try {
        const field = byCurrent ? "stats.daily_streak" : "stats.streak_longest";
        const snap = { docs: await lbTopUsersWarm(field, 75) };
        let rows = [];
        snap.docs.forEach(doc => {
          const d     = doc.data();
          const stats = d.stats || {};
          const nick  = String(d.nickname || "").trim();
          if (!nick || nick.toLowerCase() === "player") return;   // skip blank/guest
          const n = _phLbStreakNums(stats);
          // Only rank players who actually have the metric this board is about.
          if ((byCurrent ? n.current : n.longest) <= 0) return;
          rows.push({
            isMe: !!(_authUser && doc.id === _authUser.uid),
            current: n.current, longest: n.longest, days: n.days, d, doc,
          });
        });
        if (!rows.length) {
          tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">${byCurrent ? "Nobody has a streak going right now, start one today!" : "No streak data yet."}</td></tr>`;
          phLbSetSumCard("ph-lb-streak-summary","ph-lb-streak-rank","ph-lb-streak-sum-vals",false);
          return;
        }
        // Rank by the toggled metric, tie-broken by the other one, then by days played.
        const pri = r => byCurrent ? r.current : r.longest;
        const sec = r => byCurrent ? r.longest : r.current;
        rows.sort((a,b) => pri(b) - pri(a) || sec(b) - sec(a) || b.days - a.days);
        // Tied ranks: identical primary AND secondary share a number.
        let rank = 0, prevP = -1, prevS = -1, myRank = 0, myRow = null;
        rows.forEach((r,i) => {
          if (pri(r) !== prevP || sec(r) !== prevS) { rank = i + 1; prevP = pri(r); prevS = sec(r); }
          r.rank = rank;
          if (r.isMe) { myRank = rank; myRow = r; }
        });
        rows = rows.slice(0, 25);
        tbody.innerHTML = rows.map(r => {
          const av  = phLbAvatarImg(r.d.avatar_url, r.d.nickname || r.doc.id, r.d.background_url);
          const meC = r.isMe ? " ph-lb-me" : "";
          const you = r.isMe ? `<span class="ph-lb-you-tag">you</span>` : "";
          const sc  = r.rank===1 ? 'ph-lb-score-cell lb-top' : 'ph-lb-score-cell';
          const p   = pri(r), s = sec(r);
          return `<tr class="${meC}" data-uid="${escHtmlPH(r.doc.id)}">
            <td class="ph-lb-rank-cell">${phLbMedal(r.rank)}</td>
            <td><div class="ph-lb-player-cell pub-clickable">${av}<span class="ph-lb-pname" data-cc-pname="${escHtmlPH(r.doc.id)}">${escHtmlPH(r.d.nickname||"Unknown")}</span>${you}</div></td>
            <td class="${sc}">🔥 ${p.toLocaleString()} day${p === 1 ? "" : "s"}</td>
            <td class="ph-lb-meta-cell">${s.toLocaleString()}</td>
            <td class="ph-lb-meta-cell">${r.days.toLocaleString()}</td>
          ${phLbAddCell(r.doc.id, r.isMe)}</tr>`;
        }).join("");
        // Summary card. If I'm signed in but outside the fetched set, still show
        // my own numbers (rank "-") rather than hiding the card entirely.
        if (!myRow && _authUser) {
          let myStats = null;
          try { myStats = (typeof window.__fishGetMyStats === "function") ? window.__fishGetMyStats() : null; } catch (_) {}
          if (myStats) { const n = _phLbStreakNums(myStats); myRank = 0; myRow = { current: n.current, longest: n.longest, days: n.days }; }
        }
        if (myRow) {
          const v = `<div class="ph-lb-sum-val"><span>Current</span> ${Number(myRow.current||0).toLocaleString()} day${Number(myRow.current||0) === 1 ? "" : "s"}</div>
            <div class="ph-lb-sum-val"><span>Longest</span> ${Number(myRow.longest||0).toLocaleString()} day${Number(myRow.longest||0) === 1 ? "" : "s"}</div>
            <div class="ph-lb-sum-val"><span>Days Played</span> ${Number(myRow.days||0).toLocaleString()}</div>`;
          phLbSetSumCard("ph-lb-streak-summary","ph-lb-streak-rank","ph-lb-streak-sum-vals",true,myRank,v);
        } else {
          phLbSetSumCard("ph-lb-streak-summary","ph-lb-streak-rank","ph-lb-streak-sum-vals",false);
        }
      } catch(e) {
        console.error("[LB] Streak leaderboard error:", e);
        tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Could not load streak leaderboard.</td></tr>`;
      }
    }

    // Tournament champions: ranked by tournament_wins (championships), tie-broken
    // by win rate. Reads the same materialized stats the tournament server writes
    // on finalize (stats.tournament_wins / stats.tournaments_played).
    async function _phLbRenderTourney() {
      const tbody = $a("ph-lb-tourney-tbody");
      if (!tbody) return;
      tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Loading…</td></tr>`;
      try {
        const snap = { docs: await lbTopUsersWarm("stats.tournament_wins", 75) };
        let rows = [], myRank = 0, myRow = null, shown = 0;
        snap.docs.forEach(doc => {
          const d     = doc.data();
          const stats = d.stats || {};
          const nick  = String(d.nickname || "").trim();
          if (!nick || nick.toLowerCase() === "player") return;
          const champs = Number(stats.tournament_wins || 0);
          if (champs <= 0) return;
          const played = Number(stats.tournaments_played || 0);
          const winPct = played > 0 ? Math.round((champs / played) * 100) : 0;
          shown++;
          const isMe = !!(_authUser && doc.id === _authUser.uid);
          rows.push({ shown, isMe, champs, played, winPct, d, doc });
          if (isMe) { myRank = shown; myRow = { shown, champs, played, winPct }; }
        });
        if (!rows.length) {
          tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">No tournament champions yet, be the first!</td></tr>`;
          phLbSetSumCard("ph-lb-tourney-summary","ph-lb-tourney-rank","ph-lb-tourney-sum-vals",false);
          return;
        }
        rows.sort((a,b) => b.champs !== a.champs ? b.champs - a.champs : b.winPct - a.winPct);
        // Assign tied ranks (same championships + win rate share a rank).
        let rank = 0, prevC = -1, prevP = -1;
        rows.forEach((r,i) => {
          if (r.champs !== prevC || r.winPct !== prevP) { rank = i + 1; prevC = r.champs; prevP = r.winPct; }
          r.rank = rank;
          if (r.isMe) { myRank = rank; myRow = { rank, champs: r.champs, played: r.played, winPct: r.winPct }; }
        });
        rows = rows.slice(0, 25);
        tbody.innerHTML = rows.map(r => {
          const av  = phLbAvatarImg(r.d.avatar_url, r.d.nickname || r.doc.id, r.d.background_url);
          const meC = r.isMe ? " ph-lb-me" : "";
          const you = r.isMe ? `<span class="ph-lb-you-tag">you</span>` : "";
          const sc  = r.rank===1 ? ' ph-lb-score-cell lb-top' : ' ph-lb-score-cell';
          return `<tr class="${meC}" data-uid="${escHtmlPH(r.doc.id)}">
            <td class="ph-lb-rank-cell">${phLbMedal(r.rank)}</td>
            <td><div class="ph-lb-player-cell pub-clickable">${av}<span class="ph-lb-pname" data-cc-pname="${escHtmlPH(r.doc.id)}">${escHtmlPH(r.d.nickname||"Unknown")}</span>${you}</div></td>
            <td class="${sc.trim()}">🏆 ${r.champs.toLocaleString()}</td>
            <td class="ph-lb-meta-cell">${r.played.toLocaleString()}</td>
            <td class="ph-lb-meta-cell">${r.winPct}%</td>
          ${phLbAddCell(r.doc.id, r.isMe)}</tr>`;
        }).join("");
        if (myRow) {
          const v = `<div class="ph-lb-sum-val"><span>Championships</span> ${myRow.champs.toLocaleString()}</div>
            <div class="ph-lb-sum-val"><span>Played</span> ${myRow.played.toLocaleString()}</div>
            <div class="ph-lb-sum-val"><span>Win Rate</span> ${myRow.winPct}%</div>`;
          phLbSetSumCard("ph-lb-tourney-summary","ph-lb-tourney-rank","ph-lb-tourney-sum-vals",true,myRank,v);
        } else {
          phLbSetSumCard("ph-lb-tourney-summary","ph-lb-tourney-rank","ph-lb-tourney-sum-vals",false);
        }
      } catch(e) {
        console.error("[LB] Tournament leaderboard error:", e);
        tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Could not load tournament leaderboard.</td></tr>`;
      }
    }

    async function _phLbRenderCasual() {
      const tbody = $a("ph-lb-casual-tbody");
      if (!tbody) return;
      _phLbBestGames = {};   // reset the row→saved-game lookup for this render
      tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Loading…</td></tr>`;
      try {
        // Overall tab: fetch a broad set (proxy: total_score) and rank by the
        // client-computed balanced average so existing players appear immediately
        // without needing the materialized field. Size tabs: orderBy best score.
        let candidates;
        if (_phLbSize === "all") {
          const snap = { docs: await lbTopUsersWarm("stats.total_score", 150) };
          candidates = snap.docs
            .map(doc => ({ doc, d: doc.data(), score: balancedAvgFromStats((doc.data()||{}).stats) }))
            .filter(c => c.score > 0)
            .sort((a, b) => b.score - a.score)
            .slice(0, 25);
        } else {
          const field = phLbSizeField(_phLbSize);
          const snap = { docs: await lbTopUsersWarm(field, 25) };
          candidates = snap.docs
            .map(doc => ({ doc, d: doc.data(), score: ((doc.data()||{}).stats || {})[`highest_score_${_phLbSize}p`] || 0 }))
            .filter(c => c.score > 0);
        }
        let rows = [], myRank = 0, myRow = null, shown = 0;
        candidates.forEach(({ doc, d, score }) => {
          const stats = d.stats || {};
          shown++;
          const isMe  = !!(_authUser && doc.id === _authUser.uid);
          // On a specific size tab, show that player's strategy FOR that size;
          // on the Overall tab, show their most-played strategy.
          let stratRaw = stats.most_played_strategy || stats.favorite_strategy || "-";
          if (_phLbSize !== "all") {
            const bs = stats.most_played_strategy_by_size;
            const perSize = bs && typeof bs === "object" ? (bs[String(_phLbSize)] ?? bs[_phLbSize]) : "";
            if (perSize && String(perSize).trim()) stratRaw = String(perSize).trim();
          }
          const strat = escHtmlPH(stratRaw);
          const size  = _phLbSize === "all" ? "All" : `${_phLbSize}P`;
          rows.push({ shown, isMe, score, size, strat, d, doc });
          if (isMe) { myRank = shown; myRow = { shown, score, size, strat }; }
        });
        // Overall tab shows the balanced average; size tabs show best score.
        const scoreUnit  = _phLbSize === "all" ? "avg" : "pts";
        const scoreLabel = _phLbSize === "all" ? "Balanced Avg" : "Best Score";
        if (!rows.length) {
          tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">No scores recorded yet.</td></tr>`;
          phLbSetSumCard("ph-lb-casual-summary","ph-lb-casual-rank","ph-lb-casual-sum-vals",false);
          return;
        }
        tbody.innerHTML = rows.map(r => {
          const av  = phLbAvatarImg(r.d.avatar_url, r.d.nickname || r.doc.id, r.d.background_url);
          const meC = r.isMe ? " ph-lb-me" : "";
          const you = r.isMe ? `<span class="ph-lb-you-tag">you</span>` : "";
          const sc  = r.shown===1 ? ' ph-lb-score-cell lb-top' : '';
          // If this player has a saved game behind this score, remember it and
          // make the score cell a "replay" button that opens the game-detail
          // modal so anyone can see how they built that high score.
          const bg  = _phLbBestGameFor(r.d, _phLbSize);
          let viewCls = "", viewHint = "";
          if (bg) {
            _phLbBestGames[r.doc.id] = bg;
            viewCls  = " ph-lb-score-view";
            viewHint = `<span class="ph-lb-score-replay" aria-hidden="true">▸ replay</span>`;
          }
          return `<tr class="${meC}" data-uid="${escHtmlPH(r.doc.id)}">
            <td class="ph-lb-rank-cell">${phLbMedal(r.shown)}</td>
            <td><div class="ph-lb-player-cell pub-clickable">${av}<span class="ph-lb-pname" data-cc-pname="${escHtmlPH(r.doc.id)}">${escHtmlPH(r.d.nickname||"Unknown")}</span>${you}</div></td>
            <td class="ph-lb-score-cell${sc}${viewCls}"${bg ? ' title="See how this score was built"' : ''}>${r.score.toLocaleString()} ${scoreUnit}${viewHint}</td>
            <td class="ph-lb-meta-cell"><span class="ph-lb-pill">${r.size}</span></td>
            <td class="ph-lb-meta-cell">${r.strat}</td>
          ${phLbAddCell(r.doc.id, r.isMe)}</tr>`;
        }).join("");
        if (myRow) {
          const v = `<div class="ph-lb-sum-val"><span>${scoreLabel}</span> ${myRow.score.toLocaleString()} ${scoreUnit}</div>
            <div class="ph-lb-sum-val"><span>Game Size</span> ${myRow.size}</div>
            <div class="ph-lb-sum-val"><span>Strategy</span> ${myRow.strat}</div>`;
          phLbSetSumCard("ph-lb-casual-summary","ph-lb-casual-rank","ph-lb-casual-sum-vals",true,myRank,v);
        } else {
          phLbSetSumCard("ph-lb-casual-summary","ph-lb-casual-rank","ph-lb-casual-sum-vals",false);
        }
      } catch(e) {
        console.error("[LB] Casual leaderboard error:", e);
        tbody.innerHTML = `<tr><td colspan="5" class="ph-lb-empty">Could not load leaderboard.</td></tr>`;
      }
      // Hidden critter: Johnson's Sea Cucumber on the 4P leaderboard tab only.
      // Orange Tube Sponge moved to 7P stats (the strategy icon cell there).
      try {
        const slot = $a("ph-lb-casual-secret");
        if (slot) {
          slot.innerHTML = "";
          if (_phLbSize === "4" && typeof window.__fishPlaceSecretCritter === "function") {
            window.__fishPlaceSecretCritter("cucumber", slot);
          }
        }
      } catch (_) {}
    }

